INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-CTW-C-123', 'R', 'ctw', 'C', '{"topic":"Business and economics","first":"Brand loyalty is frequently interpreted as evidence that consumers prefer a product, yet it can also arise from habit and convenience.","parts":[{"t":""},{"t":" "},{"t":"A"},{"t":" "},{"t":"shopper"},{"t":" "},{"pre":"","keep":"w","n":2,"post":""},{"t":" "},{"t":"repeatedly"},{"t":" "},{"pre":"","keep":"bu","n":2,"post":""},{"t":" "},{"t":"the"},{"t":" "},{"pre":"","keep":"sa","n":2,"post":""},{"t":" "},{"t":"brand"},{"t":" "},{"pre":"","keep":"m","n":2,"post":""},{"t":" "},{"t":"simply"},{"t":" "},{"pre":"","keep":"ha","n":2,"post":""},{"t":" "},{"t":"stopped"},{"t":" "},{"pre":"","keep":"comp","n":5,"post":""},{"t":" "},{"t":"alternatives."},{"t":" "},{"pre":"","keep":"Comp","n":5,"post":""},{"t":" "},{"t":"sometimes"},{"t":" "},{"pre":"","keep":"exp","n":4,"post":""},{"t":" "},{"t":"this"},{"t":" "},{"pre":"","keep":"tend","n":4,"post":""},{"t":" "},{"t":"by"},{"t":" "},{"pre":"","keep":"mak","n":3,"post":""},{"t":" "},{"t":"small"},{"t":" "},{"t":"changes"},{"t":" "},{"t":"that"},{"t":" "},{"t":"are"},{"t":" "},{"t":"difficult"},{"t":" "},{"t":"to"},{"t":" "},{"t":"notice,"},{"t":" "},{"t":"such"},{"t":" "},{"t":"as"},{"t":" "},{"t":"adjusting"},{"t":" "},{"t":"package"},{"t":" "},{"t":"sizes."},{"t":" "},{"t":"Analysts"},{"t":" "},{"t":"therefore"},{"t":" "},{"t":"distinguish"},{"t":" "},{"t":"genuine"},{"t":" "},{"t":"attachment"},{"t":" "},{"t":"from"},{"t":" "},{"t":"inertia,"},{"t":" "},{"t":"because"},{"t":" "},{"t":"only"},{"t":" "},{"t":"the"},{"t":" "},{"t":"former"},{"t":" "},{"t":"is"},{"t":" "},{"t":"likely"},{"t":" "},{"t":"to"},{"t":" "},{"t":"persist"},{"t":" "},{"t":"when"},{"t":" "},{"t":"a"},{"t":" "},{"t":"competitor"},{"t":" "},{"t":"introduces"},{"t":" "},{"t":"a"},{"t":" "},{"t":"better"},{"t":" "},{"t":"offer."}]}', '["ho","ys","me","ay","ve","aring","anies","loit","ency","ing"]', '["Полное слово: who","Полное слово: buys","Полное слово: same","Полное слово: may","Полное слово: have","Полное слово: comparing","Полное слово: Companies","Полное слово: exploit","Полное слово: tendency","Полное слово: making"]', '["Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words","Complete the Words"]', 1, 'active', 1793652489836, 1793652489836)
