INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-A-008', 'R', 'rdl', 'A', '{"genre":"menu","doc":{"kind":"table","head":"CAMPUS CAFÉ · TODAY","rows":[["Soup of the day","$4"],["Pasta","$7"],["Soup + bread","$5"]],"foot":"Students get 10% off with a student card."},"qs":[{"type":"Factual","stem":"How much is soup with bread?","opts":["$4","$7","$9","$5"]},{"type":"Factual","stem":"How can students pay less?","opts":["By ordering two meals","By coming early","By paying in cash","By showing a student card"]}]}', '[3,3]', '["В меню: «Soup + bread — $5». $4 — суп без хлеба.","«Students get 10% off with a student card»."]', '["Factual","Factual"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-004', 'R', 'rdl', 'B', '{"genre":"notice","doc":{"kind":"notice","head":"BIKE RACK NOTICE","paras":["Bikes left at the east rack after May 30 will be removed so the area can be repaired. Use the west rack meanwhile. Removed bikes can be collected from Security."]},"qs":[{"type":"Factual","stem":"Why will bikes be removed from the east rack?","opts":["The area will be repaired.","They are parked illegally.","Security needs more space.","The rack is being sold."]},{"type":"Inference","stem":"What will most likely happen to a bike left at the east rack on June 2?","opts":["It will be repaired for free.","It will be moved to the west rack.","It will be taken to Security.","It will be given away."]}]}', '[0,2]', '["«…will be removed so the area can be repaired».","После 30 мая велосипеды уберут, а «Removed bikes can be collected from Security» — значит, велосипед окажется у охраны."]', '["Factual","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-005', 'R', 'rdl', 'B', '{"genre":"chat","doc":{"kind":"chat","msgs":[{"who":"Aisha","time":"3:05 PM","text":"Lab report''s due at 5, not tomorrow. Did you see the email?"},{"who":"Ben","time":"3:07 PM","text":"No! I''ll finish the graphs now. Can you check the conclusion?"},{"who":"Aisha","time":"3:08 PM","text":"Send it over."}]},"qs":[{"type":"Factual","stem":"What did Aisha learn from the email?","opts":["The deadline is earlier than they thought.","The lab is closed tomorrow.","Ben''s graphs are wrong.","The report has been cancelled."]},{"type":"Vocabulary","stem":"What does Aisha mean by \"Send it over\"?","opts":["She will deliver the report herself.","She asks Ben to email the teacher.","She wants Ben to share the conclusion with her.","She refuses to help."],"hlw":"Send it over"}]}', '[0,2]', '["«Lab report''s due at 5, not tomorrow» — срок сдачи сегодня в 5, раньше, чем они думали.","Бен просит проверить вывод, и Айша отвечает «Send it over» — «присылай». Она готова посмотреть текст."]', '["Factual","Vocabulary"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-006', 'R', 'rdl', 'B', '{"genre":"web","doc":{"kind":"notice","head":"Language Café · This Thursday","paras":["Practice Spanish, French, or Japanese with native speakers. Free, no booking — just bring a mug, since we no longer provide paper cups. 6–8 p.m., Student Union, Room 3."]},"qs":[{"type":"Factual","stem":"What should participants bring?","opts":["A booking confirmation","A textbook","Paper cups for everyone","Their own cup"]},{"type":"Inference","stem":"What can be inferred about the Language Café?","opts":["It is only for native speakers.","It charges a small fee.","It meets every evening.","It used to provide paper cups."]}]}', '[3,3]', '["«…just bring a mug, since we no longer provide paper cups».","«We no longer provide paper cups» — раньше стаканчики выдавали. Мероприятие бесплатное, и сказано только про этот четверг."]', '["Factual","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-007', 'R', 'rdl', 'B', '{"genre":"receipt","doc":{"kind":"receipt","head":"QUICKFIX PHONES","meta":"Repair ticket 4471","rows":[["Screen repair","$60"],["Paid","$20"],["Balance","$40"]],"foot":"Ready Wednesday after 2 p.m. Bring this ticket."},"qs":[{"type":"Factual","stem":"How much must the customer still pay?","opts":["$40","$20","$60","$80"]},{"type":"Factual","stem":"When can the phone be collected?","opts":["Wednesday morning","Any time on Tuesday","Wednesday after 2 p.m.","After the balance is paid online"]}]}', '[0,2]', '["«Balance — $40»: ремонт стоит $60, $20 уже оплачено.","«Ready Wednesday after 2 p.m.»"]', '["Factual","Factual"]', 0, 'active', 1793652489836, 1793652489836)
