INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-008', 'R', 'rdl', 'B', '{"genre":"social","doc":{"kind":"post","who":"Green Commons","handle":"@greencommons","paras":["Tree planting moved to Sunday because of storms. Same time, same place. Gloves provided, but bring your own water bottle — we''re going plastic-free!"]},"qs":[{"type":"Factual","stem":"Why was the event moved?","opts":["Storms were expected","Not enough volunteers signed up","The place was unavailable","Gloves did not arrive"]},{"type":"Factual","stem":"What has stayed the same?","opts":["The day of the event","The need to bring gloves","The time and location","The plastic bottles provided"]}]}', '[0,2]', '["«Tree planting moved to Sunday because of storms».","«Same time, same place» — поменялся только день."]', '["Factual","Factual"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-004', 'R', 'rdl', 'C', '{"genre":"notice","doc":{"kind":"notice","head":"RESERVED STUDY ROOMS","paras":["Rooms not claimed within 15 minutes of the booking start are released to walk-in users. Repeated no-shows may lead to a two-week booking suspension."]},"qs":[{"type":"Factual","stem":"What happens if a student arrives 20 minutes after their booking starts?","opts":["The room is kept for the full hour.","The student must pay a fee.","The booking is moved to the next day.","The room may already have been given to someone else."]},{"type":"Vocabulary","stem":"The word \"no-shows\" in the notice refers to","opts":["rooms without windows","students who arrive early","cancelled events","bookings that people do not use"],"hlw":"no-shows"}]}', '[3,3]', '["Если не занять комнату в течение 15 минут, она «released to walk-in users». Через 20 минут её уже могли отдать.","No-show — неявка: человек забронировал комнату и не пришёл."]', '["Factual","Vocabulary"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-005', 'R', 'rdl', 'C', '{"genre":"email","doc":{"kind":"email","from":"Registrar''s Office","to":"All students","subject":"Exam timetable","paras":["The draft exam timetable is now online. Report clashes by March 3; after that, changes will be considered only for documented emergencies."]},"qs":[{"type":"Factual","stem":"What should a student with two exams at the same time do?","opts":["Report the clash by March 3","Wait for the final timetable","Choose one exam to skip","Ask a classmate to change exams"]},{"type":"Inference","stem":"What is suggested about requests made after March 3?","opts":["They will always be accepted.","They must be made in person.","They need evidence of an emergency.","They are free of charge."]}]}', '[0,2]', '["«Report clashes by March 3». Clash — накладка: два экзамена в одно время.","После 3 марта изменения рассматривают «only for documented emergencies» — нужна подтверждённая чрезвычайная ситуация."]', '["Factual","Inference"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-006', 'R', 'rdl', 'C', '{"genre":"chat","doc":{"kind":"chat","msgs":[{"who":"Theo","time":"9:12 PM","text":"Landlord says the heating fix is Friday, but only if someone''s home to let them in."},{"who":"Mara","time":"9:15 PM","text":"I''ve got lectures all day. Could you swap your shift?"},{"who":"Theo","time":"9:16 PM","text":"I''ll ask. Otherwise it''s next week."}]},"qs":[{"type":"Factual","stem":"What condition must be met for the repair to happen on Friday?","opts":["Someone must be at home.","The landlord must pay first.","Mara must cancel her lectures.","The heating must be turned off."]},{"type":"Inference","stem":"What will most likely happen if Theo cannot change his shift?","opts":["Mara will miss her lectures.","The landlord will enter without them.","The repair will be delayed until next week.","They will fix the heating themselves."]}]}', '[0,2]', '["«…only if someone''s home to let them in».","«I''ll ask. Otherwise it''s next week» — если смену поменять не выйдет, ремонт перенесут на следующую неделю."]', '["Factual","Inference"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-007', 'R', 'rdl', 'C', '{"genre":"notice","doc":{"kind":"notice","head":"FREE FLU VACCINATIONS","paras":["Walk-in clinic, Health Centre, Oct 10–14. Bring your student ID. Those with appointments are seen first; walk-in waiting times may exceed an hour at midday."]},"qs":[{"type":"Inference","stem":"Which student is likely to wait the least?","opts":["A walk-in student arriving at noon","A student without an ID","A walk-in student on October 15","A student with an appointment"]},{"type":"Vocabulary","stem":"The word \"exceed\" in the notice is closest in meaning to","opts":["be shorter than","be equal to","be counted as","be longer than"],"hlw":"exceed"}]}', '[3,3]', '["«Those with appointments are seen first» — меньше всех ждёт тот, кто записан. 15 октября клиника уже не работает.","Exceed — превышать: ожидание может быть дольше часа."]', '["Inference","Vocabulary"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-008', 'R', 'rdl', 'C', '{"genre":"social","doc":{"kind":"post","who":"Dana","handle":"Grad Student Network","paras":["Selling last year''s statistics textbook, $25. Note: the course switched editions, so check your syllabus before messaging — the old one won''t match the assigned page numbers."]},"qs":[{"type":"Factual","stem":"Why does Dana tell buyers to check their syllabus?","opts":["The course now uses a different edition.","The book is damaged.","The price has changed.","The book is for a different course."]},{"type":"Inference","stem":"Who would most likely find Dana''s book useful?","opts":["A student who needs the new edition","A student who wants the assigned page numbers to match the new edition","A student whose course still uses last year''s edition","A teacher writing a new syllabus"]}]}', '[0,2]', '["«The course switched editions… the old one won''t match the assigned page numbers».","Книга — прошлогоднее издание, поэтому подойдёт тому, у кого в программе это издание."]', '["Factual","Inference"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-A-201', 'R', 'rdl', 'A', '{"genre":"menu","doc":{"kind":"table","head":"Green Leaf Café — Lunch Menu · Served 11:30 a.m.–2:30 p.m.","rows":[["Vegetable soup","$4"],["Chicken sandwich","$7"],["Garden salad","$5"],["Lemonade","$2"],["Lunch combo: any sandwich + any drink","$8"]],"foot":"Students show their ID and get 10% off the total price. Soup is not included in the combo. Please order at the counter."},"qs":[{"type":"Factual","stem":"A student orders the lunch combo with a chicken sandwich and a lemonade. How much does she pay?","opts":["$9.00","$7.20","$8.00","$7.00"]},{"type":"Factual","stem":"What does the menu say about soup?","opts":["It is free for students.","It is served only after 2:30.","It costs the same as a salad.","It is not part of the combo."]}]}', '[1,3]', '["Комбо стоит $8, скидка студента 10% от общей суммы: 8 − 0,80 = $7,20. Вариант $9 — это сэндвич и лимонад по отдельности.","«Soup is not included in the combo» — суп в комбо не входит. Суп стоит $4, салат $5."]', '["Factual","Factual"]', -1, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-202', 'R', 'rdl', 'B', '{"genre":"form","doc":{"kind":"table","head":"WESTSIDE CHESS CLUB — MEMBERSHIP FORM","rows":[["Name","____________"],["Student ID","____________"],["Playing level","Beginner / Intermediate / Advanced (circle one)"],["Fee","$15 per semester, paid by cash or card at the first meeting"]],"foot":"Members receive a free club T-shirt and may join the spring tournament. The club meets on Tuesdays from 6 to 8 p.m. in Room 214. If you cannot attend regularly, tell the organizer, because boards are limited and new members are waiting. Forms must be returned before the end of the first week."},"qs":[{"type":"Factual","stem":"When must the completed form be returned?","opts":["Before the end of the first week","At the first meeting","On the day of the tournament","After paying the fee"]},{"type":"Inference","stem":"Why does the club ask members to tell the organizer if they cannot attend regularly?","opts":["Members who miss meetings pay a higher fee.","The organizer must change the meeting room.","Other students may be able to use the boards.","The T-shirts are given only to regular members."]},{"type":"Vocabulary","stem":"The word \"limited\" in the notice is closest in meaning to","opts":["very expensive","restricted in number","old and damaged","available only to advanced players"],"hlw":"limited"}]}', '[0,2,1]', '["Последнее предложение: «Forms must be returned before the end of the first week». Оплата идёт на первой встрече, но это другое требование.","Доски ограничены, и новые участники ждут — значит, место можно отдать другим. Остальные причины в форме не названы.","Boards are limited — досок мало, их количество ограничено. Контекст — новые участники ждут своей очереди."]', '["Factual","Inference","Vocabulary"]', 0, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-A-203', 'R', 'rdl', 'A', '{"genre":"schedule","doc":{"kind":"table","head":"Campus Shuttle — Weekday Times","rows":[["Library → Dormitories","every 20 minutes, 7:00 a.m.–11:00 p.m."],["Dormitories → Science Building","every 30 minutes, 7:30 a.m.–6:00 p.m."],["Science Building → Library","every 30 minutes, 8:00 a.m.–6:00 p.m."]],"foot":"There is no shuttle service on weekends. During exam week, the Library route runs until 1:00 a.m."},"qs":[{"type":"Factual","stem":"A student wants to go from the dormitories to the Science Building at 7:00 p.m. on a Wednesday. What is true?","opts":["The shuttle comes every 20 minutes.","The shuttle goes through the library.","The shuttle runs only in exam week.","There is no shuttle at that time."]},{"type":"Inference","stem":"What is suggested about exam week?","opts":["Students may study in the library late at night.","The shuttle is free for everyone.","There are no classes in the Science Building.","The shuttle also runs on weekends."]}]}', '[3,0]', '["Маршрут Dormitories → Science Building заканчивается в 18:00, поэтому в 19:00 автобуса нет.","В неделю экзаменов маршрут от библиотеки идёт до 1:00 — значит, студенты остаются в библиотеке допоздна. О выходных в этот период ничего не сказано."]', '["Factual","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-204', 'R', 'rdl', 'B', '{"genre":"menu","doc":{"kind":"table","head":"Salsa Wagon — Food Truck · Open 11 a.m.–3 p.m.","rows":[["Beef taco","$3.50"],["Bean taco (vegetarian)","$3"],["Rice bowl","$8"],["Chips and salsa","$2.50"],["Any 3 tacos + chips","$11"]],"foot":"Each taco is served in a small corn tortilla. Gluten-free bowls are available on request. We accept cash only on Fridays because the card machine is serviced. Customers who bring their own container receive 50 cents off any bowl."},"qs":[{"type":"Factual","stem":"How much does a customer save by buying three bean tacos and chips as the combo instead of separately?","opts":["$1.00","$1.50","$0.50","$2.00"]},{"type":"Factual","stem":"What should a customer who wants to pay by card remember?","opts":["Cards are accepted only for bowls.","Cards cannot be used on Fridays.","Cards are accepted after 2 p.m.","Cards cost an extra 50 cents."]},{"type":"Inference","stem":"Who would most likely receive the 50-cent discount?","opts":["A customer who eats a taco at the truck","A customer who orders gluten-free chips","A customer who buys the combo on a Friday","A customer who brings a reusable box for a rice bowl"]}]}', '[2,1,3]', '["Отдельно: 3 × $3 + $2,50 = $11,50. Комбо — $11. Экономия $0,50.","«We accept cash only on Fridays» — по пятницам только наличные, потому что обслуживают терминал.","Скидка 50 центов даётся тем, кто приносит свой контейнер и берёт любую порцию в миске (bowl)."]', '["Factual","Factual","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-205', 'R', 'rdl', 'C', '{"genre":"form","doc":{"kind":"table","head":"LIBRARY ROOM BOOKING — GROUP STUDY ROOMS","rows":[["Group size","Three to six people"],["Booking length","Up to two hours; extendable once if no one is waiting"],["Advance booking","Up to seven days ahead, online only"],["Cancellation","At least two hours before the start time"]],"foot":"Rooms that are not occupied within fifteen minutes of the start time will be released to other students. Repeated late cancellations may result in a one-week suspension of booking privileges. Food is not permitted, although covered drinks are acceptable. Whiteboard markers can be borrowed at the front desk with a student card."},"qs":[{"type":"Factual","stem":"What happens if a group does not arrive within fifteen minutes?","opts":["The room may be given to other students.","The group must pay a fee.","The booking is moved to the next day.","The group loses access to the library."]},{"type":"Inference","stem":"Why does the library require cancellations at least two hours in advance?","opts":["To protect the whiteboards","To reduce the cost of electricity","To let other students use the room","To limit the number of groups"]},{"type":"Negative Factual","stem":"All of the following are stated about booking EXCEPT:","opts":["A group needs at least three people.","Bookings can be made at the front desk.","A booking can sometimes be extended.","Bookings can be made a week ahead."]}]}', '[0,2,1]', '["«Released to other students» — комнату отдадут другим. Отстранение грозит за повторные поздние отмены, а не за опоздание.","Правило нужно, чтобы освободившуюся комнату успели занять другие. Прямо это не сказано, но следует из логики: комнаты освобождаются для других студентов.","Бронирование возможно «online only», у стойки нельзя. Остальные утверждения есть в форме."]', '["Factual","Inference","Negative Factual"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-B-206', 'R', 'rdl', 'B', '{"genre":"schedule","doc":{"kind":"table","head":"Writing Center Workshops · Fall Semester","rows":[["Monday 3:00 p.m. — Thesis Statements","Room 105"],["Wednesday 4:00 p.m. — Using Sources","Room 105"],["Thursday 3:00 p.m. — Editing Your Draft","Room 220 (moved from Room 105)"]],"foot":"Each workshop lasts 50 minutes. Seats are limited to 20, so register online at least a day before. Students who attend three workshops receive a certificate that some instructors accept as extra credit."},"qs":[{"type":"Factual","stem":"Where will the workshop on editing take place?","opts":["Room 105","The Writing Center office","Online","Room 220"]},{"type":"Factual","stem":"Why should students register at least a day before a workshop?","opts":["Only twenty seats are available.","The rooms are changed every day.","The workshops are canceled without registration.","Instructors must approve each student."]},{"type":"Inference","stem":"What can be inferred about the certificate?","opts":["Every instructor gives extra credit for it.","It is required to graduate.","Its value depends on the instructor.","It is given after one workshop."]}]}', '[3,0,2]', '["В расписании: «Room 220 (moved from Room 105)» — аудитория изменена на 220.","Seats are limited to 20 — мест 20, поэтому нужна регистрация заранее.","«Some instructors accept» — только некоторые преподаватели засчитывают сертификат, значит, польза зависит от конкретного преподавателя."]', '["Factual","Factual","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-C-207', 'R', 'rdl', 'C', '{"genre":"form","doc":{"kind":"table","head":"EXAM ACCOMMODATION REQUEST","rows":[["Student name and ID","____________"],["Course and exam date","____________"],["Accommodation requested","Extra time / Separate room / Other (explain)"],["Supporting document","Letter from the Student Support Office, attached"]],"foot":"Requests must be submitted at least ten working days before the exam. Late requests will be considered only in emergencies, and approval cannot be guaranteed. Instructors are told about the accommodation but not about the reason for it. Approved students must bring a copy of the confirmation email to the exam."},"qs":[{"type":"Factual","stem":"When must a request be submitted?","opts":["On the day of the exam","At least ten working days before the exam","After the instructor approves it","Within ten days after the exam"]},{"type":"Inference","stem":"What is suggested about late requests?","opts":["They are usually approved quickly.","They are never read by the office.","They must be sent to the instructor.","They might be refused even in an emergency."]},{"type":"Vocabulary","stem":"The word \"guaranteed\" in the form is closest in meaning to","opts":["promised for certain","carefully checked","quickly delivered","paid in advance"],"hlw":"guaranteed"}]}', '[1,3,0]', '["Первое предложение примечания: не позже чем за десять рабочих дней до экзамена.","Позднюю заявку рассматривают только в экстренных случаях, и одобрение не гарантировано, то есть отказ возможен даже тогда.","Approval cannot be guaranteed — одобрение нельзя обещать наверняка. Guaranteed = promised for certain."]', '["Factual","Inference","Vocabulary"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RDL-A-208', 'R', 'rdl', 'A', '{"genre":"schedule","doc":{"kind":"table","head":"Campus Parking Permits","rows":[["Student permit (all year)","$120"],["Student permit (one semester)","$70"],["Visitor pass (one day)","$5"],["Motorcycle permit","$30"]],"foot":"Permits can be bought online or at the Security Office. Parking is free after 6 p.m."},"qs":[{"type":"Factual","stem":"How much does a student save by buying one all-year permit instead of two semester permits?","opts":["$10","$30","$20","$50"]},{"type":"Factual","stem":"Where can a permit be bought?","opts":["Only online","Online or at the Security Office","Only at the Security Office","At any parking space"]}]}', '[2,1]', '["Два семестровых пропуска: 2 × $70 = $140. Годовой стоит $120, экономия $20.","«Online or at the Security Office» — оба способа допустимы."]', '["Factual","Factual"]', -1, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-001', 'R', 'rap', 'A', '{"topic":"Life sciences","title":"The Mystery of the Purr","paras":[["For a long time, scientists believed that cats purred only when they were happy.","It is true that a relaxed cat often purrs while it is being petted or resting in a warm place.","However, researchers have noticed that cats also purr in very different situations."],["Cats sometimes purr when they are injured, when they are giving birth, or even when they are close to death.","These observations suggest that purring is not simply a sign of pleasure.","One theory proposes that the low vibrations of a purr help bones and muscles heal.","Studies have shown that sounds at similar frequencies can make bones stronger in humans."],["Another explanation focuses on communication.","Kittens begin to purr when they are only a few days old, which lets their mother know that they are safe and feeding well.","Adult cats may keep this behavior because it calms both themselves and the people around them.","Scientists still debate which explanation is correct, and it is possible that purring serves several purposes at once."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, what did scientists believe for a long time?","opts":["Cats purred to communicate with people.","Purring showed that a cat was happy.","Only young cats were able to purr.","Purring helped cats stay warm."]},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that gives evidence supporting the healing theory.","sel":{"p":1}},{"type":"Vocabulary","stem":"The word \"proposes\" in the passage is closest in meaning to","opts":["proves","rejects","suggests","describes"],"hl":{"p":1,"s":2,"w":"proposes"}},{"type":"Reference","stem":"The word \"their\" in paragraph 3 refers to","opts":["kittens","scientists","adult cats","people"],"hl":{"p":2,"s":1,"w":"their"}},{"type":"Inference","stem":"What can be inferred about a cat that purrs while it is injured?","opts":["It is probably feeling pleasure.","It may be purring for a reason other than happiness.","It is trying to call its kittens.","It will soon stop purring completely."]}]}', '[1,3,2,0,1]', '["Первое предложение: «scientists believed that cats purred only when they were happy». Верный вариант — перефраз этой мысли.","Теорию о заживлении вводит третье предложение, а доказательство даёт четвёртое: исследования показали, что звуки похожей частоты укрепляют кости у людей. Ищем именно evidence, а не саму теорию.","Theory proposes — теория предполагает. Proves («доказывает») — ловушка: теория ещё не доказана, учёные спорят.","«Kittens begin to purr …, which lets their mother know» — мать котят. Their относится к kittens.","Абзац 2: такие наблюдения показывают, что мурлыканье — не просто знак удовольствия. Значит, раненая кошка мурлычет, скорее всего, по другой причине. Прямо это о конкретной кошке не сказано — это вывод."]', '["Factual","Select the Sentence","Vocabulary","Reference","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-002', 'R', 'rap', 'A', '{"topic":"Business and economics","title":"The Paperback Revolution","paras":[["Until the 1930s, most new books in Britain were sold in hardcover.","They were well made but expensive, so many readers borrowed books from libraries instead of buying them.","Some publishers did print cheap paper editions, but these were usually poorly made and offered light entertainment rather than serious literature."],["In 1935, a publisher named Allen Lane started a company called Penguin.","His idea was simple: he would print serious books with paper covers and sell them for the price of a pack of cigarettes.","Other publishers predicted that the plan would fail.","They believed that cheap books would lower the status of literature and reduce their own profits.","Instead, Penguin sold three million copies in its first year."],["Penguin''s success changed the book trade.","Paperbacks could be sold in railway stations, shops, and newsstands, not only in bookstores.","As a result, reading became a more common activity among working people, who could now afford to build small collections of their own.","Within a few years, other companies had copied the format, and the paperback became a normal part of everyday life."]],"insert":{"p":1,"slots":[1,2,3,5],"sentence":"He is said to have had the idea at a railway station, where he could find nothing good to read for his journey."},"qs":[{"type":"Factual","stem":"According to paragraph 1, why did many readers borrow books from libraries?","opts":["Libraries had more interesting books.","New books were expensive.","Hardcover books were badly made.","Bookstores were far from their homes."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention \"the price of a pack of cigarettes\"?","opts":["To show that Lane also sold cigarettes","To explain how cheap the books were meant to be","To criticize the habits of readers at that time","To compare the quality of books and cigarettes"],"hl":{"p":1,"s":1,"w":"the price of a pack of cigarettes"}},{"type":"Inference","stem":"What can be inferred about other publishers in 1935?","opts":["They did not expect so many people to buy cheap books.","They had already tried selling paperbacks.","They helped Lane start his company.","They lowered the price of hardcover books."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added. Where would the sentence best fit?","insert":true},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following are true of paperbacks EXCEPT:","opts":["They were sold in railway stations.","They helped working people build collections.","They were sold only in bookstores.","They changed the book trade."]}]}', '[1,1,0,0,2]', '["«They were well made but expensive, so many readers borrowed books». Badly made — ловушка: в тексте наоборот, well made.","Вопрос о функции фрагмента: автор сравнивает цену книги с ценой пачки сигарет, чтобы показать, насколько дёшево Лейн собирался продавать книги.","Они предсказывали провал, а Penguin продал три миллиона экземпляров за год. Значит, они недооценили спрос на дешёвые книги.","Вставляемое предложение рассказывает, откуда у Лейна появилась идея. Следующее предложение начинается с «His idea was simple» — оно продолжает тему идеи, поэтому вставка идёт сразу после основания компании, перед ним.","В тексте: «not only in bookstores» — не только в книжных. Вариант «only in bookstores» противоречит тексту."]', '["Factual","Rhetorical Purpose","Inference","Insert Text","Negative Factual"]', -1, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-001', 'R', 'rap', 'B', '{"topic":"Physical sciences","title":"Urban Heat Islands","paras":[["Cities are often several degrees warmer than the countryside around them, a phenomenon known as the urban heat island effect.","Measurements in some large cities have recorded differences of more than ten degrees between downtown streets and nearby farmland.","The difference is usually greatest at night, when rural areas cool quickly but cities continue to release heat."],["Several features of urban environments contribute to this warming.","Dark surfaces such as asphalt roads and rooftops absorb a large share of the sunlight that reaches them and store it as heat.","Tall buildings trap this heat and block the winds that might otherwise carry it away.","In addition, cars, air conditioners, and factories release heat directly into the air."],["The consequences go beyond discomfort.","Higher temperatures increase the demand for air conditioning, which in turn raises energy consumption and, in many places, air pollution.","During heat waves, elderly residents and people without access to cooling face serious health risks.","To address the problem, some cities are painting roofs white, expanding parks, and planting trees along streets, since vegetation cools the air through the evaporation of water from leaves."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, when is the difference in temperature between cities and rural areas greatest?","opts":["In the early morning","During heat waves","At night","In the middle of the day"]},{"type":"Vocabulary","stem":"The word \"trap\" in the passage is closest in meaning to","opts":["create","hold in","reflect","measure"],"hl":{"p":1,"s":2,"w":"trap"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Because people use more air conditioning when it is hot, energy use rises and pollution often increases.","Air conditioning makes cities hotter, which is the main cause of pollution.","Energy consumption and air pollution are the main reasons why cities are hotter.","When pollution increases, people use air conditioning more often in hot weather."],"simp":{"p":2,"s":1}},{"type":"Rhetorical Purpose","stem":"Why does the author mention \"elderly residents\" in paragraph 3?","opts":["To give an example of people for whom heat can be dangerous","To explain why cities use more air conditioning","To show that older people prefer to live in cities","To argue that cities should build more hospitals"],"hl":{"p":2,"s":2,"w":"elderly residents"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 3 that explains how plants reduce temperatures.","sel":{"p":2}}]}', '[2,1,0,0,3]', '["«The difference is usually greatest at night» — ночью: село остывает быстро, а город продолжает отдавать тепло.","Здания «trap this heat and block the winds that might otherwise carry it away» — удерживают тепло, не дают ему уйти. Trap = hold in.","Цепочка в оригинале: жара → больше кондиционеров → больше энергии → часто больше загрязнения. Вариант A сохраняет эту причинно-следственную цепочку. B и C переворачивают причину и следствие, D меняет порядок звеньев.","Абзац говорит о последствиях жары. Пожилые жители — пример тех, для кого жара — серьёзный риск для здоровья. Это функция примера, а не отдельный аргумент.","Последнее предложение: растительность охлаждает воздух за счёт испарения воды с листьев (evaporation of water from leaves)."]', '["Factual","Vocabulary","Sentence Simplification","Rhetorical Purpose","Select the Sentence"]', 0, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-002', 'R', 'rap', 'B', '{"topic":"Business and economics","title":"Why Prices End in 99","paras":[["Walk into almost any store and you will see prices such as $4.99 or $19.99 rather than $5 or $20.","This practice, known as charm pricing, is so common that many shoppers no longer notice it.","Yet economists and psychologists have found that it can have a measurable effect on what people buy."],["The most widely accepted explanation involves the way people read numbers.","Because we read from left to right, the first digit makes the strongest impression.","A price of $2.99 therefore feels closer to $2 than to $3, even though the difference from $3 is only one cent.","In one experiment, a clothing company found that a dress sold more often at $39 than at $34, a price that was actually lower."],["Charm pricing does not work in every situation, however.","Luxury brands often avoid it because they want customers to associate their products with quality rather than bargains.","For them, a round number such as $200 sends a message of confidence and simplicity.","Retailers must therefore decide whether they want a price to look cheap or to look prestigious."]],"qs":[{"type":"Reference","stem":"The word \"it\" in paragraph 1 refers to","opts":["a store","charm pricing","a price of $5","a shopper"],"hl":{"p":0,"s":1,"w":"it"}},{"type":"Factual","stem":"According to paragraph 2, why does $2.99 seem closer to $2 than to $3?","opts":["Shoppers usually round prices down.","The first digit has the strongest effect on the reader.","Stores display the cents in small print.","People cannot calculate small differences."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention the dress that sold more often at $39 than at $34?","opts":["To show that a price ending in 9 can attract buyers even when it is higher","To explain why clothing is more expensive than other goods","To argue that companies should raise their prices","To show that shoppers always choose the lowest price"]},{"type":"Negative Factual","stem":"According to paragraph 3, which of the following is NOT given as a reason luxury brands avoid charm pricing?","opts":["They want their products to be linked with quality.","Round numbers suggest confidence.","Round numbers are easier for cashiers to process.","They do not want to look like bargains."]},{"type":"Inference","stem":"What can be inferred about a shop that prices a watch at $500 instead of $499?","opts":["It probably wants the watch to seem high-quality.","It made a mistake when setting the price.","It expects to sell more watches than its competitors.","It is trying to attract customers looking for bargains."]}]}', '[1,1,0,2,0]', '["«This practice, known as charm pricing, is so common that many shoppers no longer notice it» — покупатели не замечают саму практику, то есть charm pricing.","Мы читаем слева направо, и первая цифра производит самое сильное впечатление (the first digit makes the strongest impression).","Пример с платьем доказывает силу «девятки»: цена $39 продавала лучше, чем более низкая $34. D прямо противоречит примеру.","Про удобство для кассиров в тексте ничего нет. Остальные три причины названы в абзаце 3.","Круглая цена, по тексту, — сигнал качества и уверенности, так делают люксовые бренды. Значит, магазин, скорее всего, хочет, чтобы часы выглядели престижно."]', '["Reference","Factual","Rhetorical Purpose","Negative Factual","Inference"]', 0, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-001', 'R', 'rap', 'C', '{"topic":"Life sciences","title":"How Migrating Birds Find Their Way","paras":[["Each autumn, millions of migratory birds travel thousands of kilometers to wintering grounds they may never have seen before, often flying at night and over open ocean.","How they find their way has puzzled biologists for more than a century."],["Experiments have shown that birds draw on several sources of information.","Some species orient themselves by the position of the sun, compensating for its movement across the sky with an internal clock.","Others learn the patterns of stars that rotate around the North Star, a skill that young birds appear to acquire by watching the night sky before their first migration.","Yet birds kept in windowless rooms still attempt to fly in the correct seasonal direction, which suggests that celestial cues cannot be the whole story."],["The most intriguing candidate is the Earth''s magnetic field.","When researchers placed robins in cages surrounded by artificial magnetic fields, the birds shifted their preferred direction to match the altered field.","Remarkably, this sense appears to depend on light: the response disappeared under certain wavelengths, leading scientists to propose that birds may literally see magnetic fields through specialized molecules in their eyes.","If confirmed, this mechanism would represent one of the most unusual sensory systems known in nature."]],"qs":[{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Birds that cannot see the sky usually fly in the wrong direction during migration.","Celestial cues are the main reason why birds fly in the correct direction each season.","Since birds in rooms without windows still choose the right direction, they must use something besides the sun and stars.","Scientists kept birds in windowless rooms to prevent them from seeing the stars."],"simp":{"p":1,"s":3}},{"type":"Vocabulary","stem":"The word \"intriguing\" in the passage is closest in meaning to","opts":["fascinating","confusing","reliable","obvious"],"hl":{"p":2,"s":0,"w":"intriguing"}},{"type":"Inference","stem":"What can be inferred about young birds before their first migration?","opts":["They already know the position of the North Star from birth.","They need to observe the night sky to learn how to use the stars.","They cannot travel at night.","They follow older birds instead of the stars."]},{"type":"Factual","stem":"According to paragraph 3, what happened when robins were placed in artificial magnetic fields?","opts":["They stopped trying to migrate.","They changed the direction they preferred.","They became unable to see light.","They flew toward the North Star."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention that the response \"disappeared under certain wavelengths\"?","opts":["To show that robins dislike some colors of light","To support the idea that the magnetic sense depends on light","To explain why birds migrate at night","To suggest that the experiment was poorly designed"],"hl":{"p":2,"s":2,"w":"disappeared under certain wavelengths"}}]}', '[2,0,1,1,1]', '["Суть: птицы без доступа к небу всё равно выбирают верное направление → значит, солнце и звёзды — не единственный ориентир. A противоречит оригиналу, B переворачивает вывод, D пересказывает деталь и теряет главное.","Intriguing — интригующий, очень интересный. Confusing — ловушка по созвучию смысла «загадочный», но слово описывает интерес, а не путаницу.","Навык ориентироваться по звёздам молодые птицы, судя по всему, приобретают, наблюдая ночное небо до первой миграции. Значит, это умение не врождённое и требует наблюдения.","«The birds shifted their preferred direction to match the altered field» — сменили предпочтительное направление вслед за изменённым полем.","Факт с длинами волн — доказательство тезиса «this sense appears to depend on light». Вопрос о функции: деталь подкрепляет мысль о связи магнитного чувства со светом."]', '["Sentence Simplification","Vocabulary","Inference","Factual","Rhetorical Purpose"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-002', 'R', 'rap', 'C', '{"topic":"History","title":"From Tokens to Tablets","paras":[["Writing is often described as a sudden invention, but in Mesopotamia it seems to have developed gradually from practical needs.","Long before the first written texts, farmers and traders used small clay tokens of different shapes to keep track of goods such as grain and livestock."],["Around 3500 BCE, officials began sealing these tokens inside hollow clay containers to guarantee that a shipment had not been altered.","Because a sealed container could not be checked without breaking it, they pressed the tokens into its surface before closing it, leaving visible marks.","Eventually, administrators realized that the marks alone were sufficient.","The tokens themselves could be abandoned, and signs drawn on flat clay tablets took their place."],["Over the following centuries, this system of accounting expanded.","Scribes added signs for numbers and for the names of people, and later used symbols to represent sounds as well as objects.","Only at this point could writing record language in general, including stories, laws, and letters.","The earliest writing, in other words, was not designed to preserve literature but to manage an economy."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"In other words, the outside of the container now recorded exactly what was inside."},"qs":[{"type":"Factual","stem":"According to paragraph 1, what were clay tokens used for?","opts":["Decorating containers","Recording quantities of goods","Writing down stories","Paying taxes to officials"]},{"type":"Reference","stem":"The word \"they\" in paragraph 2 refers to","opts":["tokens","containers","officials","shipments"],"hl":{"p":1,"s":1,"w":"they"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added. Where would the sentence best fit?","insert":true},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following were added to the system EXCEPT:","opts":["signs for numbers","names of people","symbols for sounds","maps of trade routes"]},{"type":"Rhetorical Purpose","stem":"How is the passage organized?","opts":["It compares two competing theories about the origin of writing.","It traces how writing gradually developed from an earlier practice.","It describes a problem and explains why the solution failed.","It argues that writing was invented suddenly by one culture."]}]}', '[1,2,1,3,1]', '["Жетоны использовали «to keep track of goods such as grain and livestock» — вести учёт товаров.","Кто вдавливал жетоны в поверхность сосуда? Люди — officials из предыдущего предложения. Tokens — ловушка: это ближайшее существительное во мн. ч., но жетоны сами себя не вдавливают.","«In other words» пересказывает предыдущую мысль: на поверхности сосуда остались отпечатки жетонов — значит, снаружи было видно, что внутри. Поэтому вставка идёт сразу после предложения про отпечатки (visible marks).","Числа, имена и знаки для звуков названы в абзаце 3. Карт торговых путей в тексте нет.","Текст идёт по этапам: жетоны → запечатанные сосуды с отпечатками → таблички → знаки для звуков. Это последовательное развитие. D противоречит первому предложению."]', '["Factual","Reference","Insert Text","Negative Factual","Rhetorical Purpose"]', 1, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-101', 'R', 'rap', 'A', '{"topic":"Life sciences","title":"Seeds on the Move","paras":[["A plant cannot walk to a new home, but its seeds can travel.","This movement helps young plants grow away from the parent plant.","Close to the parent, they may have to share light, water, and space with many other plants.","Seeds that reach a different place sometimes find better conditions.","However, traveling does not guarantee success.","A seed must arrive where the soil, temperature, and water supply allow it to grow."],["Plants move their seeds in several ways.","Some seeds have thin wings or light hairs that help the wind carry them.","Others are inside fruit.","An animal eats the fruit, moves elsewhere, and may leave the seeds behind in its waste.","A third kind has small hooks that attach to an animal''s fur.","The animal carries the seeds until they fall off or are removed.","These methods depend on the shape and covering of the seed."],["There is no single best way to travel.","A windy field may suit a very light seed, while a forest with many fruit-eating animals offers different opportunities.","Water can move seeds too, especially near rivers or coasts.","By comparing seeds from different habitats, scientists can learn how plant reproduction is connected to the movement of air, water, and animals."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["How seeds travel and find growing places","How plants compete only for light","Why all seeds need animal fur","Why forests prevent plant reproduction"]},{"type":"Factual","stem":"What helps some seeds attach to fur?","opts":["A supply of water","A soft fruit center","Small hooks","Thin wings"]},{"type":"Vocabulary","stem":"The word \"guarantee\" in the passage is closest in meaning to","opts":["move toward","make difficult","look for","make certain"],"hl":{"p":0,"s":4,"w":"guarantee"}},{"type":"Rhetorical Purpose","stem":"Why does the author describe a windy field?","opts":["To identify where every seed grows","To compare wind with sunlight","To explain why animals avoid seeds","To show how habitat affects useful dispersal methods"]},{"type":"Inference","stem":"What can be inferred about a seed carried far away?","opts":["It no longer needs water","It will always grow faster than its parent","It must have traveled inside fruit","It may fail to grow in unsuitable conditions"]}]}', '[0,2,3,3,3]', '["Текст о том, как семена перемещаются (ветер, плоды, крючки, вода) и почему им важно попасть в подходящее место. Остальные варианты — частные детали или искажения.","«A third kind has small hooks that attach to an animal''s fur». Крылышки (thin wings) помогают ветру, это другой способ.","Guarantee — гарантировать, сделать что-то несомненным (make certain): «traveling does not guarantee success».","Автор противопоставляет ветреное поле и лес с животными, чтобы показать: выгодный способ распространения зависит от среды.","«Traveling does not guarantee success. A seed must arrive where the soil, temperature, and water supply allow it to grow» — далеко унесённое семя всё равно может не прорасти."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-102', 'R', 'rap', 'A', '{"topic":"Physical sciences","title":"Making Salt from Seawater","paras":[["Seawater contains dissolved salts.","These salts are mixed with the water so closely that they are not usually visible as separate grains.","One way to obtain salt is to place seawater in shallow ponds and let some of the water evaporate.","Evaporation changes liquid water into water vapor, which enters the air.","The dissolved salts remain behind.","As more water leaves, the remaining liquid becomes saltier, and eventually solid salt can form."],["Shallow ponds are useful because a large surface is exposed to the air.","Sunshine supplies energy for evaporation, and moving air can carry water vapor away.","Rain has the opposite effect on salt production: it adds fresh water and can slow the process.","For this reason, a place with many dry, sunny days can be useful for this kind of work.","Workers must still check the ponds and move the liquid between them at appropriate times."],["The solid salt is collected and may be washed or processed before use.","The method demonstrates an important difference between water and what is dissolved in it.","Water can leave as vapor while many dissolved materials stay.","It also shows that a natural process can become a practical production method.","Producers do not need to boil every pond, but they depend on weather and cannot control outdoor conditions completely."]],"qs":[{"type":"Factual","stem":"What does the passage explain?","opts":["Why every salt producer boils water","How evaporation is used to produce salt","Why rain improves salt production","How seawater becomes free of minerals naturally"]},{"type":"Factual","stem":"What happens when water evaporates from a pond?","opts":["The remaining liquid becomes less salty","Sunshine is no longer needed","Dissolved salts stay behind","Salt becomes water vapor"]},{"type":"Vocabulary","stem":"The word \"exposed\" in the passage is closest in meaning to","opts":["removed from use","hidden from view","changed into salt","open to contact"],"hl":{"p":1,"s":0,"w":"exposed"}},{"type":"Rhetorical Purpose","stem":"Why are shallow ponds discussed?","opts":["To explain a design that supports evaporation","To show that seawater has no dissolved salts","To describe ponds used only during rain","To explain how salt changes into air"]},{"type":"Factual","stem":"What limitation does outdoor salt production have?","opts":["It requires constant boiling","It works only when rain is heavy","It cannot produce solid salt","Its progress depends partly on weather"]}]}', '[1,2,3,0,3]', '["Весь текст объясняет, как испарение в мелких прудах используется для добычи соли. Дождь, наоборот, мешает (opposite effect).","«The dissolved salts remain behind». Оставшаяся жидкость становится солонее, а не менее солёной.","Exposed to the air — открыт для контакта с воздухом.","Мелкие пруды обсуждаются как устройство, которое помогает испарению: «a large surface is exposed to the air».","«…they depend on weather and cannot control outdoor conditions completely». Кипятить пруды не нужно: «do not need to boil every pond»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Factual"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-103', 'R', 'rap', 'A', '{"topic":"Art and music","title":"Remembering Music without a Score","paras":[["Music does not always pass from one person to another through writing.","In many communities, people learn songs by listening to experienced singers and joining them.","A learner may first remember the repeated part of a song, then gradually learn the longer verses.","Hearing the words and melody together helps connect the two.","Practice often takes place during ordinary activities or community events rather than in a formal classroom."],["Learning by ear can preserve a song for many years, but it does not require every performance to be identical.","A singer may change a few words to mention a local place or stretch a note to suit a particular occasion.","Other singers may copy that change.","Over time, different versions of a song can develop.","The existence of several versions does not necessarily mean that someone has made a mistake.","Variation may be part of the musical tradition itself."],["Researchers studying these songs listen to more than one performer.","They also ask when the song is used and who is expected to sing it.","A recording captures one performance, not the whole life of a song.","Written notes can help compare melodies, but the social setting matters too.","Studying how people teach, change, and use songs reveals relationships between music and community life that a printed score alone may not show."]],"qs":[{"type":"Factual","stem":"What is the main topic?","opts":["Why traditional songs must remain identical","How all singers learn written scores","Why recordings replace community performances","How songs are learned and changed through listening"]},{"type":"Factual","stem":"What might a new learner remember first?","opts":["The researcher''s written notes","Every local version","The entire longest verse","The repeated part of a song"]},{"type":"Vocabulary","stem":"The word \"variation\" in the passage is closest in meaning to","opts":["complete silence","difference in form","failure to listen","written instruction"],"hl":{"p":1,"s":5,"w":"Variation"}},{"type":"Rhetorical Purpose","stem":"Why does the author mention local place names?","opts":["To show that songs lack social meaning","To give an example of how singers adapt songs","To explain why melodies cannot change","To identify the only correct lyrics"]},{"type":"Inference","stem":"What should a researcher avoid assuming?","opts":["That written notes can aid comparison","That social settings influence performances","That singers can learn by listening","That one recording represents every use of a song"]}]}', '[3,3,1,1,3]', '["Текст о том, как песни передаются на слух и меняются со временем. В тексте прямо сказано, что исполнения не обязаны быть одинаковыми.","«A learner may first remember the repeated part of a song».","Variation — различие, изменение формы: разные версии одной песни.","Певец может вставить название местного места — это пример того, как песню приспосабливают к ситуации.","«A recording captures one performance, not the whole life of a song» — нельзя считать одну запись представителем всех исполнений."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-104', 'R', 'rap', 'A', '{"topic":"Social sciences","title":"Keeping Time in Shared Activities","paras":[["People can judge time approximately without looking at a clock.","They may notice changes in daylight, feel hungry, or remember how long an activity usually takes.","These signals are useful, but they are not equally precise.","Two people can disagree about when a meeting should begin if one says only that it will happen after lunch.","A shared activity becomes easier to arrange when everyone uses the same time reference."],["Clocks provide such a reference.","A group can agree to begin at a particular hour instead of waiting until each person feels ready.","The benefit is not that a clock makes people move faster.","It gives them a common way to describe and compare moments.","A timetable applies this idea to several activities, showing not only what happens but also when.","Travelers, workers, and students can plan one activity around another."],["A timetable is still a plan rather than a promise that nothing will change.","A bus can be delayed, or a discussion can last longer than expected.","People therefore need a way to communicate updates as well as an original schedule.","Shared timekeeping combines measurement with cooperation.","A precise clock is of limited help if different members of a group receive different instructions or if no one reports that the plan has changed."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["How hunger measures exact minutes","Why clocks make every activity faster","Why timetables prevent all delays","How shared time references help people coordinate"]},{"type":"Factual","stem":"What does a timetable show?","opts":["The causes of every delay","Only how long people feel hungry","Activities and their planned times","Only the order of clock inventions"]},{"type":"Vocabulary","stem":"The word \"precise\" in the passage is closest in meaning to","opts":["convenient","exact","early","familiar"],"hl":{"p":0,"s":2,"w":"precise"}},{"type":"Rhetorical Purpose","stem":"Why does the author mention a delayed bus?","opts":["To identify the best transport system","To illustrate that schedules can change","To prove clocks are unnecessary","To explain how daylight is measured"]},{"type":"Inference","stem":"What could reduce a clock''s usefulness for a group?","opts":["Everyone receiving the same update","Conflicting instructions about the meeting time","A timetable listing several activities","Members comparing their plans"]}]}', '[3,2,1,1,1]', '["Главная мысль — общая точка отсчёта времени помогает людям согласовывать действия. Часы не ускоряют людей, а расписание не исключает задержек.","«…showing not only what happens but also when» — мероприятия и их время.","Precise — точный (exact).","Задержка автобуса — пример того, что расписание — «a plan rather than a promise that nothing will change».","«A precise clock is of limited help if different members of a group receive different instructions» — противоречивые указания."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-105', 'R', 'rap', 'A', '{"topic":"Life sciences","title":"Animal Tracks as Evidence","paras":[["An animal may pass through a place without being seen.","Its footprints can remain afterward, especially in mud, snow, or wet sand.","These tracks give observers evidence of the animal''s presence.","The size and shape of a print may help identify the kind of animal.","A series of prints can also suggest its direction of travel and whether it was walking or running.","Tracks record an action, not simply the appearance of a body."],["Reading tracks requires care.","Soft ground can make a print look larger than the foot that produced it, while dry ground may preserve only part of a print.","Rain, melting snow, and other animals can change or destroy marks.","An observer who finds a single unclear print may not have enough information to identify its maker confidently.","Several well-preserved prints usually provide a stronger basis for comparison."],["Scientists sometimes use track surveys to learn which animals use an area.","They follow the same route repeatedly and record where prints appear.","The absence of tracks on one visit does not prove that an animal never uses the place.","Conditions may have prevented a clear print from forming.","Good surveys therefore consider both animal behavior and the surface that preserves its signs.","Evidence becomes more useful when observers understand how it could have been created, changed, or lost."]],"qs":[{"type":"Factual","stem":"What does the passage mainly discuss?","opts":["Why every print identifies its maker exactly","How footprints prevent animals from running","What animal tracks reveal and how to interpret them","Why animals travel only across wet sand"]},{"type":"Factual","stem":"Why might a print appear unusually large?","opts":["It was made in soft ground","Rain always increases foot size","It was recorded on a survey map","The animal was necessarily running"]},{"type":"Vocabulary","stem":"The word \"presence\" in the passage is closest in meaning to","opts":["moving quickly","being there","living permanently","being injured"],"hl":{"p":0,"s":2,"w":"presence"}},{"type":"Rhetorical Purpose","stem":"Why does the author discuss rain and melting snow?","opts":["To describe the best time to run","To show how animals choose their food","To prove surveys must occur only once","To explain why track evidence can change"]},{"type":"Inference","stem":"What can be concluded from finding no tracks on one visit?","opts":["An animal''s use of the area remains uncertain","The ground always preserves footprints","No animals have ever entered the area","The survey route must be changed immediately"]}]}', '[2,0,1,3,0]', '["Текст о том, что следы рассказывают о животном и как их правильно интерпретировать. Следы не всегда точно указывают на животное.","«Soft ground can make a print look larger than the foot that produced it».","Presence — присутствие, нахождение где-то (being there).","Дождь и талый снег — примеры того, как следы меняются или исчезают.","«The absence of tracks on one visit does not prove that an animal never uses the place» — вопрос остаётся открытым."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-106', 'R', 'rap', 'A', '{"topic":"Business and economics","title":"The Value of Sorting Reusable Materials","paras":[["Used materials do not all follow the same path.","A metal can, a glass bottle, and a sheet of paper need different treatment before they can become useful again.","Sorting separates materials that can be processed together.","Without it, a mixed load may require more work, and some items may be unsuitable for the equipment that receives them.","The value of a material therefore depends partly on how it is collected and prepared."],["Consider a container holding clean cardboard.","A producer may be able to use it as a source of paper fiber.","If the cardboard is mixed with food waste, cleaning and separating it can become more difficult.","The load may be worth less even though its total weight is greater.","This example shows that quantity alone is not the same as usable supply.","The condition of the material matters."],["Collection rules differ because local processors have different equipment and buyers.","An item accepted in one town may be rejected in another.","A recycling symbol describes a material but does not guarantee that a nearby service can handle it.","Residents help by following the instructions of their own collection service.","Businesses also need reliable information about what arrives.","Sorting connects household choices to a larger production system in which suitable inputs, transport, processing, and demand all affect whether materials can be reused."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["Why heavier mixed loads always have greater value","Why sorting affects the usefulness of recovered materials","How recycling symbols guarantee local acceptance","Why all towns use identical equipment"]},{"type":"Factual","stem":"What can food waste do to cardboard?","opts":["Guarantee a higher selling price","Increase the amount of paper fiber automatically","Make sorting unnecessary","Make processing more difficult"]},{"type":"Vocabulary","stem":"The word \"inputs\" in the passage is closest in meaning to","opts":["products already sold","rules for residents","materials entering a process","payments made by buyers"],"hl":{"p":2,"s":5,"w":"inputs"}},{"type":"Rhetorical Purpose","stem":"Why is clean cardboard compared with a mixed load?","opts":["To show that usable condition matters beyond weight","To recommend mixing every material","To explain why food waste becomes metal","To show that all paper must be discarded"]},{"type":"Inference","stem":"What should a resident do with an unfamiliar item?","opts":["Assume another town''s rules apply","Add food waste to increase its weight","Rely only on the item''s recycling symbol","Check the local service''s acceptance rules"]}]}', '[1,3,2,0,3]', '["Главная мысль — сортировка определяет, насколько полезны собранные материалы. Тяжёлая смешанная партия может стоить меньше.","«If the cardboard is mixed with food waste, cleaning and separating it can become more difficult».","Inputs — то, что поступает в процесс производства (сырьё).","Сравнение показывает: «quantity alone is not the same as usable supply. The condition of the material matters».","«Residents help by following the instructions of their own collection service», а символ переработки не гарантирует, что местная служба примет вещь."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-107', 'R', 'rap', 'A', '{"topic":"Physical sciences","title":"Why Shadows Change","paras":[["A shadow forms when an object blocks light from reaching a surface.","In sunlight, a tree or a person can cast a dark shape on the ground.","The shadow is not a separate object moving by itself.","Its position depends on the relationship between the light source, the blocking object, and the surface.","Changing any part of that relationship can change the shadow''s shape or location."],["During the day, the Sun appears to move across the sky as Earth turns.","When the Sun is low, an upright object often casts a long shadow.","When it is higher, the shadow becomes shorter.","The direction changes too.","These changes once helped people estimate time with sundials.","A sundial uses the shadow of a fixed object and marks on a surface.","It works because the pattern of sunlight changes in a regular way over a day."],["Shadows can also help reveal features that are hard to notice in direct light.","A small bump on the ground may cast a visible shadow when light comes from the side.","Photographers and surveyors can use this effect to make surface shapes easier to see.","However, a long shadow does not necessarily mean that an object is tall.","To interpret the shadow, an observer must also consider where the light is coming from."]],"qs":[{"type":"Factual","stem":"What is the main topic?","opts":["Why shadow length measures height without context","How light position affects shadows and their uses","How sunlight makes all surfaces flat","Why shadows are independent moving objects"]},{"type":"Factual","stem":"When does an upright object often cast a longer shadow?","opts":["When the ground has no surface","When no light reaches the area","When the Sun is directly above it","When the Sun is low"]},{"type":"Vocabulary","stem":"The word \"fixed\" in the passage is closest in meaning to","opts":["kept in one position","hidden underground","used only once","made much brighter"],"hl":{"p":1,"s":5,"w":"fixed"}},{"type":"Rhetorical Purpose","stem":"Why does the author mention a small bump?","opts":["To show that bumps produce their own light","To illustrate how side lighting reveals shape","To prove sundials require uneven ground","To explain why Earth stops turning"]},{"type":"Inference","stem":"What is needed to estimate an object''s height from its shadow?","opts":["Proof that the object moves","The photographer''s location alone","Information about the light''s direction","Only the shadow''s darkness"]}]}', '[1,3,0,1,2]', '["Текст о том, как положение источника света меняет тень и как тени используют (солнечные часы, съёмка рельефа).","«When the Sun is low, an upright object often casts a long shadow».","A fixed object — неподвижный, закреплённый в одном положении.","Маленький бугорок при боковом освещении даёт видимую тень — пример того, как боковой свет выявляет форму поверхности.","«A long shadow does not necessarily mean that an object is tall… an observer must also consider where the light is coming from»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-108', 'R', 'rap', 'A', '{"topic":"History","title":"Recipes as Historical Records","paras":[["A recipe tells someone how to prepare food, but an old recipe can tell a historian much more.","Its ingredients may show which foods were available, which were expensive, and which arrived through trade.","The equipment mentioned can suggest how a kitchen was organized.","Directions such as cooking over a fire or grinding by hand reveal work that a modern reader might otherwise overlook.","Food preparation connects daily routines with wider economic and social life."],["A recipe is not a complete report of what everyone ate.","It may describe a special occasion rather than an ordinary meal.","Some written collections belonged to wealthy households, whose kitchens had ingredients and workers that others lacked.","A direction may also leave out steps that the original cook already knew.","Historians must therefore consider who wrote the recipe, for whom, and for what purpose."],["Comparing several kinds of evidence helps.","Shopping accounts can show purchases, while kitchen objects can reveal the tools people used.","Letters may describe meals that never appeared in a formal recipe collection.","Together, these sources can support a fuller picture.","A recipe is valuable partly because it records instructions, but its silences matter too.","Understanding those silences requires attention to the people and circumstances behind the document, not simply an attempt to cook the dish exactly as written."]],"qs":[{"type":"Factual","stem":"What is the main idea?","opts":["Recipes describe every household''s daily meals exactly","Old cooking methods cannot be studied","Recipes offer historical evidence that needs context","Written recipes are less useful than all other sources"]},{"type":"Factual","stem":"What might an ingredient reveal?","opts":["A connection with trade","The writer''s complete daily diet","The exact size of a household","The age of every kitchen worker"]},{"type":"Vocabulary","stem":"The word \"overlook\" in the passage is closest in meaning to","opts":["prepare carefully","write down","fail to notice","buy cheaply"],"hl":{"p":0,"s":3,"w":"overlook"}},{"type":"Rhetorical Purpose","stem":"Why are shopping accounts mentioned?","opts":["To show everyone bought identical food","To prove recipes never contain ingredients","To illustrate evidence that complements recipes","To replace questions about a recipe''s author"]},{"type":"Inference","stem":"Why might a recipe omit a preparation step?","opts":["The writer wanted to record every detail","The dish was never prepared","The intended cook was expected to know it","The ingredient was always unavailable"]}]}', '[2,0,2,2,2]', '["Старые рецепты — ценный исторический источник, но их нужно рассматривать в контексте: кто писал, для кого и зачем.","«Its ingredients may show… which arrived through trade».","Overlook — упустить из виду, не заметить.","Счета за покупки — пример другого источника, который дополняет рецепты.","«A direction may also leave out steps that the original cook already knew»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-109', 'R', 'rap', 'A', '{"topic":"Life sciences","title":"Flowers and Visiting Insects","paras":[["A flowering plant can receive visits from many insects, but not every visit has the same result.","An insect may come to collect nectar or pollen.","When it touches parts of the flower, pollen can attach to its body.","Some of that pollen may later reach another flower of the same species.","This transfer can help the plant reproduce.","The insect gets food, while the plant may gain a way to move pollen."],["Flower features can influence which insects visit.","A deep flower may be easier for an insect with a long mouthpart to use.","A shallow flower can offer food to visitors with shorter mouthparts.","Color, smell, and the time a flower opens also affect encounters.","These differences help explain why a garden with several flower types may attract a wider variety of insects than a garden with only one type."],["A busy flower is not necessarily receiving effective pollen transfer.","Some visitors take food without contacting the relevant parts, and pollen may be carried to an unsuitable flower.","Scientists therefore distinguish the number of visits from what those visits accomplish.","They may observe body contact or examine pollen carried by insects.","Counting visitors is useful, but understanding reproduction requires looking at the relationship between the visitor''s behavior and the structure of the flower."]],"qs":[{"type":"Factual","stem":"What does the passage mainly explain?","opts":["How flower features and insect behavior affect pollen transfer","How flower color prevents reproduction","Why every insect visit produces a seed","Why insects visit flowers only for shelter"]},{"type":"Factual","stem":"Which insect may use a deep flower more easily?","opts":["One with a long mouthpart","One visiting only shallow flowers","One carrying no pollen","One avoiding nectar"]},{"type":"Vocabulary","stem":"The word \"relevant\" in the passage is closest in meaning to","opts":["connected to the matter","unusually colorful","recently opened","difficult to reach"],"hl":{"p":2,"s":1,"w":"relevant"}},{"type":"Rhetorical Purpose","stem":"Why does the author compare two kinds of garden?","opts":["To show that gardens require one flower species","To prove gardens replace natural habitats","To show how flower variety can influence insect variety","To identify the best color for every insect"]},{"type":"Inference","stem":"What is insufficient to establish effective pollination?","opts":["Evidence of pollen on insects","Observation of contact with flower parts","A high number of insect visits alone","Information about visiting behavior"]}]}', '[0,0,0,2,2]', '["Текст объясняет, как особенности цветка и поведение насекомого влияют на перенос пыльцы.","«A deep flower may be easier for an insect with a long mouthpart to use».","Relevant — относящийся к делу; здесь — части цветка, нужные для опыления.","Сад с разными цветами привлекает больше видов насекомых — разнообразие цветов влияет на разнообразие насекомых.","«A busy flower is not necessarily receiving effective pollen transfer» — одного количества визитов недостаточно."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-110', 'R', 'rap', 'A', '{"topic":"Social sciences","title":"Learning a Route through Landmarks","paras":[["People often explain a route by mentioning visible places.","Instead of giving only distances, they may say to turn beside a red building or continue until a bridge.","These landmarks help connect instructions with what a traveler can see.","A landmark does not need to be large.","It needs to be noticeable and useful at the point where a choice must be made.","An unusual sign near a junction can be more helpful than a distant tower visible throughout the journey."],["Familiarity changes how people use landmarks.","A resident may know a building by the business that once occupied it, while a visitor sees only its current sign.","Instructions based on local knowledge can therefore confuse someone new to an area.","A useful description should match what the intended traveler can actually recognize.","It may also need an alternative if a landmark is hidden by trees, vehicles, or construction."],["Researchers can study navigation by comparing the routes people describe with the routes they follow.","Errors show where an instruction failed to connect with the surroundings.","A person may remember a landmark correctly but turn before reaching it.","This means successful navigation involves both recognition and sequence.","Good route information helps travelers identify a place and understand what action belongs there, rather than simply listing memorable objects."]],"qs":[{"type":"Factual","stem":"What is the main topic?","opts":["How landmarks support or complicate route instructions","How every landmark must be a tower","Why distances cannot appear in directions","Why residents always give clearer directions"]},{"type":"Factual","stem":"What makes a landmark useful at a junction?","opts":["It can be seen throughout every journey","It is necessarily the largest building","It is noticeable where a choice is needed","It has the oldest local name"]},{"type":"Vocabulary","stem":"The word \"sequence\" in the passage is closest in meaning to","opts":["order of steps","number of buildings","speed of travel","size of objects"],"hl":{"p":2,"s":3,"w":"sequence"}},{"type":"Rhetorical Purpose","stem":"Why is a former business mentioned?","opts":["To explain why all junctions are confusing","To illustrate a difference between local and visitor knowledge","To recommend using only business names","To show that old signs are always visible"]},{"type":"Inference","stem":"What could improve directions for a first-time visitor?","opts":["Assuming recognition guarantees the right turn","Listing landmarks without associated actions","Using features visible on the current route","Using only names known to longtime residents"]}]}', '[0,2,0,1,2]', '["Текст о том, как ориентиры помогают объяснять дорогу и когда, наоборот, мешают (местное знание, закрытые ориентиры).","Ориентир «needs to be noticeable and useful at the point where a choice must be made».","Sequence — последовательность, порядок шагов.","Местный житель называет здание по бывшему магазину, а гость видит только новую вывеску — разница между местным знанием и знанием приезжего.","«A useful description should match what the intended traveler can actually recognize» — то, что видно на маршруте сейчас."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-111', 'R', 'rap', 'A', '{"topic":"Physical sciences","title":"Air inside Insulating Materials","paras":[["A thick winter coat does not create heat in the way a heater does.","Instead, it slows the movement of heat away from the body.","Many warm fabrics contain spaces that hold air.","Still air conducts heat poorly, so these spaces can reduce heat transfer.","The material''s structure matters as well as its thickness.","A thin layer with suitable air pockets can sometimes insulate better than a heavier material that allows heat to pass through easily."],["Air must remain relatively still for this effect to work well.","If large gaps allow air to circulate freely, warm air can move away and be replaced by colder air.","This is why keeping air in many small spaces differs from leaving a large open gap.","A coat also needs to limit wind entering through openings.","Fast-moving outside air can reduce the benefit of trapped air near the body."],["Similar principles appear in buildings.","Insulating layers can contain fibers or cells that restrict air movement.","Their purpose is to reduce unwanted heat transfer, whether the inside is warmer or cooler than the outside.","Insulation is therefore not useful only in cold weather.","It can also help keep a cooled room from gaining heat.","Choosing an insulating material requires attention to its structure, installation, and the conditions in which it will be used."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["Why insulation works only in winter","How trapped air helps materials limit heat transfer","Why heavier materials always insulate better","How coats produce heat independently"]},{"type":"Factual","stem":"What reduces the benefit of trapped air in a coat?","opts":["A suitable material structure","Wind entering through openings","Many small enclosed air spaces","Still air near the body"]},{"type":"Vocabulary","stem":"The word \"restrict\" in the passage is closest in meaning to","opts":["increase","replace","measure","limit"],"hl":{"p":2,"s":1,"w":"restrict"}},{"type":"Rhetorical Purpose","stem":"Why does the author mention a cooled room?","opts":["To show that insulation also helps in warm conditions","To recommend leaving windows open","To show that insulation makes cold air","To compare room sizes"]},{"type":"Inference","stem":"What can be inferred about thickness alone?","opts":["It guarantees identical performance in all conditions","It always matters more than air movement","It does not fully determine insulating performance","It shows how much heat a coat produces"]}]}', '[1,1,3,0,2]', '["Текст о том, как неподвижный воздух в материале замедляет передачу тепла (в одежде и в зданиях). Изоляция полезна не только зимой.","«Fast-moving outside air can reduce the benefit of trapped air near the body» — ветер через отверстия.","Restrict — ограничивать (limit): «cells that restrict air movement».","Охлаждённая комната — пример того, что изоляция полезна и в жару: «Insulation is therefore not useful only in cold weather».","«The material''s structure matters as well as its thickness… a thin layer… can sometimes insulate better» — одна толщина не определяет результат."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-112', 'R', 'rap', 'A', '{"topic":"History","title":"Messages before Electronic Communication","paras":[["Before electronic communication, sending information over a long distance often required someone to carry a physical message.","A letter could travel with a runner, a rider, or a ship.","Its speed depended on roads, weather, available transport, and the distance involved.","A message might arrive quickly along an organized route but slowly in a place with difficult access.","Communication was therefore linked to the systems that moved people and goods."],["Some services used stages, with fresh carriers or animals at different points.","This arrangement could reduce the need for one traveler to complete an entire journey.","A message passed through several hands while continuing toward its destination.","Reliable transfer points mattered because a delay at one stage could affect the whole route.","Sending a letter required more than writing clearly; someone needed a way to carry it and a place to deliver it."],["Historians studying old messages consider both their content and their travel.","An instruction written on one day may describe conditions that changed before it arrived.","The date of writing alone does not reveal when the recipient could act.","Replies also took time, so decisions sometimes had to be made without immediate clarification.","These limits help explain why older letters often include detailed instructions for several possible situations rather than a request for a rapid conversation."]],"qs":[{"type":"Factual","stem":"What does the passage mainly discuss?","opts":["How every message traveled by ship","Why electronic messages need fresh horses","Why old letters contained no useful information","How physical transport shaped long-distance communication"]},{"type":"Factual","stem":"What was an advantage of using stages?","opts":["One carrier did not need to travel the whole route","Every message could avoid transfer points","Weather no longer affected travel","Recipients could reply immediately"]},{"type":"Vocabulary","stem":"The word \"recipient\" in the passage is closest in meaning to","opts":["person receiving a message","place storing supplies","animal carrying a letter","person building a road"],"hl":{"p":2,"s":2,"w":"recipient"}},{"type":"Rhetorical Purpose","stem":"Why does the author distinguish writing and arrival dates?","opts":["To show when a recipient could actually respond","To compare handwriting styles","To establish that all routes took equal time","To show that letters never had dates"]},{"type":"Inference","stem":"Why could detailed alternative instructions be useful?","opts":["Every message described the same event","Immediate questions and replies were difficult","Recipients never made decisions independently","Carriers refused to deliver short letters"]}]}', '[3,0,0,0,1]', '["Главная мысль — дальняя связь зависела от физической перевозки писем: дорог, погоды, транспорта.","«This arrangement could reduce the need for one traveler to complete an entire journey».","Recipient — получатель сообщения.","«The date of writing alone does not reveal when the recipient could act» — важно, когда получатель смог действовать.","«Replies also took time, so decisions sometimes had to be made without immediate clarification» — быстро переспросить было нельзя."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-113', 'R', 'rap', 'A', '{"topic":"Life sciences","title":"Floating and Sinking Leaves in Streams","paras":[["Leaves falling into a stream become part of a system beyond the tree that produced them.","Some float on the surface and move downstream.","Others become caught behind stones or branches.","As they absorb water and begin to break down, their movement can change.","A stream therefore does not carry every leaf at the same speed or send every leaf to the same destination."],["Leaves provide material for small organisms.","Fungi and bacteria begin breaking them down, and some stream animals feed on the leaves or on the organisms growing there.","This process moves energy from plants on land into life in the water.","A shaded stream can receive much of its organic material from the surrounding vegetation.","The connection is easy to miss because the trees stand outside the channel rather than in it."],["Water movement affects where this food collects.","A fast current may carry leaves away, while a quiet pocket can hold them for longer.","Branches and stones can create such pockets.","Removing every fallen branch may make a stream look tidier but also change where organic material remains.","Scientists studying stream food supplies therefore look at the surrounding land and the physical shape of the channel.","The visible water is only one part of the environment supporting the organisms that live there."]],"qs":[{"type":"Factual","stem":"What is the main idea?","opts":["Stream food comes only from plants underwater","Fallen leaves connect land vegetation with stream life","Fallen branches provide no useful habitat","Streams carry every leaf directly to the sea"]},{"type":"Factual","stem":"What can keep leaves in one place longer?","opts":["A quiet pocket behind an obstacle","An uninterrupted fast current","A tree far from the stream","Removing all branches"]},{"type":"Vocabulary","stem":"The word \"channel\" in the passage is closest in meaning to","opts":["passage through which water flows","layer of air above water","group of feeding animals","type of tree leaf"],"hl":{"p":1,"s":4,"w":"channel"}},{"type":"Rhetorical Purpose","stem":"Why are trees outside the channel mentioned?","opts":["To show that trees must grow underwater","To compare tree heights","To explain why streams contain no fungi","To reveal an easily overlooked food connection"]},{"type":"Factual","stem":"What might removing fallen branches affect?","opts":["The existence of all stream bacteria","Whether all nearby trees stop producing leaves","The direction of sunlight","The places where stream food material collects"]}]}', '[1,0,0,3,3]', '["Опавшие листья связывают растения на суше с жизнью в воде: дают пищу организмам ручья.","«A quiet pocket can hold them for longer. Branches and stones can create such pockets».","Channel — русло, по которому течёт вода.","«The connection is easy to miss because the trees stand outside the channel» — легко не заметить эту пищевую связь.","«Removing every fallen branch… also change where organic material remains»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Factual"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-114', 'R', 'rap', 'A', '{"topic":"Business and economics","title":"Sharing Equipment in Small Workshops","paras":[["A small workshop may need a machine that it uses only occasionally.","Buying that machine would provide easy access, but the purchase, storage, and maintenance can be expensive.","Several workshops can instead share equipment.","Each gains access without paying the entire ownership cost.","Sharing can be useful when their needs occur at different times and the machine can be reached without excessive travel."],["Shared ownership also requires rules.","The users need to decide who books time, who cleans the equipment, and who pays for repairs.","If everyone expects to use the machine on the same afternoon, it cannot meet all their needs at once.","A booking calendar can reduce uncertainty, but someone must keep it accurate.","Training matters too: careless use by one workshop can create costs or delays for the others."],["The decision is not simply between paying and using something for free.","Sharing replaces some ownership costs with coordination costs.","Transporting materials, arranging appointments, and agreeing on maintenance all require time.","A workshop using the machine every day may prefer its own, while an occasional user may benefit from sharing.","To judge the arrangement, owners must consider how often the equipment is needed, how reliable access is, and whether the saved money is worth the additional planning involved."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["How sharing removes every equipment cost","Benefits and coordination needs of shared equipment","Why workshops never need their own machines","Why maintenance is unnecessary for shared machines"]},{"type":"Factual","stem":"What problem can arise if users want the same time?","opts":["The purchase price automatically falls","The machine cannot serve everyone simultaneously","Every workshop receives its own machine","Cleaning becomes unnecessary"]},{"type":"Vocabulary","stem":"The word \"occasionally\" in the passage is closest in meaning to","opts":["every day","very carefully","without permission","from time to time"],"hl":{"p":0,"s":0,"w":"occasionally"}},{"type":"Rhetorical Purpose","stem":"Why is a daily user compared with an occasional user?","opts":["To identify who invented booking calendars","To show that frequency affects the ownership decision","To explain that all workshops have equal demand","To show daily users never need maintenance"]},{"type":"Inference","stem":"Which arrangement is most likely to suit sharing?","opts":["Transport costs exceed the expected savings","All users need the machine continuously","Nobody agrees to clean or repair it","Users can plan different reliable booking times"]}]}', '[1,1,3,1,3]', '["Текст о выгодах совместного оборудования и о том, что оно требует договорённостей (бронирование, уборка, ремонт).","«If everyone expects to use the machine on the same afternoon, it cannot meet all their needs at once».","Occasionally — время от времени.","Ежедневному пользователю выгоднее своя машина, редкому — совместная: решение зависит от частоты использования.","Совместное владение работает, когда потребности «occur at different times» и доступ надёжен. Остальные варианты описывают условия, при которых оно не работает."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-115', 'R', 'rap', 'A', '{"topic":"Physical sciences","title":"Condensation on a Cold Surface","paras":[["A cold drink can develop water drops on the outside of its glass.","The water has not necessarily leaked through the glass.","It may have come from water vapor already present in the surrounding air.","When air close to the cold surface cools enough, some vapor changes into liquid water.","This process is called condensation.","The outside drops reveal a change of state that would otherwise be difficult to see."],["The amount of condensation depends on conditions.","Air containing more water vapor can produce more visible drops when cooled sufficiently.","A glass close to room temperature may remain dry under the same conditions.","The difference is not simply whether the drink contains water.","What matters is the relationship between surface temperature and the moisture in the air.","Condensation can occur on many cold surfaces, including windows and metal pipes."],["People sometimes mistake such water for a leak.","Looking at where it appears can help distinguish the causes.","Water spread over the outside of a cold pipe may have a different explanation from water emerging at a broken joint.","This distinction matters when deciding what to repair.","Understanding condensation helps people connect an everyday observation with the behavior of water in air.","It also shows why an explanation should consider the surroundings, not just the object on which a change becomes visible."]],"qs":[{"type":"Factual","stem":"What does the passage explain?","opts":["How all room-temperature surfaces become wet","How condensation forms and can be recognized","Why water vapor exists only near drinks","Why glass allows every drink to leak"]},{"type":"Factual","stem":"Where can the outside drops come from?","opts":["Only a broken pipe joint","Water produced by metal","Water vapor in surrounding air","Only liquid passing through the glass"]},{"type":"Vocabulary","stem":"The word \"emerging\" in the passage is closest in meaning to","opts":["spreading evenly","being repaired","cooling down","coming out"],"hl":{"p":2,"s":2,"w":"emerging"}},{"type":"Rhetorical Purpose","stem":"Why does the author compare pipe surfaces and joints?","opts":["To compare the taste of drinks","To show every wet pipe must be replaced","To prove pipes contain no water vapor nearby","To distinguish condensation from a possible leak"]},{"type":"Inference","stem":"Why might a warmer glass remain dry?","opts":["Condensation requires a broken surface","The surrounding air must contain no moisture","Its drink cannot contain water","Its surface may not cool nearby air enough"]}]}', '[1,2,3,3,3]', '["Текст объясняет, как образуется конденсат и как отличить его от протечки.","«It may have come from water vapor already present in the surrounding air».","Emerging — выходящий наружу: вода, выходящая из сломанного соединения.","Сравнение показывает, как отличить конденсат на холодной трубе от возможной протечки в месте соединения.","«What matters is the relationship between surface temperature and the moisture in the air» — тёплый стакан может недостаточно охлаждать воздух рядом."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-116', 'R', 'rap', 'A', '{"topic":"Art and music","title":"The Space around a Sculpture","paras":[["A sculpture occupies space, but the space around it also affects how it is seen.","A viewer can often walk around a sculpture and discover different shapes from different angles.","A projecting arm may hide part of the body from one position but become clearly visible from another.","Unlike an image shown from one fixed viewpoint, a three-dimensional object can invite a sequence of observations."],["The display location influences that sequence.","If a sculpture stands against a wall, visitors may be unable to see its back.","If it stands in the center of a room, they may have access to more viewpoints.","Lighting can reveal or hide surface details, while nearby objects can compete for attention.","Curators must therefore think about more than placing the sculpture where it physically fits.","They also consider how people will approach and move past it."],["There is no rule that every sculpture must be visible from every side.","Some works were made for a particular position or designed with a main viewing direction.","Understanding the original setting can help explain such choices.","A useful display makes the relationship between object and viewpoint understandable.","Studying sculpture involves looking at material and form, but also at the movement and surroundings that shape a viewer''s experience of the work."]],"qs":[{"type":"Factual","stem":"What is the main topic?","opts":["Why every sculpture needs identical lighting","Why sculptures cannot stand near walls","How paintings always show every side of an object","How viewpoints and display space affect sculpture viewing"]},{"type":"Factual","stem":"What can a central room position allow?","opts":["A single compulsory viewpoint","Removal of all surface shadows","Access to more viewing angles","Automatic recovery of the original setting"]},{"type":"Vocabulary","stem":"The word \"projecting\" in the passage is closest in meaning to","opts":["lying underneath","being repaired","extending outward","turning invisible"],"hl":{"p":0,"s":2,"w":"projecting"}},{"type":"Rhetorical Purpose","stem":"Why are works with a main viewing direction mentioned?","opts":["To show that sculptures are always flat","To qualify the idea that every side must be accessible","To explain how all artworks are transported","To recommend ignoring original settings"]},{"type":"Factual","stem":"What should a curator consider beyond physical fit?","opts":["How visitors approach and observe the work","Only the room''s total floor area","Whether the work is visible in one photograph","Removing all other objects from the museum"]}]}', '[3,2,2,1,0]', '["Текст о том, как точка обзора и место экспозиции влияют на восприятие скульптуры.","«If it stands in the center of a room, they may have access to more viewpoints».","Projecting — выступающий наружу (о руке скульптуры).","Работы с главным направлением обзора уточняют мысль: «There is no rule that every sculpture must be visible from every side».","«They also consider how people will approach and move past it»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Factual"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-117', 'R', 'rap', 'A', '{"topic":"Social sciences","title":"Why Clear Categories Help a Survey","paras":[["A survey often asks people to choose from a set of answers.","These choices help researchers compare responses, but they must be designed carefully.","If a question asks how someone travels to work, options such as walking, cycling, bus, and car can be useful.","However, a person may use more than one method.","The instructions must explain whether to select a main method or every method used.","Without that guidance, people may answer the same question in different ways."],["Categories also need to cover relevant possibilities.","A list that leaves out train travel may force some respondents to choose an inaccurate answer or skip the question.","An \"other\" option can help, especially when it includes space to explain.","At the same time, too many overlapping categories can make the survey harder to complete.","Good choices balance useful detail with clarity."],["Researchers may test a survey with a small group before distributing it widely.","They ask which questions were confusing and compare how people understood the instructions.","This test can reveal problems that were not obvious to the writer.","Improving a survey does not mean making every question longer.","Sometimes a short instruction removes an important ambiguity.","The quality of the resulting information depends partly on whether participants understand the same question in a sufficiently similar way."]],"qs":[{"type":"Factual","stem":"What is the main idea?","opts":["Every respondent uses only one travel method","Longer surveys always produce more accurate answers","Testing removes the need for clear categories","Survey categories and instructions affect response quality"]},{"type":"Factual","stem":"Why could omitting train travel cause a problem?","opts":["Train users would answer more quickly","All other choices would become identical","Some respondents may lack an accurate choice","The survey would automatically count trains"]},{"type":"Vocabulary","stem":"The word \"ambiguity\" in the passage is closest in meaning to","opts":["lack of participants","uncertainty about meaning","agreement among writers","large amount of detail"],"hl":{"p":2,"s":4,"w":"ambiguity"}},{"type":"Rhetorical Purpose","stem":"Why is a small preliminary group discussed?","opts":["To prove large surveys are impossible","To replace all answer categories with interviews","To show how confusing questions can be detected","To ensure every participant travels by train"]},{"type":"Factual","stem":"What could happen without a multiple-method instruction?","opts":["Similar travelers might report their travel differently","Researchers could infer identical meanings automatically","Respondents would necessarily stop working","Every person would select all options"]}]}', '[3,2,1,2,0]', '["Главная мысль — категории и инструкции в опросе определяют качество ответов. Длиннее не значит лучше.","«A list that leaves out train travel may force some respondents to choose an inaccurate answer or skip the question».","Ambiguity — неоднозначность, неясность смысла.","Пилотная группа помогает найти непонятные вопросы: «This test can reveal problems that were not obvious to the writer».","«Without that guidance, people may answer the same question in different ways»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Factual"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-118', 'R', 'rap', 'A', '{"topic":"Life sciences","title":"The Work of Decomposers","paras":[["A fallen log can remain visible for years, yet it is not unchanged.","Fungi, bacteria, and other organisms gradually break down its material.","Some live on its surface, while others grow or move inside.","These decomposers use dead material as a resource.","Their activity helps return nutrients to the environment, where they can become available for other living things.","A forest therefore contains important processes in both living trees and dead remains."],["The speed of breakdown varies.","Moisture and temperature can influence decomposer activity.","Very dry conditions may slow it, and the structure of the wood matters too.","A small soft piece and a large dense log do not necessarily disappear at the same rate.","Observers need to consider these differences before using the appearance of wood to estimate how long it has been lying on the ground."],["A decaying log also provides places for animals to shelter.","Cracks, soft sections, and damp spaces can create different small habitats.","Removing every dead piece of wood may make an area seem cleaner but also remove food and shelter.","This does not mean that fallen wood should never be moved, especially where safety is an issue.","It means that dead material has ecological functions.","Looking only at living plants can leave out a substantial part of how a woodland system works."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["Ecological functions of dead wood and its breakdown","Why forest safety never matters","How every log disappears at the same speed","Why dead wood has no forest value"]},{"type":"Factual","stem":"Which condition may slow decomposition?","opts":["Very dry surroundings","Access to suitable moisture","The presence of decomposers","A supply of dead material"]},{"type":"Vocabulary","stem":"The word \"substantial\" in the passage is closest in meaning to","opts":["temporary","considerable","invisible","unrelated"],"hl":{"p":2,"s":5,"w":"substantial"}},{"type":"Rhetorical Purpose","stem":"Why does the author mention animal shelter?","opts":["To show animals stop all decomposition","To explain why logs are always dangerous","To argue only living trees provide habitat","To show a function beyond nutrient recycling"]},{"type":"Inference","stem":"Why is log appearance an imperfect guide to age?","opts":["All logs decay without organisms","Large logs must always be younger","Different conditions produce different breakdown rates","Temperature has no influence on decay"]}]}', '[0,0,1,3,2]', '["Текст об экологических функциях мёртвой древесины: разложение, возврат питательных веществ, укрытия для животных.","«Very dry conditions may slow it».","Substantial — значительный, существенный.","Укрытие для животных — функция мёртвого дерева помимо возврата питательных веществ.","Скорость разложения зависит от влажности, температуры и структуры древесины, поэтому по виду бревна нельзя точно судить о его возрасте."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-119', 'R', 'rap', 'A', '{"topic":"Physical sciences","title":"Seeing the Moon''s Changing Shape","paras":[["The Moon can appear as a thin curve, a half circle, or a full circle.","These appearances are called phases.","They do not mean that the Moon itself changes its physical shape every few days.","Sunlight illuminates about half of the Moon at a time.","As the Moon travels around Earth, observers see different amounts of that illuminated half.","The changing viewing relationship produces the familiar pattern."],["A common mistake is to explain every phase as Earth''s shadow covering the Moon.","Earth''s shadow is involved in a lunar eclipse, but ordinary phases have a different cause.","A model using a lamp, a ball, and an observer can help show the distinction.","The lamp represents the Sun, and the observer sees different lit portions as the ball moves around.","The ball need not enter the observer''s shadow for its visible bright area to change."],["The model leaves out many details, including real distances and the exact size relationships.","It is useful because it highlights illumination and viewpoint.","Careful observation over several weeks can connect this explanation with the sky.","A person can record the visible shape and compare it with earlier observations.","The result shows that an apparent change in an object''s outline can come from how it is lit and viewed, rather than from a change in the object itself."]],"qs":[{"type":"Factual","stem":"What does the passage explain?","opts":["Why the Moon''s visible illuminated portion changes","Why sunlight illuminates the entire Moon equally","How every phase is a lunar eclipse","Why the Moon changes its physical shape"]},{"type":"Factual","stem":"What causes ordinary Moon phases?","opts":["Different views of the sunlit half","Earth''s shadow at every phase","Changes in the Moon''s material","A lamp placed on Earth"]},{"type":"Vocabulary","stem":"The word \"portions\" in the passage is closest in meaning to","opts":["pattern","shadow","parts","distance"],"hl":{"p":1,"s":3,"w":"portions"}},{"type":"Rhetorical Purpose","stem":"Why does the author describe a lamp and ball?","opts":["To show the Moon makes its own light","To illustrate illumination and viewing relationships","To reproduce every real distance exactly","To explain why observation is unnecessary"]},{"type":"Factual","stem":"What can change without the Moon physically changing shape?","opts":["The Moon''s material composition","The size of the Sun","Its apparent bright outline from Earth","Earth''s actual diameter"]}]}', '[0,0,2,1,2]', '["Текст объясняет, почему меняется видимая освещённая часть Луны. Форма самой Луны не меняется.","«As the Moon travels around Earth, observers see different amounts of that illuminated half». Тень Земли — только при затмении.","Portions — части, доли (освещённые части мяча).","Модель с лампой и мячом показывает связь между освещением и точкой наблюдения.","«An apparent change in an object''s outline can come from how it is lit and viewed» — меняется видимый с Земли светлый контур."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Factual"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-120', 'R', 'rap', 'A', '{"topic":"History","title":"What Old Street Names Can Reveal","paras":[["A street name can preserve a clue about a place''s past.","A road named after a mill may remain long after the mill has disappeared.","Another name may refer to a market, a craft, or a family that once owned nearby land.","These words can draw attention to activities and people no longer visible in the present streetscape.","They provide a starting point for historical questions rather than a complete answer."],["Names can change for several reasons.","A town may rename a street to honor someone, simplify delivery routes, or replace a confusing duplicate.","A familiar old name may continue in conversation even after official signs change.","Different maps can therefore use different names for the same road.","Historians comparing locations need to consider when each map was made and which naming system it followed."],["A name is not always a literal description.","A modern developer may choose a pleasant-sounding name with no connection to a former local activity.","Likewise, the survival of a craft name does not prove that every house on the street once housed that craft.","Researchers compare names with property records, maps, and physical evidence.","Used together, these sources help explain how places have developed.","Street names are valuable because they can carry memories, but those memories need to be examined rather than accepted without question."]],"qs":[{"type":"Factual","stem":"What is the main idea?","opts":["Official renaming immediately ends all older usage","Street names offer historical clues requiring other evidence","Every street name accurately describes an old industry","Names provide complete property histories"]},{"type":"Factual","stem":"Why might two maps name the same road differently?","opts":["All road names describe current businesses","One map must show a different town","They reflect different dates or naming systems","The road must have physically moved"]},{"type":"Vocabulary","stem":"The word \"literal\" in the passage is closest in meaning to","opts":["exactly matching the stated description","pleasant sounding","widely used","difficult to spell"],"hl":{"p":2,"s":0,"w":"literal"}},{"type":"Rhetorical Purpose","stem":"Why is a modern developer mentioned?","opts":["To explain why maps cannot be compared","To recommend replacing property records","To show a name may lack a historical local connection","To prove all old names were invented recently"]},{"type":"Inference","stem":"What is a reasonable response to a road named Mill Street?","opts":["Assume every building was a mill","Investigate whether a mill existed nearby","Assume the name refers to a current mill","Reject the name as historical evidence"]}]}', '[1,2,0,2,1]', '["Названия улиц дают исторические подсказки, но их нужно проверять по другим источникам.","«Historians… need to consider when each map was made and which naming system it followed».","Literal — буквальный, точно соответствующий названию.","Застройщик может выбрать красивое название без связи с местной историей — название не всегда исторический факт.","Название — «a starting point for historical questions rather than a complete answer». Разумно проверить, была ли рядом мельница."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-101', 'R', 'rap', 'B', '{"topic":"Life sciences","title":"Camouflage and Changing Backgrounds","paras":[["Camouflage can make an animal harder to detect by reducing the visual differences between its body and its surroundings.","A pattern resembling dry leaves may work well on a forest floor but poorly on bare rock.","Concealment is therefore a relationship between an animal and a particular background, not a permanent property of its color alone.","Movement and lighting can also change how noticeable the animal becomes."],["Some animals have different colors on their upper and lower surfaces.","When light comes mainly from above, the upper surface tends to receive more illumination.","A darker upper side and lighter underside can partly reduce the resulting contrast.","This arrangement is called countershading.","It may help an animal appear less three-dimensional under suitable conditions, although its effect depends on the angle of the light and the observer."],["Researchers evaluating camouflage cannot rely solely on how attractive a pattern looks to a human.","Predators may see colors differently or notice movement that a still photograph conceals.","Experiments may compare detection against several backgrounds and under different lighting conditions.","Such comparisons distinguish a pattern''s appearance from its performance.","They also explain why a color that seems conspicuous in an isolated display can be effective in a natural habitat.","To understand camouflage, one must consider the observer, the setting, and the animal''s behavior together."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["Animal movement always improves concealment","Camouflage depends on viewing conditions and context","Countershading works equally in every habitat","Human judgments reliably predict every predator''s vision"]},{"type":"Factual","stem":"What is countershading?","opts":["A bright underside matching bare rock","A leaf pattern on every surface","A darker upper surface with a lighter underside","A color change caused by running"]},{"type":"Vocabulary","stem":"The word \"conspicuous\" in the passage is closest in meaning to","opts":["slow moving","poorly understood","well protected","easily noticed"],"hl":{"p":2,"s":4,"w":"conspicuous"}},{"type":"Rhetorical Purpose","stem":"Why are predators'' color abilities discussed?","opts":["To show predators cannot detect movement","To explain limits of judging camouflage through human vision","To prove photographs reproduce every habitat","To explain how countershading changes eyesight"]},{"type":"Inference","stem":"What would strengthen a camouflage evaluation?","opts":["Selecting the pattern humans find most attractive","Ignoring the position of the light","Using only an isolated photograph","Testing detection in relevant natural-looking conditions"]}]}', '[1,2,3,1,3]', '["Маскировка — это связь животного с конкретным фоном, светом и наблюдателем, а не просто окраска.","«A darker upper side and lighter underside… This arrangement is called countershading».","Conspicuous — бросающийся в глаза, заметный. Противопоставление: заметный на выставке, но эффективный в природе.","Хищники видят цвета иначе, поэтому человеческий глаз — ненадёжный судья маскировки.","«Experiments may compare detection against several backgrounds and under different lighting conditions» — проверка в условиях, близких к природным."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-102', 'R', 'rap', 'B', '{"topic":"Physical sciences","title":"Matching Patterns in Tree Rings","paras":[["In many seasonal environments, trees form growth rings that can provide records of past conditions.","Ring width may reflect how much a tree grew during a particular year.","Growth is influenced by several factors, including moisture, temperature, competition, and damage.","A narrow ring is therefore not automatically evidence of one specific climatic event.","Its meaning depends on the tree and the circumstances in which it developed."],["Researchers compare patterns from multiple trees rather than counting rings in isolation.","A sequence of unusually narrow and wide rings may appear in several samples from the same region.","Aligning these sequences helps establish which rings formed during the same years.","This process, called crossdating, can reveal problems such as an unclear or missing ring in an individual sample.","Overlapping records from living trees and older wood can also extend a regional sequence further into the past."],["Once a sequence is dated securely, researchers can investigate relationships between growth and environmental conditions.","They may compare recent rings with recorded weather before interpreting older ones.","The comparison helps identify what kind of signal the trees preserve.","Trees from a dry site may respond strongly to moisture, while those elsewhere may be limited by other factors.","A dated ring record is valuable, but it becomes a climate record only through careful interpretation of those relationships."]],"qs":[{"type":"Factual","stem":"What is the central idea?","opts":["Counting one sample provides all climate information","Tree-ring records need pattern matching and contextual interpretation","Crossdating removes all environmental influences","Every narrow ring identifies a drought exactly"]},{"type":"Factual","stem":"What does crossdating involve?","opts":["Aligning ring patterns across samples","Replacing old wood with living trees","Measuring only a tree''s total height","Giving every narrow ring the same date"]},{"type":"Vocabulary","stem":"The word \"extend\" in the passage is closest in meaning to","opts":["make less reliable","make wider physically","make longer in coverage","make easier to discard"],"hl":{"p":1,"s":4,"w":"extend"}},{"type":"Rhetorical Purpose","stem":"Why compare recent rings with recorded weather?","opts":["To remove the need for crossdating","To show old wood contains no information","To identify environmental influences on growth","To prove trees respond only to temperature"]},{"type":"Inference","stem":"What can a securely dated ring still leave uncertain?","opts":["Whether rings can be compared at all","Whether it belongs to an identified year","Whether the sample contains wood","Which environmental factor shaped its width"]}]}', '[1,0,2,2,3]', '["Записи годичных колец требуют сопоставления узоров из разных деревьев и осторожной интерпретации.","«Aligning these sequences helps establish which rings formed during the same years. This process, called crossdating…»","Extend a sequence further into the past — продлить ряд, увеличить охват во времени.","Сравнение с записанной погодой помогает понять, какой сигнал хранят деревья: «identify what kind of signal the trees preserve».","Даже точно датированное кольцо не говорит само, какой фактор сделал его узким: «A narrow ring is therefore not automatically evidence of one specific climatic event»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-103', 'R', 'rap', 'B', '{"topic":"Social sciences","title":"Retrieval as a Learning Activity","paras":[["Reading notes can create a feeling that information is familiar.","However, recognizing a statement on a page differs from producing the information without seeing it.","Retrieval practice asks learners to attempt that production.","A student might close a book and explain a concept, answer a question, or list the steps in a process.","The activity makes the accessibility of stored knowledge more visible than rereading alone does."],["An unsuccessful attempt is not necessarily wasted.","It can reveal a gap that the learner did not notice while looking at the answer.","Checking accurate feedback afterward helps connect the question with the correct information.","Without that check, a repeated error may remain uncorrected.","Retrieval practice therefore involves more than asking difficult questions; the opportunity to evaluate and repair an answer matters too."],["Researchers comparing study methods need to distinguish immediate performance from later retention.","A method that feels smooth during study may not produce the strongest memory after a delay.","Conversely, an effortful task may expose difficulties while supporting future access to information.","The appropriate comparison uses a later test as well as observations during practice.","This does not imply that reading is useless or that every kind of material should be studied identically.","It shows why the ease of a learning activity cannot by itself establish how well the information will remain available."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["Why reading has no role in learning","How immediate ease guarantees lasting knowledge","Why all failed answers improve memory automatically","Retrieval practice and how to judge learning beyond familiarity"]},{"type":"Factual","stem":"What is an example of retrieval practice?","opts":["Explaining a concept with the book closed","Looking repeatedly at the correct explanation","Copying a visible answer word for word","Highlighting every line in the notes"]},{"type":"Vocabulary","stem":"The word \"retention\" in the passage is closest in meaning to","opts":["continued keeping of information","speed of reading","selection of questions","correction of handwriting"],"hl":{"p":2,"s":0,"w":"retention"}},{"type":"Rhetorical Purpose","stem":"Why does the author discuss feedback after failure?","opts":["To remove the need for later tests","To recommend avoiding difficult questions","To show how an attempt can lead to correction","To show wrong answers should be memorized unchanged"]},{"type":"Inference","stem":"What is insufficient evidence of effective learning?","opts":["Performance on a later test","Evidence that an error was corrected","An explanation produced without notes","A study activity feeling easy at the time"]}]}', '[3,0,0,2,3]', '["Текст о практике извлечения и о том, почему ощущение знакомости — не доказательство усвоения.","«A student might close a book and explain a concept…»","Retention — сохранение информации в памяти.","После неудачной попытки обратная связь помогает исправить ошибку: «Checking accurate feedback afterward helps connect the question with the correct information».","«The ease of a learning activity cannot by itself establish how well the information will remain available» — лёгкость не доказательство."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-104', 'R', 'rap', 'B', '{"topic":"Physical sciences","title":"Ice Layers and Trapped Air","paras":[["As snow accumulates in a cold region, older layers can become buried and compressed.","Under suitable conditions, they eventually form ice containing small pockets of air.","A core drilled through the ice can provide a sequence of layers from different periods.","The air pockets offer evidence about past atmospheric composition, while other features of the ice can preserve information about conditions when the snow formed."],["Reading this record requires more than assigning the depth of a layer to an exact date.","Accumulation rates can vary, and flowing ice can compress or distort older layers.","In addition, air may remain connected to the atmosphere through spaces in the snow before those spaces close.","Consequently, the gas trapped in a section of ice can be younger than the ice surrounding it.","Researchers must consider the histories of both materials when comparing records."],["Scientists use several dating approaches and compare cores from different sites to evaluate their interpretations.","A pattern found in more than one record can help distinguish a regional feature from a wider event.","Ice cores do not provide identical information everywhere: local snowfall and preservation conditions influence what remains.","Their value lies in the combination of physical layers and chemical evidence.","Understanding how the archive formed is essential to understanding what it can reveal about the past."]],"qs":[{"type":"Factual","stem":"What is the main idea?","opts":["Every core records the same local conditions","Ice depth always gives an exact date directly","Trapped air and surrounding ice must have identical ages","Ice cores preserve useful evidence requiring attention to formation"]},{"type":"Factual","stem":"Why can trapped gas be younger than surrounding ice?","opts":["Gas always forms after drilling","Air can circulate before snow spaces close","Older ice contains no air spaces","Researchers replace the original air"]},{"type":"Vocabulary","stem":"The word \"distort\" in the passage is closest in meaning to","opts":["alter the original form","date with certainty","freeze immediately","remove all chemicals"],"hl":{"p":1,"s":1,"w":"distort"}},{"type":"Rhetorical Purpose","stem":"Why compare cores from different sites?","opts":["To assess whether a pattern is local or widespread","To avoid using chemical evidence","To ensure every snowfall rate is identical","To make trapped air older than its ice"]},{"type":"Factual","stem":"What should accompany interpretation of core measurements?","opts":["Knowledge of how layers and gas pockets formed","A decision to disregard site conditions","An assumption of constant accumulation everywhere","Only the present depth of the core"]}]}', '[3,1,0,0,0]', '["Ледяные керны хранят ценные данные, но их нужно читать с учётом того, как формировались слои и пузырьки газа.","«Air may remain connected to the atmosphere through spaces in the snow before those spaces close. Consequently, the gas… can be younger».","Distort — искажать, изменять исходную форму.","«A pattern found in more than one record can help distinguish a regional feature from a wider event».","«Understanding how the archive formed is essential to understanding what it can reveal»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Factual"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-105', 'R', 'rap', 'B', '{"topic":"Business and economics","title":"Seasonal Prices for Fresh Produce","paras":[["The price of fresh produce can change even when customers'' preferences remain stable.","During a local harvest, a larger supply may reach the market over a short period.","If demand does not rise equally, sellers may lower prices to attract buyers before the produce spoils.","At other times, supplying the same food may require storage, longer-distance transport, or production under more costly conditions.","These differences help explain seasonal price patterns."],["The pattern is not automatic.","Bad weather can reduce the harvest, and a sudden increase in demand can offset the effect of additional supply.","Different products also have different storage possibilities.","A crop that keeps well can be sold gradually, while a highly perishable crop creates greater pressure to sell quickly.","The time available to a seller influences how changes in supply affect bargaining and pricing."],["Researchers studying such markets compare quantities, costs, and prices across periods.","A low price alone does not prove that farmers are producing efficiently, just as a high price does not necessarily show that consumers value a crop more.","Several causes may produce a similar visible result.","Understanding price movements requires separating changes in supply from changes in demand and considering the practical constraints on storing and transporting the product.","Seasonal markets illustrate how biological timing and economic decisions interact."]],"qs":[{"type":"Factual","stem":"What does the passage mainly explain?","opts":["How storage removes all transport costs","How seasonal supply and practical constraints influence produce prices","Why customer preferences determine every price change","Why all harvests lead to lower prices"]},{"type":"Factual","stem":"Why may sellers lower prices during a large harvest?","opts":["To make stored crops spoil faster","To avoid delivering any food","To sell perishable produce before spoilage","To guarantee identical demand every year"]},{"type":"Vocabulary","stem":"The word \"offset\" in the passage is closest in meaning to","opts":["simplify","predict","counterbalance","record"],"hl":{"p":1,"s":1,"w":"offset"}},{"type":"Rhetorical Purpose","stem":"Why compare crops with different storage abilities?","opts":["To argue transport is irrelevant","To explain differences in pressure to sell quickly","To show all produce has equal shelf life","To prove storage always increases demand"]},{"type":"Inference","stem":"What can be inferred from a higher produce price alone?","opts":["Farmers must have become less skilled","Its cause cannot be identified with certainty","The harvest quantity has certainly increased","Consumers necessarily prefer the crop more"]}]}', '[1,2,2,1,1]', '["Сезонное предложение и практические ограничения (хранение, перевозка) влияют на цены продуктов.","«…sellers may lower prices to attract buyers before the produce spoils».","Offset — уравновешивать, компенсировать.","Культура, которая хорошо хранится, продаётся постепенно, а скоропортящаяся создаёт «greater pressure to sell quickly».","«Several causes may produce a similar visible result», и высокая цена не обязательно значит, что покупатели больше ценят продукт. По одной цене причину не установить."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-106', 'R', 'rap', 'B', '{"topic":"History","title":"Roof Shapes and Local Conditions","paras":[["Traditional roof forms often reflect more than visual preference.","Builders work with available materials, familiar techniques, and the conditions a building must face.","A steep roof can help rain or snow move off its surface, while a broad overhang can protect walls and entrances.","Such features may become recognizable parts of a regional building style even when later residents do not know the original reasons for them."],["Environmental explanations should not be treated as complete explanations of every design.","Two communities facing similar rainfall may build different roofs because they use different materials or construction systems.","Social expectations also matter.","A roof may signal status, follow a religious tradition, or preserve a style associated with a particular group.","A feature can therefore have a practical role and a cultural meaning at the same time."],["Historians and architects examine buildings alongside records of craft knowledge, material supply, and local use.","They ask whether a feature has changed as new technologies became available.","A roof shape that once suited a particular material may survive after the material is replaced.","Its continued use may express identity rather than technical necessity alone.","Studying these patterns reveals how architecture combines adaptation with tradition.","A useful interpretation connects form to circumstances without assuming that climate dictates every choice or that decorative meaning excludes practical function."]],"qs":[{"type":"Factual","stem":"What is the main idea?","opts":["New materials always erase regional styles","Roof forms combine practical conditions with cultural traditions","Decorative meaning prevents practical usefulness","Climate determines every roof identically"]},{"type":"Factual","stem":"What can a broad overhang do?","opts":["Protect walls and entrances","Remove cultural meaning from a roof","Guarantee that snow never falls","Make all construction materials identical"]},{"type":"Vocabulary","stem":"The word \"dictates\" in the passage is closest in meaning to","opts":["describes briefly","preserves carefully","measures accurately","determines completely"],"hl":{"p":2,"s":5,"w":"dictates"}},{"type":"Rhetorical Purpose","stem":"Why compare communities with similar rainfall?","opts":["To show climate alone cannot explain roof differences","To establish that styles never change","To prove roof forms ignore environmental conditions","To recommend one material everywhere"]},{"type":"Inference","stem":"Why might an old roof form survive a material change?","opts":["It has become associated with local identity","Its original material is still necessarily used","Builders cannot learn new techniques","All technical needs remain identical"]}]}', '[1,0,3,0,0]', '["Форма крыши сочетает практические условия и культурные традиции.","«A broad overhang can protect walls and entrances».","Dictates — диктует, полностью определяет.","При одинаковом количестве осадков общины строят разные крыши — один климат различий не объясняет.","«Its continued use may express identity rather than technical necessity alone»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-107', 'R', 'rap', 'B', '{"topic":"Social sciences","title":"Words Borrowed between Languages","paras":[["Languages can acquire words through contact with other languages.","A new food, technology, or social practice may arrive with a name that speakers adopt.","Borrowing can also occur when a foreign expression gains prestige or becomes familiar through repeated use.","The borrowed word need not fill an absolute gap: a language may already have a related term.","Speakers'' choices are influenced by both practical communication and social associations."],["Once adopted, a word can change.","Its pronunciation may be adjusted to familiar sound patterns, and its grammatical behavior may follow the receiving language''s rules.","Its meaning can become narrower or broader than in the source language.","These changes make borrowing an active process rather than simple copying.","A word used in two languages may therefore look similar while functioning differently in each."],["Researchers investigate borrowing by examining dated texts and patterns of use.","The earliest surviving written example does not necessarily mark the first spoken use.","Some expressions circulate informally before entering published records.","Scholars also distinguish a temporary foreign quotation from a word that has become part of ordinary vocabulary.","The distinction depends on how speakers use it, not merely on its origin.","Studying borrowed words can reveal contact between communities, but a single word cannot by itself describe the complete history or direction of that contact."]],"qs":[{"type":"Factual","stem":"What does the passage mainly discuss?","opts":["Why borrowing occurs only when no related word exists","Why written records date all speech exactly","How borrowed words are adopted, changed, and studied","How borrowed words retain every original feature"]},{"type":"Factual","stem":"What may happen after a word enters another language?","opts":["Its source language stops using it","It cannot follow local grammar","It must lose all recognizable sounds","Its meaning can change"]},{"type":"Vocabulary","stem":"The word \"prestige\" in the passage is closest in meaning to","opts":["social respect or status","literal meaning","grammatical difficulty","historical age"],"hl":{"p":0,"s":2,"w":"prestige"}},{"type":"Rhetorical Purpose","stem":"Why mention informal use before publication?","opts":["To show all borrowings begin in books","To reject dated texts entirely","To explain limits of the earliest written evidence","To prove informal language leaves no evidence"]},{"type":"Inference","stem":"How should a familiar-looking borrowed word be interpreted?","opts":["Its source meaning must remain unchanged","Its origin proves complete community history","Its spelling alone establishes ordinary acceptance","Its local use should be checked rather than assumed identical"]}]}', '[2,3,0,2,3]', '["Текст о том, как заимствованные слова приходят в язык, меняются и как их изучают.","«Its meaning can become narrower or broader than in the source language».","Prestige — престиж, социальное уважение.","«The earliest surviving written example does not necessarily mark the first spoken use» — ограничение письменных источников.","Слово может выглядеть похоже, но работать иначе: «look similar while functioning differently in each». Употребление нужно проверять."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-108', 'R', 'rap', 'B', '{"topic":"Physical sciences","title":"Why Flat Maps Distort the Earth","paras":[["A globe represents Earth''s surface on a curved object.","A flat map places that surface on a plane.","Transforming a curved surface in this way cannot preserve every geometric relationship perfectly.","Map projections therefore distribute distortion differently.","A projection may preserve local angles while changing relative areas, or preserve areas while altering shapes.","Choosing a projection means deciding which relationships matter most for the map''s purpose."],["This trade-off can influence interpretation.","If a map enlarges high-latitude regions, viewers may overestimate their size compared with regions nearer the equator.","The map can still be useful for a task that depends on another preserved property.","Calling it simply wrong overlooks the choice involved.","However, using it for area comparisons without recognizing distortion can produce misleading conclusions."],["Cartographers consider scale and geographic extent as well as projection.","A map covering a small region may display little noticeable distortion, while a world map makes the compromises more visible.","Labels, symbols, and color add further decisions about what users will notice.","A map is therefore a designed representation rather than an unfiltered copy of the planet.","Reading one well involves asking what it preserves, what it simplifies, and which questions it was intended to answer.","These questions help users match the representation to their own needs."]],"qs":[{"type":"Factual","stem":"What is the central idea?","opts":["Small-region maps require no design decisions","Map projections involve compromises suited to different purposes","Area distortion makes any map useless","Every flat map preserves all globe relationships"]},{"type":"Factual","stem":"What might an angle-preserving projection alter?","opts":["Relative areas","Every label''s spelling","The Earth''s actual curvature","The existence of the equator"]},{"type":"Vocabulary","stem":"The word \"extent\" in the passage is closest in meaning to","opts":["color selected","direction traveled","accuracy guaranteed","range covered"],"hl":{"p":2,"s":0,"w":"extent"}},{"type":"Rhetorical Purpose","stem":"Why discuss enlarged high-latitude regions?","opts":["To prove those regions are physically growing","To explain why all projections preserve area","To show how distortion can mislead area comparisons","To recommend ignoring a map''s purpose"]},{"type":"Inference","stem":"What should a user consider before comparing countries'' areas?","opts":["Whether the projection preserves area appropriately","Whether the countries appear near one another","Whether the map uses bright colors","Only whether country labels are clear"]}]}', '[1,0,3,2,0]', '["Проекции карт всегда идут на компромисс, и проекцию выбирают под задачу карты.","«A projection may preserve local angles while changing relative areas».","Geographic extent — охват территории, какую область покрывает карта.","Увеличенные высокоширотные районы — пример того, как искажение вводит в заблуждение при сравнении площадей.","Для сравнения площадей нужно знать, сохраняет ли проекция площадь, иначе «misleading conclusions»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-109', 'R', 'rap', 'B', '{"topic":"Life sciences","title":"Upwelling and Ocean Food Supplies","paras":[["Sunlight reaches the upper ocean, where microscopic organisms can use it to produce organic material.","Their growth also requires nutrients.","Surface waters may become depleted as organisms use those nutrients, while deeper water can contain nutrients released by the breakdown of sinking material.","Moving deep water upward can therefore connect two resources that are otherwise partly separated: nutrients below and light above."],["This movement is called upwelling.","In some coastal regions, winds help move surface water away, allowing colder water from below to replace it.","The arriving water can support growth of microscopic producers, which then supply food to other organisms.","A productive food web may develop even though the surface water is comparatively cold.","Temperature alone is thus an incomplete guide to the area''s biological productivity."],["Upwelling varies with winds, currents, and local geography.","Changes in these conditions can alter the timing or strength of nutrient supply.","More nutrients do not guarantee that every population will increase immediately; light, grazing, and other conditions also affect growth.","Scientists study water movement alongside biological observations to understand these connections.","The example shows how a physical process can influence life through the movement of resources.","It also explains why measuring only surface temperature, without considering what the water carries and how organisms respond, can miss an important part of ocean functioning."]],"qs":[{"type":"Factual","stem":"What does the passage mainly explain?","opts":["How winds guarantee immediate population growth","Why cold surface water cannot support food webs","Why nutrients replace the need for sunlight","How upwelling connects nutrient movement with ocean life"]},{"type":"Factual","stem":"What happens in the coastal example?","opts":["Sunlight reaches every depth equally","Surface water becomes permanently motionless","Deeper water replaces displaced surface water","Winds remove all dissolved nutrients"]},{"type":"Vocabulary","stem":"The word \"depleted\" in the passage is closest in meaning to","opts":["carried farther inland","reduced through use","mixed with sand","warmed by sunlight"],"hl":{"p":0,"s":2,"w":"depleted"}},{"type":"Rhetorical Purpose","stem":"Why mention productive but cold surface water?","opts":["To explain why nutrients are always absent","To show temperature has no biological influence","To compare coastal water with drinking water","To challenge temperature as a sufficient productivity guide"]},{"type":"Factual","stem":"Why might more nutrients not immediately increase a population?","opts":["Deep water never contains useful nutrients","Upwelling necessarily blocks all light","All organisms respond at the same speed","Other growth conditions may remain limiting"]}]}', '[3,2,1,3,3]', '["Апвеллинг соединяет питательные вещества глубин со светом у поверхности и поддерживает жизнь в океане.","«Winds help move surface water away, allowing colder water from below to replace it».","Depleted — истощённый, уменьшившийся в результате использования.","Холодная, но продуктивная вода показывает, что температура — неполный ориентир: «Temperature alone is thus an incomplete guide».","«More nutrients do not guarantee… light, grazing, and other conditions also affect growth»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Factual"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-110', 'R', 'rap', 'B', '{"topic":"Art and music","title":"Repeated Patterns in Woven Cloth","paras":[["A woven pattern can be produced by repeating a small arrangement of threads.","The weaver determines how threads cross, which colors appear, and when the arrangement begins again.","A complex-looking surface may therefore emerge from a relatively limited set of actions.","Repetition reduces the need to invent every section independently, but maintaining the pattern still requires attention to sequence and tension."],["The structure of weaving also places constraints on design.","A picture drawn freely on paper may not transfer directly into a cloth pattern because threads form an organized grid.","Designers may simplify curves, adjust proportions, or use stepped edges.","These changes are not necessarily failures to copy an image.","They can be solutions suited to the material and technique.","The visible result reflects both the intended motif and the practical method used to construct it."],["Researchers studying textiles examine the reverse side and the thread structure, not just the front image.","Two cloths that look alike can have different construction methods.","Conversely, similar methods can produce varied surfaces through changes in color and repetition.","Understanding technique helps distinguish visual resemblance from shared production knowledge.","A textile can communicate social meaning through its pattern while also preserving evidence of skilled work.","Looking at how the object was made adds information that a photograph of its decorative surface alone may leave hidden."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["Why complex cloth requires a new action for every thread","How paper drawings transfer without adjustment","How weaving methods shape patterns and their interpretation","Why decoration contains no evidence of technique"]},{"type":"Factual","stem":"Why might a designer use stepped edges?","opts":["Every motif must have equal colors","The cloth has no underlying structure","Curves cannot appear in any art form","The thread grid constrains representation"]},{"type":"Vocabulary","stem":"The word \"motif\" in the passage is closest in meaning to","opts":["design element","repair method","thread weight","display location"],"hl":{"p":1,"s":5,"w":"motif"}},{"type":"Rhetorical Purpose","stem":"Why does the author mention the reverse side?","opts":["To explain why similar cloths must share makers","To show only the reverse has decoration","To show how construction evidence extends beyond the front image","To prove photographs reveal every thread crossing"]},{"type":"Inference","stem":"What cannot be established from visual similarity alone?","opts":["That both contain a visible pattern","That two cloths use the same construction method","That their colors can be compared","That their front surfaces resemble each other"]}]}', '[2,3,0,2,1]', '["Техника ткачества определяет узоры и то, как их интерпретировать.","Нити образуют сетку, поэтому «Designers may simplify curves… or use stepped edges».","Motif — элемент узора, мотив.","Изнанка и структура нитей дают информацию о том, как сделана ткань, сверх лицевой стороны.","«Two cloths that look alike can have different construction methods» — по внешнему сходству нельзя установить одинаковую технику."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-111', 'R', 'rap', 'B', '{"topic":"Life sciences","title":"Birdsong in Noisy Environments","paras":[["Birdsong can carry information to potential mates and rivals, but a signal must be heard to have an effect.","Background noise can interfere with that transmission.","If noise occupies frequencies used by a song, parts of the song may become harder to distinguish.","The problem is not necessarily that the bird has stopped singing.","Its listener may have difficulty separating the song from other sounds."],["Some birds adjust aspects of their songs under noisy conditions.","They may sing more loudly, change timing, or use different frequencies.","Such adjustments can improve transmission in some circumstances, but they may also have costs or limits.","A louder song requires effort, and changing a signal may affect how a listener interprets it.","Different species have different vocal abilities, so a response observed in one species should not automatically be expected in another."],["Researchers compare recordings from quiet and noisy places while considering habitat and population differences.","They may also examine whether an apparent change comes from flexible behavior or from differences between the birds living at each site.","Noise reduction and song adjustment are not equivalent solutions: one changes the environment, while the other changes the signal.","Studying both helps explain communication as an interaction between sender, transmission conditions, and receiver.","Measuring the song alone can overlook the surroundings that determine whether its information reaches another bird."]],"qs":[{"type":"Factual","stem":"What is the main idea?","opts":["Only song volume determines communication","Singing guarantees that every listener hears a signal","All birds use identical responses to noise","Noise affects bird communication and possible song adjustments"]},{"type":"Factual","stem":"How can background noise interfere with a song?","opts":["By preventing all birds from making sound","By removing all potential listeners","By overlapping the frequencies it uses","By making every song louder"]},{"type":"Vocabulary","stem":"The word \"flexible\" in the passage is closest in meaning to","opts":["unable to travel","able to adjust","easy to measure","fixed permanently"],"hl":{"p":2,"s":1,"w":"flexible"}},{"type":"Rhetorical Purpose","stem":"Why distinguish noise reduction from song adjustment?","opts":["To show both change the same physical feature","To prove either method always succeeds","To separate environmental change from signal change","To argue receivers are irrelevant"]},{"type":"Inference","stem":"What should a comparison between two habitats consider?","opts":["An assumption that every species responds identically","Only which recording sounds louder to humans","Bird and habitat differences besides noise","The number of microphones alone"]}]}', '[3,2,1,2,2]', '["Шум мешает птицам общаться, и некоторые виды меняют песню. Реакции у разных видов разные.","«If noise occupies frequencies used by a song, parts of the song may become harder to distinguish».","Flexible behavior — гибкое поведение, способность приспосабливаться.","«One changes the environment, while the other changes the signal» — разделить изменение среды и изменение сигнала.","Учёные учитывают «habitat and population differences» и проверяют, не разные ли птицы живут в каждом месте."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-112', 'R', 'rap', 'B', '{"topic":"History","title":"Writing Surfaces Used More than Once","paras":[["A writing surface can contain evidence of more than one period of use.","When durable materials were valuable, people sometimes removed earlier writing and wrote again on the same surface.","Erasure did not always eliminate every trace.","Faint marks could remain beneath the newer text.","A document with overlapping writing histories may therefore preserve information that is not obvious during ordinary reading."],["Recovering an earlier text requires careful distinction between the different layers.","Differences in ink, handwriting, and orientation can help.","Imaging methods may reveal marks that are difficult to see in normal light, but an enhanced image does not interpret itself.","Researchers must still decide which marks belong together and whether a proposed letter or word is supported.","A gap should not be filled simply because a familiar phrase would fit there."],["The later writing is also historically important.","Reuse can reveal decisions about which texts or materials people considered worth keeping.","However, the removal of a text does not prove that its ideas were rejected.","Practical shortages or routine workshop choices may have motivated reuse.","Studying the surface as an object helps connect the texts with those circumstances.","Instead of treating the newer layer only as an obstacle, scholars can examine how successive uses produced the document that survives.","Its history includes both the lost writing and the decision to write again."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["Why reuse proves rejection of an earlier idea","How imaging automatically translates all writing","Recovering and interpreting multiple uses of writing surfaces","Why erased texts never leave evidence"]},{"type":"Factual","stem":"What can help distinguish writing layers?","opts":["Ink, handwriting, and orientation","The modern reader''s preferred phrase","Only the surface''s total weight","The assumption that all marks form one text"]},{"type":"Vocabulary","stem":"The word \"successive\" in the passage is closest in meaning to","opts":["following one another","having identical meaning","requiring no effort","occurring everywhere"],"hl":{"p":2,"s":5,"w":"successive"}},{"type":"Rhetorical Purpose","stem":"Why is a familiar phrase mentioned?","opts":["To explain the cost of writing materials","To warn against unsupported reconstruction","To recommend replacing missing marks freely","To show every old text uses common phrases"]},{"type":"Inference","stem":"What can erasure alone establish about motive?","opts":["The later text was necessarily more valuable","No single motive can be concluded confidently","The writer opposed every earlier idea","Materials were certainly abundant"]}]}', '[2,0,0,1,1]', '["Текст о том, как восстанавливают и интерпретируют несколько слоёв письма на одной поверхности.","«Differences in ink, handwriting, and orientation can help».","Successive — последовательный, следующий один за другим.","«A gap should not be filled simply because a familiar phrase would fit there» — предупреждение против реконструкции без оснований.","«The removal of a text does not prove that its ideas were rejected. Practical shortages or routine workshop choices may have motivated reuse» — мотив по одному стиранию не установить."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-113', 'R', 'rap', 'B', '{"topic":"Physical sciences","title":"Sediment behind a Dam","paras":[["A river transports particles of different sizes.","When water enters a reservoir and slows, some of those particles settle.","Sediment can therefore accumulate behind a dam instead of continuing downstream.","The dam changes not only the timing of water flow but also the movement of material within the river system.","These two changes can have different consequences for the landscape."],["Accumulation can reduce reservoir storage space over time.","Downstream, a reduced sediment supply may also change how banks and beds develop.","Water released from a dam can still transport material, even when it carries less sediment than before.","The outcome depends on flow conditions, channel form, and the availability of particles downstream.","It is not enough to assume that controlling water automatically controls every process linked to the river."],["Managers may consider several approaches, such as altering releases or moving accumulated sediment.","Each approach has practical limits and can affect other uses of the reservoir.","Removing material requires resources, while release changes may interact with water supply or power generation.","Researchers examine both the reservoir and downstream reaches when assessing an intervention.","A solution that improves storage in one place may not restore sediment movement throughout the system.","The example illustrates why river management requires attention to connected processes and locations, rather than treating a dam as an isolated structure with only a local effect."]],"qs":[{"type":"Factual","stem":"What does the passage mainly explain?","opts":["Why dams affect only water quantity","How dams alter sediment movement across a river system","How reservoirs prevent every downstream change","Why sediment removal has no costs"]},{"type":"Rhetorical Purpose","stem":"Why does sediment settle in a reservoir?","opts":["All river sediment dissolves instantly","Water slows after entering it","The particles become lighter than air","The dam stops every water movement"]},{"type":"Vocabulary","stem":"The word \"intervention\" in the passage is closest in meaning to","opts":["description of a distant location","natural event without management","measurement of particle color","action intended to change conditions"],"hl":{"p":2,"s":3,"w":"intervention"}},{"type":"Rhetorical Purpose","stem":"Why mention water supply and power generation?","opts":["To prove all release changes increase power","To show sediment never affects reservoir use","To illustrate competing considerations in release decisions","To explain why downstream studies are unnecessary"]},{"type":"Inference","stem":"What might an effective local sediment-removal project fail to do?","opts":["Restore sediment transport through the entire river system","Require equipment or labor","Address accumulated material","Increase any reservoir storage space"]}]}', '[1,1,3,2,0]', '["Плотина меняет движение наносов по всей речной системе, а не только поток воды.","«When water enters a reservoir and slows, some of those particles settle».","Intervention — вмешательство, действие с целью изменить условия.","Водоснабжение и выработка энергии — примеры других интересов, которые нужно учитывать при изменении сброса воды.","«A solution that improves storage in one place may not restore sediment movement throughout the system»."]', '["Factual","Rhetorical Purpose","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-114', 'R', 'rap', 'B', '{"topic":"History","title":"Library Access beyond the Collection","paras":[["The presence of books does not by itself make a library accessible.","People must be able to enter, understand its rules, and find material relevant to their needs.","Opening hours may exclude workers who cannot visit during the day.","Membership requirements can create additional barriers.","A library''s social role therefore depends on its organization as well as the number of items on its shelves."],["Changes in services can expand access without immediately enlarging the collection.","Extended hours, guidance from staff, or arrangements for borrowing outside a central building may allow more people to use existing resources.","Such changes require money and planning.","They also raise questions about whose needs receive priority.","A quiet study area and a group activity space may serve different users, and a single room cannot always perform both functions comfortably at once."],["Historians studying libraries compare official aims with evidence of actual use.","A statement welcoming everyone does not prove that every group could participate equally.","Records may reveal who joined, which materials circulated, or which restrictions remained.","Informal experiences can be harder to recover, especially when users left little writing.","A library should thus be understood as both a collection and a set of relationships between an institution and its public.","Examining those relationships helps explain why similar collections can have very different effects in different communities."]],"qs":[{"type":"Factual","stem":"What is the main idea?","opts":["Official aims always describe actual use exactly","Library access depends on institutional arrangements beyond books","Larger collections automatically ensure equal participation","Libraries can serve only one kind of user"]},{"type":"Factual","stem":"What can daytime-only opening hours exclude?","opts":["Workers unable to visit during the day","People borrowing fiction only","Every registered member","All readers seeking quiet"]},{"type":"Vocabulary","stem":"The word \"circulated\" in the passage is closest in meaning to","opts":["were physically repaired","were arranged by color","were excluded permanently","were borrowed and used"],"hl":{"p":2,"s":2,"w":"circulated"}},{"type":"Rhetorical Purpose","stem":"Why compare quiet study and group activities?","opts":["To prove all readers prefer silence","To recommend discarding collections","To show services can involve competing spatial needs","To show no library can host activities"]},{"type":"Inference","stem":"What should a historian do with an inclusive mission statement?","opts":["Ignore membership and borrowing records","Treat it as proof of equal access","Compare it with evidence of actual participation","Assume excluded users left complete accounts"]}]}', '[1,0,3,2,2]', '["Доступность библиотеки зависит от её организации (часы, правила, услуги), а не только от числа книг.","«Opening hours may exclude workers who cannot visit during the day».","Circulated (о материалах библиотеки) — выдавались и были в обращении у читателей.","Тихий зал и пространство для групп нужны разным пользователям: «a single room cannot always perform both functions».","«A statement welcoming everyone does not prove that every group could participate equally» — заявление нужно сравнить с данными о реальном использовании."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-115', 'R', 'rap', 'B', '{"topic":"Business and economics","title":"Reputation in Repeat Transactions","paras":[["In some markets, buyers cannot fully judge quality before purchasing.","A repair may look successful at first but fail later, or a product''s durability may become clear only through use.","Sellers who expect repeat business have a reason to consider those later experiences.","A disappointed buyer may not return and may tell others.","Reputation can therefore influence present behavior through its effect on future opportunities."],["This influence depends on information reaching the right people.","A useful review describes a relevant experience rather than simply repeating a favorable label.","Buyers also need to know whether several comments are independent or copied from one source.","A large number of similar statements may appear persuasive without adding much new evidence.","The visibility of opinions is not the same as their reliability."],["Reputation does not remove the need for other safeguards.","A new seller may provide excellent service before having any established record.","Conversely, a seller with a strong record may perform poorly on a particular occasion.","Buyers can combine reputation with guarantees, inspection, and clear agreements about what is being purchased.","Economists study these arrangements as ways to address incomplete information.","The broader lesson is not that trusted sellers never make mistakes.","It is that expectations about future contact, together with credible information about past performance, can change the incentives surrounding a transaction."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["How reputation influences markets with incomplete quality information","How many copied reviews guarantee quality","Why reputation makes agreements unnecessary","Why new sellers always provide poor service"]},{"type":"Factual","stem":"Why might a seller care about a buyer''s later experience?","opts":["It prevents every product defect","It eliminates all competition","It guarantees immediate inspection","It can affect future business"]},{"type":"Vocabulary","stem":"The word \"credible\" in the passage is closest in meaning to","opts":["very brief","believable","recently purchased","widely copied"],"hl":{"p":2,"s":6,"w":"credible"}},{"type":"Rhetorical Purpose","stem":"Why discuss reviews copied from one source?","opts":["To explain how guarantees are priced","To show all reviews are false","To distinguish opinion volume from independent evidence","To recommend ignoring past performance"]},{"type":"Inference","stem":"What is reasonable when assessing a new seller?","opts":["Lack of reputation does not prove poor quality","Reviews should replace clear agreements","No transaction can be satisfactory","Any guarantee establishes perfect durability"]}]}', '[0,3,1,2,0]', '["Текст о том, как репутация влияет на рынки, где покупатель не может сразу оценить качество.","«Sellers who expect repeat business… A disappointed buyer may not return and may tell others».","Credible — заслуживающий доверия, правдоподобный.","«The visibility of opinions is not the same as their reliability» — много одинаковых отзывов не равно независимым доказательствам.","«A new seller may provide excellent service before having any established record» — отсутствие репутации не доказывает низкое качество."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-116', 'R', 'rap', 'B', '{"topic":"Physical sciences","title":"Echoes and Room Acoustics","paras":[["Sound reaching a listener in a room may have taken several routes.","Some travels directly from the source, while some reflects from walls, ceilings, and other surfaces.","Reflected sound can arrive shortly after the direct sound.","When these arrivals overlap, they can influence clarity and the impression of the space.","A room''s acoustic character therefore depends on more than the loudness of the original source."],["Hard smooth surfaces tend to reflect much sound, while suitable soft or porous materials can absorb some of it.","The amount and placement of absorption matter.","Adding a small panel in one location does not necessarily solve a problem throughout a room.","Furniture, occupants, and the shape of the space also affect sound paths.","The same room may behave differently when empty and when filled with people."],["Acoustic design depends on purpose.","A setting for spoken instructions needs words to remain distinct, while a musical performance may benefit from some sustained reflected sound.","More absorption is not automatically better in every setting.","Designers evaluate how long sound persists and how it is distributed to listeners.","They may test changes before choosing a permanent arrangement.","The challenge is to match sound behavior with the activity, not simply to eliminate every reflection.","Understanding routes and surfaces helps explain why two rooms of similar size can provide very different listening experiences."]],"qs":[{"type":"Factual","stem":"What does the passage mainly explain?","opts":["How reflected sound and room design affect listening","Why equal-sized rooms sound identical","How all reflections must be eliminated","Why loudness alone determines room acoustics"]},{"type":"Factual","stem":"Why can occupancy change a room''s acoustics?","opts":["The original source must change frequency","Every occupied room gains hard walls","People stop sound from traveling directly","People affect absorption and sound paths"]},{"type":"Vocabulary","stem":"The word \"persists\" in the passage is closest in meaning to","opts":["moves outside","continues","becomes visible","loses meaning"],"hl":{"p":2,"s":3,"w":"persists"}},{"type":"Factual","stem":"Why contrast speech and musical performance?","opts":["To show acoustic goals depend on the activity","To recommend identical absorption everywhere","To show music always requires silence","To prove speech needs no direct sound"]},{"type":"Inference","stem":"What should be considered before adding absorption?","opts":["Only whether a panel looks attractive","An assumption that more absorption is always better","Only the source''s advertised loudness","The listening purpose and the room''s existing behavior"]}]}', '[0,3,1,0,3]', '["Текст объясняет, как отражённый звук и устройство комнаты влияют на то, что слышит слушатель.","«Furniture, occupants, and the shape of the space also affect sound paths. The same room may behave differently when empty and when filled».","Persists — продолжается, сохраняется (как долго звучит звук).","Для речи нужна разборчивость, а музыке полезно немного отражённого звука: цель зависит от назначения помещения.","«More absorption is not automatically better… The challenge is to match sound behavior with the activity»."]', '["Factual","Factual","Vocabulary","Factual","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-117', 'R', 'rap', 'B', '{"topic":"Life sciences","title":"Volunteer Observations in Science","paras":[["Volunteer observers can help researchers collect information across places that a small professional team could not visit frequently.","They may record birds, plants, or local weather using a shared method.","Many observations can reveal patterns over a wide area.","However, increasing the number of records does not automatically make them representative.","Where volunteers live and when they are available affect what is observed."],["A popular park may receive many reports while a remote area receives few.","Differences in recorded species could then reflect differences in observation effort as well as differences in nature.","Clear instructions can reduce some inconsistency, and training can help people identify what they see.","Researchers may also ask observers to record time spent searching, including visits when nothing relevant was found.","Such information helps interpret both presence and absence in the records."],["Volunteer projects are most useful when participation and scientific design support each other.","Instructions that are too demanding may discourage observers, while instructions that are too vague may produce difficult-to-compare data.","Researchers need to balance these concerns and explain how reports will be used.","Feedback can help volunteers improve future observations.","The resulting dataset is neither worthless because volunteers collected it nor automatically reliable because it is large.","Its usefulness depends on the method, the coverage, and the care taken when drawing conclusions."]],"qs":[{"type":"Factual","stem":"What is the central idea?","opts":["Volunteer data are useful when collection and coverage are evaluated","Training removes every geographic bias","Only professional observations can be useful","Large volunteer datasets guarantee representative results"]},{"type":"Factual","stem":"Why record time spent searching?","opts":["To rank volunteers by their addresses","To help account for observation effort","To guarantee finding a species","To remove all empty reports"]},{"type":"Vocabulary","stem":"The word \"representative\" in the passage is closest in meaning to","opts":["reflecting the wider situation adequately","easy to publish","collected only by experts","containing many photographs"],"hl":{"p":0,"s":3,"w":"representative"}},{"type":"Rhetorical Purpose","stem":"Why compare a popular park with a remote area?","opts":["To explain why training is unnecessary","To illustrate uneven observation coverage","To show remote reports must be rejected","To prove species prefer all popular parks"]},{"type":"Inference","stem":"What could fewer reports from one area mean?","opts":["Certain absence of the recorded organisms","A complete record of local conditions","Less observation rather than fewer organisms","Better identification training there"]}]}', '[0,1,0,1,2]', '["Данные волонтёров полезны, если оценивать метод сбора и охват территории.","Время поиска помогает учесть «observation effort» и правильно понимать отсутствие находок.","Representative — репрезентативный, адекватно отражающий общую картину.","Популярный парк и удалённый район показывают неравномерный охват наблюдениями.","Различия могут отражать «differences in observation effort as well as differences in nature» — меньше отчётов может значить меньше наблюдений."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-118', 'R', 'rap', 'B', '{"topic":"Life sciences","title":"Life on Newly Exposed Rock","paras":[["A bare rock surface may appear to offer little opportunity for life.","Yet organisms such as lichens can occupy some exposed surfaces under suitable conditions.","A lichen involves a fungus living in association with a photosynthetic partner.","The partners'' combined activity allows growth in places where many larger plants cannot immediately establish.","The surface is therefore not necessarily biologically empty simply because it lacks visible soil and vegetation."],["As organisms grow and die, they can contribute organic material.","Weathering and particles arriving from elsewhere also help create small pockets in which other organisms may settle.","Over time, the available habitats can change.","This process should not be imagined as an identical sequence occurring everywhere.","Moisture, temperature, rock properties, and nearby sources of colonists influence which organisms arrive and how quickly conditions develop."],["Researchers studying such changes compare surfaces of different ages, but age is not the only relevant difference.","An older surface in a dry exposed location may support less growth than a younger sheltered one.","Observations across sites need to consider those conditions.","The study of early colonization reveals how organisms interact with physical environments rather than simply waiting for a finished habitat to appear.","It also shows why a surface''s current appearance reflects both its history and the ongoing exchange of material and life with its surroundings."]],"qs":[{"type":"Factual","stem":"What is the passage mainly about?","opts":["How every site follows an identical sequence","How organisms colonize exposed rock under varying conditions","Why surface age determines growth alone","Why bare rock always remains lifeless"]},{"type":"Factual","stem":"What partners are described in a lichen?","opts":["A fungus and a photosynthetic organism","A tree and a burrowing animal","A rock and a water drop","Two large flowering plants"]},{"type":"Vocabulary","stem":"The word \"colonists\" in the passage is closest in meaning to","opts":["tools used for weathering","particles leaving a surface","people measuring rock age","organisms arriving to establish themselves"],"hl":{"p":1,"s":4,"w":"colonists"}},{"type":"Rhetorical Purpose","stem":"Why compare an older dry surface with a younger sheltered one?","opts":["To establish that older rocks contain no organisms","To show environmental conditions can outweigh age","To prove shelter always stops growth","To eliminate comparisons between sites"]},{"type":"Factual","stem":"What may support later establishment of other organisms?","opts":["Age increasing without any environmental change","New material and habitat pockets formed over time","The removal of all early organisms'' remains","An assumption that every sequence is identical"]}]}', '[1,0,3,1,1]', '["Текст о том, как организмы заселяют голую скалу и как от условий зависит скорость этого процесса.","«A lichen involves a fungus living in association with a photosynthetic partner».","Colonists — организмы-колонизаторы, прибывающие и закрепляющиеся на новом месте.","Старая сухая поверхность может поддерживать меньше жизни, чем молодая защищённая: условия важнее возраста.","«Organisms… contribute organic material. Weathering and particles… help create small pockets in which other organisms may settle»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Factual"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-119', 'R', 'rap', 'B', '{"topic":"History","title":"Preserving a Shipwreck underwater","paras":[["A shipwreck can remain underwater for a long time, but seawater does not preserve every part equally.","Wood, metal, cloth, and other materials respond differently to their surroundings.","Water movement can expose or bury objects, while organisms and chemical processes can alter them.","A wreck is therefore an archaeological site undergoing change, not a sealed container in which the moment of sinking remains untouched."],["Burial in sediment can limit some kinds of disturbance and change exposure to oxygen.","However, protection depends on the material and local conditions.","An object uncovered by a storm may begin experiencing a different environment.","Researchers document positions and surrounding sediments because those relationships can help explain what has survived.","Removing an object also changes its conditions.","A material stable underwater may require careful treatment after being brought into air."],["Excavation decisions involve more than deciding which object would look attractive in a museum.","Leaving material in place can preserve relationships that removal would disrupt, while recovering an endangered object may prevent its loss.","Neither choice is automatically best in every case.","Archaeologists weigh research value, site threats, and the resources available for long-term care.","The example shows that finding an object and preserving its information are different achievements.","Understanding a wreck requires attention to the environment, the arrangement of evidence, and what happens after an investigation begins."]],"qs":[{"type":"Factual","stem":"What is the main idea?","opts":["Seawater keeps every wreck material unchanged","Every recovered object remains stable in air","All underwater objects should immediately enter museums","Shipwreck preservation depends on environment and investigation choices"]},{"type":"Factual","stem":"What can a storm do to a buried object?","opts":["Guarantee permanent preservation","Restore its original position exactly","Expose it to different conditions","Remove the need for documentation"]},{"type":"Vocabulary","stem":"The word \"disrupt\" in the passage is closest in meaning to","opts":["repeat","protect","disturb","identify"],"hl":{"p":2,"s":1,"w":"disrupt"}},{"type":"Rhetorical Purpose","stem":"Why discuss treatment after recovery?","opts":["To recommend recovery based only on appearance","To prove objects become stronger automatically in air","To show removing an object changes its preservation needs","To show sediment records are unnecessary"]},{"type":"Factual","stem":"What should influence a recovery decision?","opts":["The assumption that finding equals preserving","A belief that all materials respond identically","Only an object''s display appeal","Site threats and resources for continued care"]}]}', '[3,2,2,2,3]', '["Сохранность затонувшего судна зависит от среды и от решений исследователей.","«An object uncovered by a storm may begin experiencing a different environment».","Disrupt — нарушать, разрушать (связи между находками).","«Removing an object also changes its conditions. A material stable underwater may require careful treatment» — после подъёма нужны новые меры сохранности.","«Archaeologists weigh research value, site threats, and the resources available for long-term care»."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Factual"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-120', 'R', 'rap', 'B', '{"topic":"Business and economics","title":"Measuring Output and Work Quality","paras":[["A workplace may count completed tasks to evaluate performance.","Such a measure is easy to compare, but it may omit important aspects of the work.","Ten quickly completed repairs are not necessarily better than eight reliable ones.","If defects require later correction, the apparent gain in output may create additional costs.","A useful measure should therefore reflect what the activity is intended to achieve, not only what is easiest to count."],["Introducing a target can also change behavior.","Workers may concentrate on measured tasks and give less attention to unmeasured ones.","This response need not involve dishonesty.","People naturally allocate effort toward what an organization emphasizes.","A measure that originally described work can become a force shaping it.","Managers need to ask whether improved numbers correspond to improved outcomes."],["Combining indicators can provide a fuller view.","Output counts might be considered alongside error rates, customer experience, and time spent on necessary preparation.","More indicators do not automatically solve every problem, because collecting and interpreting them takes effort too.","The goal is a balanced assessment rather than an unlimited list.","Researchers studying productivity distinguish the amount produced from the value and reliability of the result.","This distinction explains why a rising performance figure can be encouraging without being sufficient evidence that the entire workplace is functioning better."]],"qs":[{"type":"Factual","stem":"What does the passage mainly discuss?","opts":["How targets eliminate changes in worker behavior","Why every organization needs unlimited indicators","Why counting tasks is always useless","Why output counts need interpretation alongside quality"]},{"type":"Factual","stem":"What can defects in completed repairs cause?","opts":["Later correction costs","Guaranteed customer satisfaction","Removal of preparation work","An automatic fall in every target"]},{"type":"Vocabulary","stem":"The word \"allocate\" in the passage is closest in meaning to","opts":["double","conceal","examine","distribute"],"hl":{"p":1,"s":3,"w":"allocate"}},{"type":"Rhetorical Purpose","stem":"Why does the author mention unmeasured tasks?","opts":["To prove workers are necessarily dishonest","To show how targets can redirect attention","To identify the fastest repair method","To recommend abandoning all targets"]},{"type":"Inference","stem":"What does a rising completed-task count alone establish?","opts":["Equal attention to all necessary tasks","Certain improvement in every work outcome","Only part of the evidence about overall performance","The disappearance of errors"]}]}', '[3,0,3,1,2]', '["Число выполненных задач нужно интерпретировать вместе с качеством работы.","«If defects require later correction, the apparent gain in output may create additional costs».","Allocate effort — распределять усилия.","Неизмеряемые задачи упомянуты, чтобы показать, как цели перенаправляют внимание работников.","Рост показателя «can be encouraging without being sufficient evidence that the entire workplace is functioning better» — это только часть картины."]', '["Factual","Factual","Vocabulary","Rhetorical Purpose","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-003', 'R', 'rap', 'C', '{"topic":"Life sciences","title":"Sleeping with Half a Brain","paras":[["Most land mammals sleep with both halves of the brain at once, but several marine mammals do something unusual.","Bottlenose dolphins can rest one hemisphere of the brain while the other remains alert.","During this state, called unihemispheric sleep, the eye connected to the waking hemisphere often stays open.","The animal can therefore continue to surface for air and watch for predators while still obtaining rest."],["Researchers first documented the pattern by recording electrical activity on both sides of the brain.","They found that the slow waves typical of deep sleep appeared on one side only, and that the two sides alternated over several hours.","Similar recordings have since been made in seals and in some birds.","Ducks resting at the edge of a group, for example, keep the eye facing outward open more often than birds in the center."],["Such findings suggest that sleep is not an all-or-nothing state.","However, unihemispheric sleep may not fully replace ordinary sleep.","Fur seals that sleep this way in water switch to sleeping with both hemispheres when they rest on land, where breathing and predators pose fewer problems.","The ability may thus be a compromise that allows some rest when complete unawareness would be too dangerous."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, what can a dolphin do during unihemispheric sleep?","opts":["Stop breathing for several hours","Keep one eye open and continue surfacing for air","Sleep deeply with both halves of the brain","Remain completely unaware of predators"]},{"type":"Vocabulary","stem":"The word \"alternated\" in the passage is closest in meaning to","opts":["took turns","grew stronger","disappeared","remained equal"],"hl":{"p":1,"s":1,"w":"alternated"}},{"type":"Inference","stem":"What can be inferred about ducks resting at the edge of a group?","opts":["They sleep more deeply than ducks in the center.","They face a greater risk from predators than ducks in the center.","They never close either eye.","They are younger than ducks in the center."]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Fur seals prefer land because breathing in water is impossible for them.","Fur seals sleep with both hemispheres in water and with one hemisphere on land.","Fur seals use one-hemisphere sleep in water but full sleep on land, where the risks are lower.","On land, fur seals stop sleeping because predators are present there."],"simp":{"p":2,"s":2}},{"type":"Rhetorical Purpose","stem":"Why does the author mention fur seals resting on land?","opts":["To show that one-hemisphere sleep may be used only when it is needed","To prove that seals cannot sleep in water","To compare the breathing of seals and dolphins","To explain how brain recordings are made"]}]}', '[1,0,1,2,0]', '["«The eye connected to the waking hemisphere often stays open… continue to surface for air and watch for predators». Остальные варианты противоречат тексту: спит только одно полушарие.","Alternate — чередоваться: полушария по очереди спят и бодрствуют.","Утки с краю чаще держат открытым глаз, смотрящий наружу. Логичный вывод: опасность для них выше, поэтому им нужно следить за хищниками.","Суть: в воде — сон одним полушарием, на суше — обоими, потому что там меньше рисков. Вариант B переворачивает смысл, A и D добавляют то, чего нет в тексте.","На суше морские котики переходят на обычный сон. Пример поддерживает мысль, что сон одним полушарием — компромисс на случай опасности, а не полная замена сна."]', '["Factual","Vocabulary","Inference","Sentence Simplification","Rhetorical Purpose"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-004', 'R', 'rap', 'C', '{"topic":"History","title":"Railway Time","paras":[["Before the middle of the nineteenth century, most towns kept their own local time, setting clocks by the position of the sun.","Noon in one town might arrive several minutes before noon in a town further west.","For travelers on foot or horseback, these small differences hardly mattered, since journeys were slow and schedules were loose."],["Railways changed this situation.","A train moving quickly between towns made local differences visible, and timetables listing many local times confused passengers and staff alike.","More seriously, when trains shared a single track, an error in timekeeping could place two of them on the same section at once.","In Britain, railway companies therefore began to adopt a single standard, usually the time kept at Greenwich, for all of their stations.","Many towns resisted at first, and some public clocks displayed two minute hands, one for local time and one for railway time."],["Over time, the practical advantages of a shared standard outweighed local attachment to solar time.","Standard time spread from railways to telegraph offices, businesses, and eventually the law.","The change illustrates how a technology designed for transport could reshape something as basic as the way communities measured the day."]],"insert":{"p":0,"slots":[0,1,2,3],"sentence":"Even a journey between distant towns took long enough that a few minutes made no practical difference."},"qs":[{"type":"Factual","stem":"According to paragraph 2, why did shared tracks make timekeeping errors dangerous?","opts":["Passengers might miss their trains.","Two trains could end up on the same section at the same time.","Telegraph offices would be forced to close.","Clocks with two minute hands would stop working."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention public clocks with two minute hands?","opts":["To describe a technical improvement in clock design","To show that trains were often late","To explain how Greenwich time was calculated","To illustrate that the change to railway time met resistance"]},{"type":"Reference","stem":"The word \"them\" in paragraph 2 refers to","opts":["towns","trains","passengers","timetables"],"hl":{"p":1,"s":2,"w":"them"}},{"type":"Vocabulary","stem":"The word \"outweighed\" in the passage is closest in meaning to","opts":["were hidden by","were caused by","were greater than","were equal to"],"hl":{"p":2,"s":0,"w":"outweighed"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 1 that indicate where the following sentence could be added. Where would the sentence best fit?","insert":true}]}', '[1,3,1,2,3]', '["«An error in timekeeping could place two of them on the same section at once» — два поезда на одном участке пути.","«Many towns resisted at first, and some public clocks displayed two minute hands» — часы с двумя минутными стрелками показывают сопротивление переходу.","«When trains shared a single track, an error… could place two of them on the same section» — them = trains.","Outweigh — перевешивать: практическая польза оказалась важнее привязанности к местному времени.","Вставка поясняет, почему разница в несколько минут не мешала путешественникам. Она продолжает последнее предложение абзаца («hardly mattered, since journeys were slow»), поэтому стоит в конце."]', '["Factual","Rhetorical Purpose","Reference","Vocabulary","Insert Text"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-005', 'R', 'rap', 'C', '{"topic":"Physical sciences","title":"Boulders Far from Home","paras":[["Scattered across parts of northern Europe and North America are large boulders whose rock type differs completely from the bedrock beneath them.","A block of granite may rest on a plain of limestone, hundreds of kilometers from the nearest granite outcrop.","For a long time, these stones, now called erratics, puzzled observers.","Some proposed that powerful floods had carried them, but water alone seemed unable to move objects weighing many tons over such distances."],["In the nineteenth century, naturalists who studied Alpine glaciers offered another explanation.","They noticed that moving ice picked up rock from valley walls and transported it slowly downhill, depositing it where the ice melted.","If ice sheets had once covered much larger areas, they could have moved erratics across entire regions.","Scratches on exposed bedrock, aligned in the same direction across wide areas, supported this idea."],["Today, geologists use erratics as evidence of past ice movement.","By matching a boulder to its source outcrop, they can reconstruct the direction in which an ice sheet flowed.","Some erratics can even be dated by measuring how long their surfaces have been exposed to cosmic radiation, which indicates roughly when the ice that carried them disappeared."]],"qs":[{"type":"Negative Factual","stem":"According to the passage, all of the following are used as evidence about past ice sheets EXCEPT:","opts":["scratches aligned in the same direction on bedrock","boulders matched to their source outcrops","the exposure of rock surfaces to cosmic radiation","the speed of modern floods"]},{"type":"Vocabulary","stem":"The word \"depositing\" in the passage is closest in meaning to","opts":["breaking apart","leaving behind","measuring","heating"],"hl":{"p":1,"s":1,"w":"depositing"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 1 that explains why the flood explanation seemed unlikely.","sel":{"p":0}},{"type":"Inference","stem":"What can be inferred about the naturalists who studied Alpine glaciers?","opts":["They believed that floods had carried the erratics.","They measured cosmic radiation on boulder surfaces.","They had observed glaciers moving rock in their own time.","They had found erratics only in the Alps."]},{"type":"Factual","stem":"According to paragraph 3, what can measuring a surface''s exposure to cosmic radiation indicate?","opts":["The weight of the boulder","Approximately when the ice carrying it melted away","The type of bedrock beneath it","The speed of ancient floods"]}]}', '[3,1,3,2,1]', '["Царапины, сопоставление валунов с источником и космическое излучение названы в тексте. Наводнения упоминаются только как отвергнутая гипотеза, и о скорости современных наводнений речи нет.","Deposit — оставлять, откладывать: лёд оставлял камни там, где таял.","Последнее предложение: «water alone seemed unable to move objects weighing many tons over such distances» — вода не могла унести такие тяжёлые камни так далеко.","Они заметили, что движущийся лёд переносит камни («They noticed that moving ice picked up rock»), то есть наблюдали это у современных ледников и перенесли вывод на прошлое.","«…which indicates roughly when the ice that carried them disappeared» — примерно когда растаял лёд."]', '["Negative Factual","Vocabulary","Select the Sentence","Inference","Factual"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-006', 'R', 'rap', 'C', '{"topic":"Social sciences","title":"The Pull of the First Number","paras":[["When people estimate an uncertain quantity, their answers are often influenced by a number they encountered just beforehand, even when that number is plainly irrelevant.","In a well-known experiment, participants first saw a number produced by a spinning wheel and were then asked to estimate a percentage unrelated to it.","Those who had seen a high number gave noticeably higher estimates than those who had seen a low one.","Psychologists call this tendency anchoring."],["One explanation is that people start from the anchor and adjust away from it, but stop adjusting too soon.","Another holds that the anchor makes information consistent with it more accessible in memory, so that people unintentionally search for reasons why the anchor might be close to correct.","These accounts are not mutually exclusive, and different situations may favor one mechanism over the other."],["Anchoring has practical consequences in negotiation.","An opening offer can shape the range within which later proposals are discussed, which is why experienced negotiators sometimes prefer to make the first offer.","Yet the effect is not unlimited.","An extreme anchor may be dismissed as unserious and can damage trust, and experts in a field tend to be somewhat less affected, although rarely immune."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, what did the spinning-wheel experiment demonstrate?","opts":["People ignore numbers produced by chance.","An unrelated number influenced participants'' estimates.","High numbers made participants more accurate.","Participants refused to give estimates after seeing the wheel."]},{"type":"Vocabulary","stem":"The phrase \"mutually exclusive\" in the passage is closest in meaning to","opts":["equally popular","based on the same experiment","difficult to test","unable to be true at the same time"],"hl":{"p":1,"s":2,"w":"mutually exclusive"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["People deliberately search their memory to prove the anchor wrong.","Memory plays no role in anchoring according to this account.","The anchor makes matching information easier to recall, so people find reasons it could be right.","Information that contradicts the anchor becomes easier to recall."],"simp":{"p":1,"s":1}},{"type":"Rhetorical Purpose","stem":"Why does the author mention experienced negotiators?","opts":["To show how anchoring can be used strategically","To prove that experts are immune to anchoring","To describe the spinning-wheel experiment","To argue that negotiations rarely involve numbers"]},{"type":"Inference","stem":"What can be inferred about an extremely high opening offer?","opts":["It always produces the best result for the seller.","It may be ignored and weaken the other side''s trust.","It has no effect on people who are not experts.","It is required in formal negotiations."]}]}', '[1,3,2,0,1]', '["Те, кто видел большое число на колесе, давали более высокие оценки, хотя число не имело отношения к вопросу.","Mutually exclusive — взаимоисключающие. Автор говорит, что оба объяснения могут быть верны одновременно.","Суть: якорь делает «подходящую» информацию доступнее, и человек невольно ищет доводы в его пользу. Вариант A ошибается в deliberately и wrong, D переворачивает смысл.","Опытные переговорщики предпочитают первыми назвать цену — пример того, как якорь используют намеренно.","«An extreme anchor may be dismissed as unserious and can damage trust» — слишком смелое предложение могут не воспринять всерьёз и перестать доверять."]', '["Factual","Vocabulary","Sentence Simplification","Rhetorical Purpose","Inference"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-007', 'R', 'rap', 'C', '{"topic":"Art and music","title":"Painting into Wet Plaster","paras":[["In true fresco, the technique used for many wall paintings in Renaissance Italy, pigments mixed only with water are applied to fresh lime plaster.","As the plaster dries, a chemical reaction with carbon dioxide in the air forms a thin crystalline layer that binds the pigment into the wall itself.","The result can be remarkably durable, since the color becomes part of the surface rather than a coating on top of it."],["The method imposed strict working conditions.","Because plaster remains workable for only a limited number of hours, painters prepared just the area they could finish in a single session, known as a giornata, meaning a day''s work.","Joins between these sections are often visible to conservators today, allowing them to reconstruct the order in which a wall was painted.","Corrections were difficult: altering a finished area usually meant cutting out the plaster and starting again."],["Not every pigment survives the alkaline environment of lime, so certain blues and greens had to be added after the plaster dried, using a binder such as egg or glue.","These additions, painted on dry plaster, have frequently flaked away over the centuries.","As a result, some frescoes now display colors that differ from the original design, which complicates any attempt to judge an artist''s intentions from the surviving surface alone."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"Larger scenes therefore had to be divided into many such patches."},"qs":[{"type":"Factual","stem":"According to paragraph 1, why can true fresco be very durable?","opts":["The pigment is protected by a layer of glue.","The color becomes part of the wall surface.","Painters used only blue and green pigments.","The plaster never dries completely."]},{"type":"Reference","stem":"The word \"them\" in paragraph 2 refers to","opts":["joins","sections","conservators","painters"],"hl":{"p":1,"s":2,"w":"them"}},{"type":"Vocabulary","stem":"The word \"imposed\" in the passage is closest in meaning to","opts":["described","avoided","reduced","required or forced"],"hl":{"p":1,"s":0,"w":"imposed"}},{"type":"Inference","stem":"What can be inferred about the sections called giornate?","opts":["Their edges can reveal the sequence in which a painting was made.","They were painted on dry plaster.","Each one covered an entire wall.","They were added after the wall was finished."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added. Where would the sentence best fit?","insert":true}]}', '[1,2,3,0,1]', '["«The color becomes part of the surface rather than a coating on top of it». Клей использовали как раз для красок a secco, которые осыпаются.","«…visible to conservators today, allowing them to reconstruct the order» — восстанавливают порядок работы реставраторы, them = conservators.","Impose — навязывать, вводить обязательные условия: техника требовала строгого режима работы.","Стыки между участками видны реставраторам и позволяют восстановить порядок росписи, то есть границы giornate показывают последовательность работы.","«Such patches» отсылает к участку giornata, описанному во втором предложении. Вставка идёт сразу после него и перед фразой о стыках между этими участками."]', '["Factual","Reference","Vocabulary","Inference","Insert Text"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-008', 'R', 'rap', 'C', '{"topic":"Life sciences","title":"Underground Partnerships","paras":[["The roots of most land plants are colonized by fungi that form what are known as mycorrhizal associations.","Fine fungal threads extend far beyond the reach of the roots, absorbing water and mineral nutrients such as phosphorus from the soil.","The fungi pass a portion of these resources to the plant, which in return supplies the fungi with sugars produced by photosynthesis."],["Because a single fungus can connect to several plants at once, researchers have proposed that forests contain shared underground networks.","In some experiments, carbon labeled with a traceable isotope moved from one tree to a neighboring tree, apparently through fungal connections.","These results led to popular descriptions of trees that feed their offspring or warn their neighbors of danger."],["Many ecologists, however, consider such descriptions premature.","Detecting a substance in a neighboring plant does not show how much was transferred or whether the transfer benefited the receiver in any measurable way.","Some of the carbon may simply have remained in the fungus.","The partnership between an individual plant and its fungi is well established; the extent and significance of network-wide sharing remain open questions."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, what does a plant provide to its fungal partner?","opts":["Phosphorus","Water","Sugars","Traceable isotopes"]},{"type":"Vocabulary","stem":"The word \"premature\" in the passage is closest in meaning to","opts":["made too early, before enough evidence","based on long experience","widely accepted","completely false"],"hl":{"p":2,"s":0,"w":"premature"}},{"type":"Rhetorical Purpose","stem":"Why does the author mention descriptions of trees that \"feed their offspring\"?","opts":["To prove that trees recognize their offspring","To explain how isotopes are traced","To describe the structure of a fungus","To give an example of popular interpretations that some ecologists question"]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Substances moved between plants always benefit the receiver.","Finding a substance in another plant does not reveal how much moved or whether it helped that plant.","Measuring transfers is impossible because substances cannot be detected.","Neighboring plants never receive substances from each other."],"simp":{"p":2,"s":1}},{"type":"Inference","stem":"Which statement would the author most likely agree with?","opts":["Forest-wide networks have now been fully mapped.","Fungi harm most of the plants they colonize.","Partnerships between individual plants and fungi are better supported than claims about forest-wide sharing.","Isotope experiments prove that trees communicate."]}]}', '[2,0,3,1,2]', '["«…supplies the fungi with sugars produced by photosynthesis». Воду и фосфор, наоборот, гриб даёт растению.","Premature — преждевременный: выводы сделаны раньше, чем накопились доказательства.","Сразу после этого автор пишет: «Many ecologists, however, consider such descriptions premature». Пример показывает популярные трактовки, к которым учёные относятся скептически.","Суть: обнаружение вещества не говорит ни о количестве, ни о пользе. Остальные варианты утверждают то, чего в предложении нет: always, impossible, never.","Последнее предложение: союз отдельного растения с грибом «well established», а масштаб общего обмена в сети «remain open questions»."]', '["Factual","Vocabulary","Rhetorical Purpose","Sentence Simplification","Inference"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-009', 'R', 'rap', 'C', '{"topic":"Business and economics","title":"Guilds and Quality","paras":[["In many medieval European towns, craftsmen in a given trade belonged to a guild, an association that regulated who could practice the craft and how.","Guilds set standards for materials and workmanship, inspected products, and punished members whose goods fell short.","Becoming a full member usually required years as an apprentice and then as a journeyman, followed in some places by the production of a qualifying piece of work."],["Historians have long debated what these rules accomplished.","One view emphasizes consumer protection: buyers often could not judge quality before purchase, and a guild''s collective reputation gave them some assurance.","A competing view stresses that the same rules limited entry into the trade, kept prices high, and protected established masters from competition."],["The two interpretations are not necessarily incompatible.","A regulation that guaranteed a minimum standard could also exclude capable newcomers who lacked connections.","Studies of individual towns suggest that the balance varied: in some places guilds adapted to new techniques, while in others they resisted them.","Evaluating guilds therefore requires attention to local evidence rather than a single verdict about the institution as a whole."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, what was typically required before a craftsman became a full guild member?","opts":["Payment of town taxes only","Years of training as an apprentice and a journeyman","Approval from foreign merchants","Ownership of land in the town"]},{"type":"Vocabulary","stem":"The word \"verdict\" in the passage is closest in meaning to","opts":["record","payment","judgment","question"],"hl":{"p":2,"s":3,"w":"verdict"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that presents a criticism of guild rules.","sel":{"p":1}},{"type":"Inference","stem":"According to the consumer-protection view, why were guild standards valuable?","opts":["They lowered the prices of most goods.","They allowed apprentices to work without pay.","They encouraged the use of new techniques.","Buyers could not easily assess quality before buying."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention that some guilds adapted to new techniques while others resisted them?","opts":["To support the claim that guilds must be judged using local evidence","To prove that guilds always blocked change","To describe how members produced a qualifying piece","To show that consumers preferred older techniques"]}]}', '[1,2,2,3,0]', '["«Becoming a full member usually required years as an apprentice and then as a journeyman».","Verdict — вердикт, окончательное суждение.","Критика — в третьем предложении: правила ограничивали доступ в ремесло, держали цены высокими и защищали мастеров от конкуренции.","«Buyers often could not judge quality before purchase, and a guild''s collective reputation gave them some assurance».","Разное поведение гильдий в разных городах подводит к выводу: «Evaluating guilds therefore requires attention to local evidence»."]', '["Factual","Vocabulary","Select the Sentence","Inference","Rhetorical Purpose"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-010', 'R', 'rap', 'C', '{"topic":"Physical sciences","title":"The Rhythm of Tides","paras":[["Along most coastlines, the sea rises and falls twice each day.","These tides result mainly from the Moon''s gravity, which pulls slightly more strongly on the side of Earth facing it than on Earth''s center, and slightly more on the center than on the far side.","The difference in pull stretches the oceans into two bulges, one facing the Moon and one on the opposite side.","As Earth rotates, a given location passes through both bulges, producing two high tides."],["The Sun produces a similar but weaker effect.","When the Sun and Moon are aligned, at new and full moon, their effects combine to produce especially large spring tides.","When they pull at right angles, the smaller neap tides result.","Spring tides have nothing to do with the season; the name refers to the water springing up."],["Real tides are far more complicated than this simple model suggests.","The shapes of ocean basins, the depth of the water, and the outline of coasts can amplify or suppress the tidal motion.","Some places experience only one high tide a day, and certain bays, where the natural movement of the water matches the tidal rhythm, see ranges of more than ten meters."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, why are there two tidal bulges?","opts":["The Sun and the Moon pull on opposite sides of Earth.","The Moon''s pull differs across Earth, stretching the oceans.","Earth''s rotation pushes water outward at the equator.","Winds pile water up on both sides of Earth."]},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following can influence tides EXCEPT:","opts":["the shape of ocean basins","the depth of the water","the outline of coasts","the season of the year"]},{"type":"Vocabulary","stem":"The word \"amplify\" in the passage is closest in meaning to","opts":["increase","weaken","delay","measure"],"hl":{"p":2,"s":1,"w":"amplify"}},{"type":"Rhetorical Purpose","stem":"Why does the author explain the origin of the name \"spring tides\"?","opts":["To show that spring tides are the weakest tides","To describe how neap tides are formed","To prevent the mistaken idea that they occur in spring","To show that the Sun is stronger than the Moon"]},{"type":"Inference","stem":"What can be inferred about bays with very large tidal ranges?","opts":["They have no tides during neap periods.","Their shape allows the water''s movement to reinforce the tidal rhythm.","They are located only near the equator.","They experience three high tides a day."]}]}', '[1,3,0,2,1]', '["Луна притягивает ближнюю сторону сильнее, а дальнюю слабее. «The difference in pull stretches the oceans into two bulges».","Форма бассейнов, глубина и очертания берегов названы в тексте. О сезоне в абзаце 3 ничего нет, а в абзаце 2 прямо сказано, что spring tides с временем года не связаны.","Amplify — усиливать. В тексте ему противопоставлено suppress — подавлять.","Название легко понять как «весенние приливы». Автор уточняет, что spring здесь — «подниматься, бить ключом».","Огромные приливы бывают там, «where the natural movement of the water matches the tidal rhythm», то есть форма залива усиливает приливное движение."]', '["Factual","Negative Factual","Vocabulary","Rhetorical Purpose","Inference"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-011', 'R', 'rap', 'C', '{"topic":"Social sciences","title":"Losing a First Language","paras":[["People who move to a new country often become highly proficient in its language, sometimes to the point that their first language begins to weaken.","Linguists call this process first-language attrition.","It typically affects vocabulary retrieval before grammar: speakers may hesitate to find a word they once used daily, or borrow a term from their second language, while sentence structure remains largely intact."],["Age at emigration appears to be a crucial factor.","Adults who leave after their early teens usually retain their first language well, even after decades abroad, although they may report feeling less fluent.","Children who emigrate before about the age of ten can experience far more extensive loss, especially if they stop using the language entirely.","In some studies, adults adopted in early childhood performed no better than people who had never been exposed to the language at all."],["Yet such findings do not mean that early knowledge simply vanishes.","When adoptees were trained in sounds from their birth language, some learned to distinguish them faster than comparison groups did, suggesting that traces of early exposure can persist without conscious access.","Attrition, then, may involve reduced accessibility rather than complete erasure."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"Continued contact, such as regular conversations with family, seems to slow this loss considerably."},"qs":[{"type":"Factual","stem":"According to paragraph 1, which part of language is usually affected first?","opts":["Sentence structure","Pronunciation of all sounds","Reading ability","Word retrieval"]},{"type":"Reference","stem":"The word \"them\" in paragraph 3 refers to","opts":["adoptees","sounds","comparison groups","studies"],"hl":{"p":2,"s":1,"w":"them"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["People who emigrate after early adolescence generally keep their first language, though they may feel less fluent.","Adults who live abroad for decades lose their first language completely.","Adults report feeling more fluent after many years abroad.","Only teenagers are able to keep their first language when they emigrate."],"simp":{"p":1,"s":1}},{"type":"Inference","stem":"What do the training studies suggest about adults adopted in early childhood?","opts":["They had never heard their birth language.","They learned the sounds faster than native speakers.","Some knowledge from early exposure remained without conscious awareness.","Their first language was fully restored by training."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added. Where would the sentence best fit?","insert":true}]}', '[3,1,0,2,2]', '["«It typically affects vocabulary retrieval before grammar» — первым страдает поиск слов, а структура предложений почти не меняется.","«Trained in sounds from their birth language, some learned to distinguish them» — различать звуки, them = sounds.","Суть: уехавшие после ранней юности в целом сохраняют язык, хотя могут чувствовать себя менее уверенно. B и C противоречат тексту, D искажает его.","«Traces of early exposure can persist without conscious access» — следы раннего опыта сохраняются, хотя человек их не осознаёт.","«This loss» отсылает к потере языка у детей, которые совсем перестают им пользоваться (третье предложение). Вставка идёт после него: регулярное общение замедляет потерю."]', '["Factual","Reference","Sentence Simplification","Inference","Insert Text"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-012', 'R', 'rap', 'C', '{"topic":"Business and economics","title":"Charging Different Prices","paras":[["Two passengers sitting side by side on the same flight may have paid very different fares.","Economists describe this as price discrimination: charging different customers different prices for essentially the same product, not because costs differ but because customers differ in how much they are willing to pay.","For the seller, the aim is to capture revenue from those who value the product highly without losing customers who would buy only at a lower price."],["To succeed, a firm must be able to separate customers into groups and prevent resale between them.","Airlines achieve this partly through conditions attached to tickets.","Cheaper fares often require booking weeks ahead, conditions that leisure travelers accept more readily than business travelers, whose plans are less flexible.","Because tickets carry the passenger''s name, a traveler who bought cheaply cannot resell the seat to someone willing to pay more."],["The welfare effects of the practice are debated.","It can allow some customers to buy who would otherwise be priced out, and it may help cover the high fixed costs of operating a route.","At the same time, it transfers value from consumers to firms and can seem unfair to those paying the highest prices.","Whether it is beneficial overall depends on the market and on how the prices compare with what a single uniform price would have been."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, why do customers pay different prices under price discrimination?","opts":["Their seats cost different amounts to provide.","They differ in how much they are willing to pay.","They book with different airlines.","Some of them receive lower-quality service."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention that tickets carry the passenger''s name?","opts":["To explain how resale between customer groups is prevented","To show that airlines value security","To describe the flexibility of business travelers","To show that the fixed costs of a route are high"]},{"type":"Vocabulary","stem":"The word \"uniform\" in the passage is closest in meaning to","opts":["changing frequently","extremely low","kept secret","identical for everyone"],"hl":{"p":2,"s":3,"w":"uniform"}},{"type":"Inference","stem":"Why are advance-booking requirements effective at separating customers?","opts":["Leisure travelers prefer expensive tickets.","Airlines lose money on early bookings.","Business travelers often cannot commit to plans far ahead.","Weekend flights are always full."]},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 3 that identifies a possible benefit of price discrimination.","sel":{"p":2}}]}', '[1,0,3,2,1]', '["«…not because costs differ but because customers differ in how much they are willing to pay». Первый вариант — прямая ловушка.","В начале абзаца сказано, что нужно «prevent resale between them». Именной билет — способ это сделать.","A uniform price — единая цена, одинаковая для всех покупателей.","У деловых путешественников «plans are less flexible», поэтому им сложно бронировать заранее, и они платят больше.","Второе предложение: часть людей сможет купить билет, а перевозчик — покрыть постоянные расходы. Третье предложение, наоборот, о недостатках."]', '["Factual","Rhetorical Purpose","Vocabulary","Inference","Select the Sentence"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-013', 'R', 'rap', 'C', '{"topic":"Physical sciences","title":"Measuring the Distance to Stars","paras":[["Hold a finger at arm''s length and look at it first with one eye and then with the other: the finger appears to shift against the background.","Astronomers use the same effect, called parallax, to measure the distances to nearby stars.","As Earth orbits the Sun, a nearby star seems to move slightly relative to much more distant stars, and the size of this shift depends on the star''s distance."],["The shifts are extremely small, which is why they eluded astronomers for centuries.","Their absence was even used as an argument against the idea that Earth moves around the Sun, since a moving Earth should produce observable parallax.","The objection was answered only in 1838, when the first stellar parallax was measured, confirming that the stars lie at distances far greater than earlier thinkers had imagined."],["Ground-based telescopes are limited by the blurring effect of the atmosphere, which restricts parallax measurements to relatively nearby stars.","Space telescopes avoid this problem.","Recent missions have measured the positions of over a billion stars with extraordinary precision, extending direct distance measurements across a large part of our galaxy.","These distances serve as a foundation for other methods that estimate the distances of objects too far away for parallax to detect."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, what determines the size of a star''s parallax shift?","opts":["Its distance from Earth","Its brightness","The size of the telescope","Its temperature"]},{"type":"Vocabulary","stem":"The word \"eluded\" in the passage is closest in meaning to","opts":["were noticed by","escaped detection by","confused","were measured by"],"hl":{"p":1,"s":0,"w":"eluded"}},{"type":"Rhetorical Purpose","stem":"Why does the author mention the argument against Earth''s motion around the Sun?","opts":["To prove that Earth does not move","To explain the blurring effect of the atmosphere","To describe how space telescopes work","To show that the lack of observed parallax was once treated as evidence"]},{"type":"Reference","stem":"The word \"Their\" in paragraph 2 refers to","opts":["astronomers","stars","the shifts","centuries"],"hl":{"p":1,"s":1,"w":"Their"}},{"type":"Inference","stem":"What can be inferred about the importance of parallax distances for faraway objects?","opts":["Parallax can be measured for all galaxies.","They provide a basis for checking other distance methods.","Other methods are no longer needed.","Faraway objects show larger shifts."]}]}', '[0,1,3,2,1]', '["«The size of this shift depends on the star''s distance».","Elude — ускользать: смещения были так малы, что астрономы веками не могли их заметить.","Параллакс не наблюдали, и это считали доводом против движения Земли. Пример показывает, насколько важным было его измерение в 1838 году.","«The shifts are extremely small… Their absence was even used as an argument» — отсутствие наблюдаемых смещений, their = the shifts.","«These distances serve as a foundation for other methods» — для далёких объектов параллакс не работает, но он даёт опору другим методам."]', '["Factual","Vocabulary","Rhetorical Purpose","Reference","Inference"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-014', 'R', 'rap', 'C', '{"topic":"Life sciences","title":"When Coral Turns White","paras":[["Reef-building corals depend on a partnership with single-celled algae that live inside their tissues.","The algae photosynthesize and supply the coral with much of the energy it needs, while the coral provides shelter and nutrients from its waste.","The algae also give many corals their color."],["When water temperatures rise even one or two degrees above the usual summer maximum for several weeks, this partnership can break down.","Stressed algae may produce harmful chemicals, and the coral expels them, leaving its tissue transparent so that the white skeleton shows through.","This process is known as bleaching.","A bleached coral is not dead, but it is starving, and if conditions do not improve, it may die or become more vulnerable to disease."],["Recovery is possible when temperatures return to normal quickly enough for algae to recolonize the coral.","Some corals host heat-tolerant types of algae and bleach less readily, which has led researchers to investigate whether reefs might adapt.","However, adaptation takes time, and bleaching events have become more frequent, shortening the intervals in which reefs can recover before the next episode."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, what do corals receive from the algae?","opts":["Their skeletons","Protection from disease","Much of their energy","Cooler water"]},{"type":"Vocabulary","stem":"The word \"expels\" in the passage is closest in meaning to","opts":["forces out","feeds","protects","repairs"],"hl":{"p":1,"s":1,"w":"expels"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Bleached corals die immediately from disease.","Starving corals cannot bleach unless they are diseased.","Bleaching protects corals from disease if conditions improve.","Bleached corals are still alive but lack food and may die or become ill if conditions stay poor."],"simp":{"p":1,"s":3}},{"type":"Inference","stem":"Why might more frequent bleaching threaten reefs even though recovery is possible?","opts":["Algae disappear permanently after one event.","Reefs may not have enough time to recover between events.","Recovery requires higher temperatures.","Heat-tolerant algae harm corals."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention heat-tolerant types of algae?","opts":["To introduce a possible way reefs could adapt","To prove that bleaching is harmless","To explain where corals get their color","To describe how algae produce harmful chemicals"]}]}', '[2,0,3,1,0]', '["«The algae photosynthesize and supply the coral with much of the energy it needs».","Expel — изгонять, выталкивать: коралл избавляется от водорослей.","Суть: обесцвеченный коралл жив, но голодает и может погибнуть или заболеть. A и C противоречат тексту, B путает причину и следствие.","«…shortening the intervals in which reefs can recover before the next episode» — между эпизодами остаётся слишком мало времени.","Кораллы с термоустойчивыми водорослями обесцвечиваются реже, поэтому учёные изучают, могут ли рифы приспособиться."]', '["Factual","Vocabulary","Sentence Simplification","Inference","Rhetorical Purpose"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-201', 'R', 'rap', 'A', '{"topic":"Life sciences","title":"Why Honeybees Dance","paras":[["When a honeybee finds a good source of flowers, it returns to the hive and performs a short dance.","The dance tells the other bees where to find the food.","Scientists first described this behavior in the 1940s, and their discovery later won a Nobel Prize.","Before then, most people believed that insects could not share such detailed information."],["There are two main types of dance.","If the food is close to the hive, the bee makes a circle.","The circle shows that flowers are nearby, but it does not point in any particular direction.","If the food is far away, the bee performs a figure-eight dance known as the waggle dance.","During the straight middle part, the bee shakes its body quickly from side to side."],["The waggle dance contains two kinds of information.","The angle of the straight part, measured against the vertical wall of the hive, shows the direction of the flowers compared with the sun.","The length of the waggle shows the distance, so a longer waggle means that the flowers are farther away.","Other bees follow the dancer closely and then fly out to look for the flowers themselves."]],"insert":{"p":1,"slots":[1,2,4,5],"sentence":"Which one a bee performs depends on how far away the flowers are."},"qs":[{"type":"Factual","stem":"According to paragraph 1, what did most people believe about insects before the 1940s?","opts":["Bees could not find flowers.","Insects danced only in winter.","Insects could not share detailed information.","Bees used only smell to find the hive."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Reference","stem":"The word \"it\" in the passage refers to","opts":["the circle","the hive","the food","the bee"],"hl":{"p":1,"s":2,"w":"it"}},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following are true of the waggle dance EXCEPT:","opts":["It shows the direction of the flowers.","It shows the distance to the flowers.","Other bees watch it before they fly out.","It tells the bees which kind of flower to choose."]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["The wall of the hive is placed at an angle to show where the sun is.","The straight part of the dance is at an angle that shows where the flowers are in relation to the sun.","The bee measures the angle of the sun to find the straight part of the dance.","The direction of the hive is shown by the position of the flowers and the sun."],"simp":{"p":2,"s":1}}]}', '[2,0,0,3,1]', '["В конце первого абзаца: «most people believed that insects could not share such detailed information». Остальные варианты в тексте не упоминаются.","Вставка начинается с «Which one» — она отсылает к «two main types» в предыдущем предложении и сразу подводит к описанию каждого типа. В другом месте у «Which one» нет понятного антецедента.","«The circle shows that flowers are nearby, but it does not point in any particular direction» — не указывает направление именно круг, поэтому it = the circle.","Тип цветов в третьем абзаце не называется. Направление (угол), расстояние (длина виляния) и то, что другие пчёлы следят за танцем, в тексте есть.","Суть: угол прямой части танца показывает направление на цветы относительно солнца. Остальные варианты меняют, что от чего измеряется."]', '["Factual","Insert Text","Reference","Negative Factual","Sentence Simplification"]', -1, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-202', 'R', 'rap', 'A', '{"topic":"Earth science","title":"How Glaciers Move","paras":[["A glacier is a huge mass of ice that forms over many years in places where snow does not melt completely in summer.","Each year, new snow falls on top of the old snow and presses it down.","Slowly, the lower layers turn into dense ice.","When the ice becomes thick enough, it begins to move."],["Glaciers move in two main ways.","First, the ice itself can bend and flow very slowly, like thick honey, under the weight above it.","Second, a glacier can slide along the ground when a thin layer of water forms at its base.","This water may come from melting caused by pressure or by heat from the ground, and it works like oil between two surfaces.","Because of these two processes, some glaciers move only a few centimeters a day, while fast ones may travel dozens of meters."],["As glaciers move, they change the land around them.","They carry rocks and gravel that scrape the ground like sandpaper.","Over thousands of years, this action can turn a narrow river valley into a wide U-shaped valley.","When a glacier finally melts, it leaves behind piles of rock that it carried, which show scientists where the ice once reached."]],"qs":[{"type":"Vocabulary","stem":"The word \"dense\" in the passage is closest in meaning to","opts":["very cold","tightly packed","completely clear","easily broken"],"hl":{"p":0,"s":2,"w":"dense"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that compares the water under a glacier to something familiar.","sel":{"p":1}},{"type":"Reference","stem":"The word \"it\" in the passage refers to","opts":["the ground","the heat","the pressure","the water"],"hl":{"p":1,"s":3,"w":"it"}},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following are effects of moving glaciers EXCEPT:","opts":["They create new rivers in dry land.","They carry rocks across the land.","They can make a river valley wider.","They leave piles of rock when they melt."]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Scientists melt glaciers to find the rocks that the ice carried.","The rocks that a glacier carries show scientists when the ice will melt.","After a glacier melts, the rocks it left behind show scientists how far the ice used to reach.","A glacier melts only after it has carried all of its rocks to a new place."],"simp":{"p":2,"s":3}}]}', '[1,3,3,0,2]', '["Под давлением снега нижние слои спрессовываются в плотный лёд. Dense = tightly packed, плотный.","Сравнение с привычным предметом — «it works like oil between two surfaces» в четвёртом предложении абзаца. Предыдущее предложение только говорит, что вода образуется.","«This water may come from … and it works like oil» — как масло работает вода. Heat и pressure — ближайшие существительные-ловушки, но они лишь источники воды.","Новые реки в сухих районах в тексте не упоминаются. Перенос камней, расширение долины и оставленные при таянии камни — есть.","Суть: камни, оставшиеся после таяния, показывают, докуда доходил лёд. Остальные варианты меняют причину и следствие."]', '["Vocabulary","Select the Sentence","Reference","Negative Factual","Sentence Simplification"]', -1, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-203', 'R', 'rap', 'B', '{"topic":"Social sciences","title":"Waiting for Two Marshmallows","paras":[["In the late 1960s, the psychologist Walter Mischel tested a simple idea with preschool children at Stanford University.","A researcher placed one marshmallow in front of each child and offered a deal.","If the child could wait alone for about fifteen minutes without eating it, he or she would receive a second marshmallow.","Some children ate the treat almost immediately, while others found clever ways to distract themselves."],["Years later, Mischel and his colleagues followed up with many of the participants.","They reported that children who had waited longer tended to have higher test scores and better social skills as teenagers.","The results spread quickly, and the study became a popular symbol of self-control.","Many parents and teachers concluded that the ability to delay gratification is a key to success."],["More recent research has questioned this conclusion.","In 2018, a team of researchers repeated the experiment with a much larger and more diverse group of children.","They found that the link between waiting time and later achievement was considerably weaker than the original studies suggested.","Once the researchers accounted for the children''s family background, such as parents'' education and income, the connection almost disappeared.","This suggests that a child''s willingness to wait may reflect how reliable the child''s environment is, not just self-control alone."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"However, the original group was small, and most of the children came from families connected with the university."},"qs":[{"type":"Inference","stem":"What can be inferred about the original Stanford studies from paragraph 3?","opts":["They included more children than later research.","They measured family income very carefully.","Their results may not have applied to all kinds of children.","They were repeated by Mischel several times."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 3 that offers a possible explanation for why some children are willing to wait longer.","sel":{"p":2}},{"type":"Negative Factual","stem":"According to paragraph 1, all of the following describe the original experiment EXCEPT:","opts":["Parents stayed in the room to help the children wait.","Each child was left alone with one marshmallow.","A child who waited about fifteen minutes could get a second marshmallow.","The children were tested at a university."]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["The connection disappeared because parents'' education and income were not measured.","Family background became more important to researchers than waiting time.","The researchers ended the study because the children''s backgrounds were too different.","After family background was taken into account, waiting time and later success were hardly connected."],"simp":{"p":2,"s":3}}]}', '[2,3,4,0,3]', '["Повторное исследование использовало «much larger and more diverse group» — значит, исходная группа была меньше и менее разнообразной. Отсюда осторожность в обобщениях.","Вставка с «However» критикует вывод, сделанный в конце абзаца, и подводит к следующему абзацу («More recent research has questioned this conclusion»). Раньше она разорвала бы описание популярности результата.","Объяснение причины даёт последнее предложение: готовность ждать может отражать надёжность среды ребёнка. Остальные предложения описывают результаты.","Дети ждали «alone», родители не присутствовали. Остальные три пункта прямо названы в первом абзаце.","Суть: после учёта семейного фона связь между временем ожидания и успехом почти исчезла. Остальные варианты придумывают другую причину."]', '["Inference","Insert Text","Select the Sentence","Negative Factual","Sentence Simplification"]', 0, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-204', 'R', 'rap', 'B', '{"topic":"Humanities","title":"Moving Type in Korea","paras":[["Many people associate the invention of movable type with Johannes Gutenberg, who printed books in Germany around 1450.","However, printers in Korea had been using metal type for more than two centuries before that.","The oldest surviving book printed with movable metal type is a Korean Buddhist text called the Jikji, produced in 1377.","Its pages were printed from small metal pieces, each carrying a single Chinese character."],["Despite this early start, movable type did not transform Korean society the way it later changed Europe.","One reason was the writing system itself.","Classical texts used thousands of different Chinese characters.","A European printer, by contrast, needed only a few dozen letters, which could be combined to make any word.","Another reason was that printing in Korea was controlled mostly by the government and by temples, which printed small numbers of books for officials and monks."],["Gutenberg''s workshop operated in a very different setting.","He sold books to a growing group of merchants, students, and church leaders who wanted to buy them.","As demand rose, printers across Europe competed to produce books quickly and cheaply, which spread the technology even further.","In this way, the commercial setting mattered at least as much as the invention itself."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"As a result, a printer had to make and store an enormous number of metal pieces."},"qs":[{"type":"Rhetorical Purpose","stem":"Why does the author mention \"a few dozen letters\" in paragraph 2?","opts":["To prove that European printing was older than Korean printing","To show how the writing system affected the difficulty of printing","To explain why Gutenberg moved to Korea","To criticize European books for being too cheap"],"hl":{"p":1,"s":3,"w":"a few dozen letters"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that gives a reason connected to who controlled printing in Korea.","sel":{"p":1}},{"type":"Reference","stem":"The word \"which\" in the passage refers to","opts":["rising demand","printers competing to produce books quickly and cheaply","Gutenberg''s workshop","the growing group of merchants"],"hl":{"p":2,"s":2,"w":"which"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 1? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["The Jikji is the oldest Buddhist text, and it was the first book printed in Korea.","Movable metal type was invented in 1377 in order to print the Jikji.","A Korean book printed in 1377 was lost, so no book printed with metal type survives.","The Jikji, a Korean Buddhist book from 1377, is the oldest remaining book printed with movable metal type."],"simp":{"p":0,"s":2}}]}', '[1,2,4,1,3]', '["Автор противопоставляет алфавит из нескольких десятков букв тысячам иероглифов: так объясняется, почему набор в Корее был сложнее.","«As a result» следует за предложением о тысячах иероглифов, а следующее предложение («A European printer, by contrast») противопоставляет им короткий алфавит. В других местах причинно-следственная связь нарушается.","Печать в Корее контролировали правительство и храмы — об этом последнее предложение абзаца. Остальные предложения про письменность и общий контраст.","Which относится ко всей ситуации: конкуренция печатников, которая и распространила технологию. Ближайшее существительное demand — ловушка.","Суть: «Дзикдзи» (1377) — старейшая сохранившаяся книга, напечатанная подвижным металлическим шрифтом. Другие варианты искажают, что именно старейшее."]', '["Rhetorical Purpose","Insert Text","Select the Sentence","Reference","Sentence Simplification"]', 0, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-205', 'R', 'rap', 'B', '{"topic":"Business and economics","title":"The Box That Changed Shipping","paras":[["Until the 1950s, loading a cargo ship was slow, expensive work.","Goods arrived at the port in barrels, sacks, and wooden crates of every shape and size.","Teams of dockworkers carried each item on board by hand or with simple cranes, and a ship might wait in port for a week or more.","Because loading took so long, ships earned money for only part of the year, and the cost of shipping a product was often higher than the cost of making it."],["In 1956, an American trucking businessman named Malcolm McLean tried a different approach.","He had large steel boxes of one standard shape lifted directly from trucks onto a ship, without opening them.","The cargo stayed sealed inside the container until it reached its destination.","Loading times fell from days to hours, and goods were damaged and stolen far less often."],["Containers soon changed the global economy.","Once other shippers agreed on standard sizes, a container could move easily from a ship to a train or truck.","Ports invested in huge cranes and large storage areas, and many older ports that could not adapt lost business.","As shipping became cheaper, it made sense for companies to manufacture goods in distant countries and sell them everywhere."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"They could also be stacked several layers high, which made better use of space on the ship."},"qs":[{"type":"Vocabulary","stem":"The word \"adapt\" in the passage is closest in meaning to","opts":["change to suit new conditions","become larger","find new customers","stay open longer"],"hl":{"p":2,"s":2,"w":"adapt"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 1 that states a result of slow loading for shipping companies.","sel":{"p":0}},{"type":"Reference","stem":"The word \"them\" in the passage refers to","opts":["the trucks","the dockworkers","the steel boxes","the ports"],"hl":{"p":1,"s":1,"w":"them"}},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following were results of the spread of containers EXCEPT:","opts":["Ports built huge cranes and storage areas.","Containers could move easily between ships, trains, and trucks.","Companies stopped selling goods in distant countries.","Some older ports lost business."]}]}', '[0,1,3,2,2]', '["Старые порты, которые «could not adapt», потеряли бизнес — то есть не смогли приспособиться к новым условиям.","«They» относится к стальным коробкам из предыдущего предложения. После предложения о запечатанном грузе местоимение уже не подходит: рядом нет множественного числа.","Последствие медленной погрузки — суда зарабатывали лишь часть года, а перевозка стоила дороже производства. Это четвёртое предложение абзаца.","«He had large steel boxes … lifted directly from trucks onto a ship, without opening them» — не открывали именно коробки.","Наоборот, перевозка подешевела, и компании стали продавать товары по всему миру. Остальные три пункта прямо названы в третьем абзаце."]', '["Vocabulary","Insert Text","Select the Sentence","Reference","Negative Factual"]', 0, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-206', 'R', 'rap', 'C', '{"topic":"Physical sciences","title":"Why the Night Sky Is Dark","paras":[["At first glance, the darkness of the night sky seems too obvious to need an explanation.","Yet in the nineteenth century, the German astronomer Heinrich Olbers pointed out a puzzle.","If the universe were infinite and filled evenly with stars that have existed forever, every line of sight from Earth would eventually end on the surface of a star.","The entire sky would therefore blaze as brightly as the surface of the Sun, even at midnight."],["Astronomers eventually realized that the puzzle disappears once we accept that the universe has a history.","Light travels at a finite speed, so we can only see objects whose light has had enough time to reach us.","Because the universe is about 13.8 billion years old, light from beyond a certain distance has not yet arrived.","The number of stars that can contribute light to our night sky is therefore limited."],["A second factor is that the universe is expanding.","As distant galaxies move away from us, the light they emit is stretched to longer wavelengths, shifting from visible light toward infrared and microwaves.","Much of this energy is no longer visible to the human eye, even though it still reaches us.","In fact, it forms a faint glow of microwaves detected in every direction, which scientists regard as a remnant of the early universe."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"Beyond that distance, the universe may contain countless stars that we cannot see."},"qs":[{"type":"Inference","stem":"What can be inferred about Olbers'' puzzle from paragraph 1?","opts":["It was based on assumptions that later proved incorrect.","It was solved by Olbers himself.","It showed that stars do not produce light.","It proved that the universe is infinite."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Reference","stem":"The word \"they\" in the passage refers to","opts":["wavelengths","microwaves","human eyes","distant galaxies"],"hl":{"p":2,"s":1,"w":"they"}},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following are true of the expansion of the universe EXCEPT:","opts":["It stretches the light from distant galaxies.","It makes the light of nearby stars much brighter.","It shifts some light out of the range the human eye can see.","It is linked to a faint glow of microwaves detected in every direction."]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 1? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Because stars have existed forever, the universe must be infinite and evenly filled.","In an endless, eternal universe full of stars, any direction we looked would eventually meet a star.","Earth would end up on the surface of a star if the universe were infinite.","Looking in different directions from Earth would show stars that have existed for different lengths of time."],"simp":{"p":0,"s":2}}]}', '[0,2,3,1,1]', '["Загадка строится на условии «если Вселенная бесконечна и вечна». Второй абзац показывает, что Вселенная имеет историю, — значит, исходные допущения были неверны.","«that distance» отсылает к «a certain distance» из предыдущего предложения. Предложение о том, что за этой границей есть невидимые звёзды, естественно ведёт к выводу про ограниченное число звёзд.","«the light they emit» — свет излучают галактики. Wavelengths — ближайшее множественное существительное после they, но оно не излучает свет.","О яркости близких звёзд в третьем абзаце ничего не сказано. Растяжение света, сдвиг за пределы видимого и микроволновое свечение — есть.","Суть: в бесконечной вечной Вселенной любой луч зрения упирался бы в звезду. Другие варианты меняют условие и следствие местами."]', '["Inference","Insert Text","Reference","Negative Factual","Sentence Simplification"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-207', 'R', 'rap', 'C', '{"topic":"Arts","title":"Paint in a Tube","paras":[["Before the middle of the nineteenth century, painters who wanted to work outdoors faced a practical problem.","Oil paint was sold in animal bladders tied with string, and it dried out or spilled when carried from one place to another.","As a result, most artists painted indoors, working from sketches made outside.","Landscapes created in the studio often looked formal and carefully arranged rather than fresh."],["In 1841, the American portrait painter John Goffe Rand patented a collapsible metal tube with a screw cap.","Paint could now be stored for months, squeezed out in small amounts, and sealed again.","The invention was inexpensive to manufacture, and manufacturers soon began filling tubes with a wide range of ready-made colors.","Artists no longer needed to grind pigments by hand with assistants, which had previously required a workshop."],["The result was a new way of painting.","Claude Monet and Pierre-Auguste Renoir carried portable easels into fields and gardens and painted directly from what they saw.","They worked quickly to capture changing light, using short, visible brushstrokes instead of smooth, hidden ones.","Renoir is said to have remarked that without paint in tubes there would have been no Impressionism."]],"qs":[{"type":"Rhetorical Purpose","stem":"Why does the author mention \"animal bladders\" in paragraph 1?","opts":["To show that painters preferred natural materials","To describe how colors were mixed","To argue that tubes were more expensive than bladders","To explain why early oil paint was difficult to carry outdoors"],"hl":{"p":0,"s":1,"w":"animal bladders"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that describes a way the new tubes changed how artists prepared their colors.","sel":{"p":1}},{"type":"Reference","stem":"The word \"They\" in paragraph 3 refers to","opts":["Claude Monet and Pierre-Auguste Renoir","portable easels","fields and gardens","short brushstrokes"],"hl":{"p":2,"s":2,"w":"They"}},{"type":"Negative Factual","stem":"According to paragraph 2, all of the following are true of Rand''s tube EXCEPT:","opts":["It had a cap that could be screwed on.","It allowed paint to be stored for months.","It was designed to be used only by portrait painters.","It was inexpensive to manufacture."]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 1? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Animal bladders were tied with string so that oil paint could dry.","Painters carried string from place to place to tie their bladders.","Oil paint was kept in tied animal bladders, which made it hard to carry because it dried out or spilled.","Oil paint spilled only when animal bladders were not tied with string."],"simp":{"p":0,"s":1}}]}', '[3,3,0,2,2]', '["Автор описывает, как продавалась краска: в связанных пузырях она высыхала или проливалась. Это объясняет, почему художники работали в студии.","Последнее предложение говорит, что художникам больше не нужно растирать пигменты вручную. Предыдущие предложения про хранение и стоимость.","Работали быстро художники, которые вынесли мольберты на природу. Предыдущее предложение содержит несколько существительных-ловушек (easels, fields).","Ограничение «только для портретистов» в тексте не упоминается: Рэнд был портретистом, но трубка использовалась широко. Остальные характеристики названы.","Суть: краска хранилась в пузырях и при переноске высыхала или проливалась. Остальные варианты меняют назначение завязки или причину."]', '["Rhetorical Purpose","Select the Sentence","Reference","Negative Factual","Sentence Simplification"]', 1, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-208', 'R', 'rap', 'C', '{"topic":"Social sciences","title":"The Commons Revisited","paras":[["In 1968, the ecologist Garrett Hardin described a problem that he called the tragedy of the commons.","He asked readers to imagine a pasture open to all the herders in a village.","Each herder gains personally from adding one more animal, but the cost of overgrazing is shared by everyone.","Because every herder reasons in the same way, the pasture is eventually destroyed."],["Hardin concluded that shared resources inevitably collapse unless they are privatized or controlled by a government.","His argument was widely applied to fisheries, forests, and the atmosphere.","Yet the political scientist Elinor Ostrom, who studied communities around the world, found many cases that did not fit his prediction.","Mountain villages in Switzerland, for example, have managed shared pastures for centuries."],["According to Ostrom, successful communities share certain features.","Members clearly know who is allowed to use the resource, and they create rules that suit local conditions.","Those who break the rules are monitored and receive penalties that start small and increase for repeated violations.","Ostrom received the Nobel Prize in Economics in 2009 for showing that people can often solve such problems without relying on either markets or central authorities."]],"insert":{"p":0,"slots":[1,2,3,4],"sentence":"Every herder therefore has a reason to add more animals."},"qs":[{"type":"Inference","stem":"What can be inferred about Hardin''s argument from paragraph 2?","opts":["It overlooked communities that managed shared resources successfully.","It was proven correct by Ostrom''s research.","It was ignored by policy makers.","It applied only to pastures."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 1 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that gives a specific example of a community that contradicts Hardin''s prediction.","sel":{"p":1}},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following are features of successful communities EXCEPT:","opts":["Members know who is allowed to use the resource.","Rules are suited to local conditions.","Penalties become stronger for repeated violations.","Anyone outside the community may use the resource freely."]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Ostrom won the Nobel Prize because she proved that markets and governments always fail.","Ostrom won the 2009 Nobel Prize in Economics for showing that communities can often manage such problems without markets or governments.","In 2009, Ostrom showed that people rely on markets and central authorities to solve problems.","The Nobel Prize in Economics was created in 2009 to honor Ostrom''s work."],"simp":{"p":2,"s":3}}]}', '[0,2,3,3,1]', '["Остром нашла «many cases that did not fit his prediction» — значит, аргумент Хардина не учитывал успешные общины. Он применялся и к рыболовству, лесам, атмосфере.","«therefore» требует причины перед собой (выгода каждого пастуха), а следующее предложение («reasons in the same way») ссылается на это рассуждение. Поэтому вставка идёт после третьего предложения.","Конкретный пример — горные деревни Швейцарии, веками управляющие общими пастбищами. Предыдущее предложение лишь утверждает, что такие случаи есть.","В тексте члены общины чётко знают, кому разрешено пользоваться ресурсом, то есть доступ для всех открыт не был. Остальные признаки названы в абзаце.","Суть: премия за доказательство, что люди часто решают такие проблемы без рынка и центральной власти. Остальные варианты искажают причину награды."]', '["Inference","Insert Text","Select the Sentence","Negative Factual","Sentence Simplification"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-209', 'R', 'rap', 'C', '{"topic":"Life sciences","title":"Underground Partners","paras":[["Beneath a forest floor lies a vast network of fine fungal threads that connect to the roots of nearly all plants.","This partnership, known as a mycorrhiza, benefits both sides.","The fungus extends the plant''s reach into the soil, absorbing water and minerals such as phosphorus that roots could not easily gather alone.","In exchange, the plant supplies the fungus with sugars produced through photosynthesis."],["Some researchers have proposed that these fungal threads also link trees to one another, forming what has been called a wood-wide web.","In laboratory experiments, carbon atoms taken up by one tree have later been detected in neighboring trees.","Supporters suggest that older, larger trees might use the network to send resources to shaded seedlings, improving the young trees'' chance of survival.","Such interpretations have attracted enormous public interest."],["Other scientists urge caution.","They point out that evidence of carbon moving between plants does not show that the transfer is intended to help the recipient or that it makes a significant difference in a natural forest.","The fungus itself might retain much of the carbon, and seedlings may survive mainly because of the light and water around them.","Most researchers agree that the networks exist, but how much they shape forest life remains an open question."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"These results suggested that trees might exchange resources through the fungi."},"qs":[{"type":"Vocabulary","stem":"The word \"retain\" in the passage is closest in meaning to","opts":["produce","keep","transfer","measure"],"hl":{"p":2,"s":2,"w":"retain"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 3 that offers an alternative explanation for why seedlings survive.","sel":{"p":2}},{"type":"Reference","stem":"The phrase \"Such interpretations\" in the passage refers to","opts":["descriptions of how fungi absorb minerals","claims that fungi never benefit from plants","the detection of carbon atoms in laboratory tests","suggestions that trees use fungal networks to help one another"],"hl":{"p":1,"s":3,"w":"Such interpretations"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Carbon moving between plants does not prove that the transfer is meant to help or that it matters much in real forests.","Carbon moves between plants only when the transfer is intended to help the recipient.","The evidence shows that carbon transfer makes a big difference in forests but is not intended.","Scientists doubt that carbon can move between plants at all."],"simp":{"p":2,"s":1}}]}', '[1,1,2,3,0]', '["Гриб может «retain» часть углерода — оставить у себя, а не передать деревьям. Retain = keep.","«These results» относится к лабораторным экспериментам с углеродом из предыдущего предложения. Следующее предложение («Supporters suggest…») развивает эту интерпретацию.","Альтернативное объяснение: сеянцы выживают из-за света и воды вокруг, а не помощи через сеть. Это третье предложение абзаца.","«Interpretations» — это объяснения, а не наблюдения. Речь о предположении, что старые деревья помогают сеянцам через сеть. Само обнаружение углерода — факт, а не интерпретация.","Суть: сам факт перемещения углерода не доказывает ни цели помочь, ни значимости в реальном лесу. Остальные варианты искажают или отрицают сам факт."]', '["Vocabulary","Insert Text","Select the Sentence","Reference","Sentence Simplification"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-210', 'R', 'rap', 'C', '{"topic":"Technology and history","title":"Cards and Looms","paras":[["The origins of modern computing are often traced to machines for arithmetic, but another source was weaving.","In 1804, the French inventor Joseph-Marie Jacquard demonstrated a loom that could weave complicated patterns automatically.","Instead of relying on a skilled worker to choose each thread, the loom read instructions from a chain of cards with holes punched in them.","Where a hole appeared, a hook could pass through and lift a thread; where there was none, the thread stayed down."],["Because the pattern was stored on cards rather than in a person''s memory, it could be changed by replacing the cards.","A weaver could also produce exactly the same design again whenever it was needed.","Some workers feared that the machine would take their jobs, and a few attacked such looms, but the technology spread throughout Europe.","By the middle of the century, tens of thousands of Jacquard looms were in use."],["The idea also attracted the English mathematician Charles Babbage.","In the 1830s he designed the Analytical Engine, a mechanical calculator that was to be controlled by punched cards.","His collaborator Ada Lovelace recognized that such a machine could manipulate not only numbers but any symbols that followed rules, such as music.","Although the machine was never completed, later inventors used punched cards to store data, and they remained in use for computers well into the twentieth century."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"These two features made the loom far more flexible than earlier machines."},"qs":[{"type":"Rhetorical Purpose","stem":"Why does the author mention \"music\" in paragraph 3?","opts":["To suggest that Babbage''s machine could play instruments","To explain why the engine was never completed","To show that Lovelace understood the machine could work with more than numbers","To compare weaving patterns with songs"],"hl":{"p":2,"s":2,"w":"music"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 1 that explains what the presence or absence of a hole in a card caused.","sel":{"p":0}},{"type":"Reference","stem":"The word \"they\" in paragraph 3 refers to","opts":["later inventors","computers","punched cards","Babbage and Lovelace"],"hl":{"p":2,"s":3,"w":"they"}},{"type":"Negative Factual","stem":"According to paragraph 2, all of the following are true of Jacquard looms EXCEPT:","opts":["Workers welcomed them without any opposition.","A pattern could be changed by replacing the cards.","The same design could be produced again.","Tens of thousands were in use by the middle of the century."]}]}', '[2,1,3,2,0]', '["Музыка приведена как пример «любых символов, подчиняющихся правилам»: Лавлейс поняла, что машина способна на большее, чем счёт.","«These two features» — это возможность менять узор заменой карт и повторять тот же рисунок. Оба свойства названы в первых двух предложениях, поэтому вставка идёт после второго.","Последствие наличия или отсутствия отверстия описано в последнем предложении: крючок поднимает нить или нить остаётся внизу.","В использовании оставались перфокарты («punched cards to store data, and they remained in use»). Later inventors — ближайший подлежащий-ловушка.","Часть рабочих боялась потерять работу, а некоторые даже нападали на станки. Остальные три утверждения есть в абзаце."]', '["Rhetorical Purpose","Insert Text","Select the Sentence","Reference","Negative Factual"]', 1, 'pretest', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-211', 'R', 'rap', 'C', '{"topic":"Earth science","title":"The Year Without a Summer","paras":[["In April 1815, the volcano Mount Tambora, on an island in present-day Indonesia, erupted with enormous force.","It threw more than one hundred cubic kilometers of ash and rock into the air, making it the largest eruption in recorded history.","The explosion and its immediate effects killed tens of thousands of people nearby.","However, the most widespread consequences were felt thousands of kilometers away, and they appeared a year later."],["The eruption released large quantities of sulfur gas into the stratosphere, where it combined with water to form tiny droplets.","These droplets reflected some sunlight back into space, reducing the energy that reached the surface of the Earth.","As a result, average temperatures in parts of the Northern Hemisphere fell by as much as one degree Celsius in 1816, which was enough to disrupt the growing season.","Spring frosts were followed by cold, rainy summers, and snow was reported in New England in June."],["Harvests failed across Europe and North America, and food prices rose steeply.","In many regions, farmers faced hunger and some families left their homes to search for food or to start new lives elsewhere.","The gloomy weather also left a mark on culture.","Confined indoors during a stormy summer in Switzerland, the young writer Mary Shelley began the story that became Frankenstein."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"Rain does not reach this layer, so the droplets stay aloft for a long time."},"qs":[{"type":"Factual","stem":"According to paragraph 2, how did the eruption lower temperatures?","opts":["Ash blocked the ocean currents that carry warm water.","Smoke from burning forests covered the surface of the Earth.","The explosion moved the Earth farther from the Sun.","Tiny droplets in the upper atmosphere reflected sunlight back into space."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 3 that links the consequences of the eruption to a work of literature.","sel":{"p":2}},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following were consequences of the cold weather EXCEPT:","opts":["Harvests failed across Europe and North America.","Governments canceled all taxes on farmers.","Food prices rose steeply.","Some families left their homes."]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Temperatures in the Northern Hemisphere rose by one degree in 1816, which disrupted farming.","In 1816, temperatures in some northern regions dropped by up to a degree, enough to interfere with farming.","The growing season lasted a degree longer in 1816 because temperatures fell.","In 1816, the whole Northern Hemisphere became colder by one degree, which stopped all farming."],"simp":{"p":1,"s":2}}]}', '[3,0,3,1,1]', '["Капли серной кислоты в стратосфере отражали часть солнечного света обратно в космос. Остальные причины в тексте не упоминаются.","«this layer» — стратосфера из первого предложения абзаца, а следующее предложение («These droplets reflected…») продолжает рассказ о каплях, которые остаются в воздухе.","Связь с литературой — Мэри Шелли начала «Франкенштейна» летом 1816 года. Это последнее предложение абзаца.","Об отмене налогов в тексте ничего нет. Неурожаи, рост цен и переезд семей названы в третьем абзаце.","Суть: в 1816 году в ряде северных регионов температура упала почти на градус, чего хватило, чтобы нарушить сезон выращивания. Другие варианты меняют знак изменения или преувеличивают."]', '["Factual","Insert Text","Select the Sentence","Negative Factual","Sentence Simplification"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-212', 'R', 'rap', 'C', '{"topic":"Social sciences","title":"When a New Road Makes Traffic Worse","paras":[["Common sense suggests that adding a new road to a congested network should make travel faster.","In 1968, however, the mathematician Dietrich Braess showed that this is not always true.","Under certain conditions, a new road can increase the travel time for every driver in the network.","The result seems paradoxical, but it follows from a simple feature of how people choose their routes."],["Imagine two routes between a suburb and a city center, each with one slow but steady stretch and one fast stretch that becomes crowded when many cars use it.","Drivers divide themselves roughly evenly between the two routes, and each trip takes a similar amount of time.","Now suppose a short connecting road is built that lets drivers combine the two fast stretches.","Each driver, looking only at his or her own journey, finds the new shortcut attractive.","As more drivers switch, the fast stretches become congested, and everyone ends up with a longer trip than before."],["Researchers think that similar effects occasionally occur in real cities.","In 2005, Seoul removed an elevated highway through the city center and replaced it with a stream and park, yet traffic in the area did not collapse as many had feared.","Transportation planners are cautious about drawing general conclusions from such cases.","Nevertheless, the idea reminds them that individual choices can produce results that nobody wants."]],"insert":{"p":1,"slots":[2,3,4,5],"sentence":"In other words, everyone would be better off if the shortcut did not exist."},"qs":[{"type":"Inference","stem":"What can be inferred about the drivers in the example in paragraph 2?","opts":["They are unaware that the new road has been built.","They prefer longer trips to shorter ones.","They are forced by the government to use the shortcut.","They do not consider how their own choices affect other drivers."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that explains why the new road is attractive to individual drivers.","sel":{"p":1}},{"type":"Reference","stem":"The word \"them\" in paragraph 3 refers to","opts":["transportation planners","real cities","researchers","individual choices"],"hl":{"p":2,"s":3,"w":"them"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Seoul built a stream and park in 2005 because traffic had collapsed.","Many people feared that Seoul''s elevated highway would collapse onto the stream in 2005.","Although many people feared a traffic collapse, Seoul''s removal of a central elevated highway in 2005 did not cause one.","In 2005, traffic in Seoul improved because the elevated highway was removed."],"simp":{"p":2,"s":1}}]}', '[3,3,3,0,2]', '["Каждый водитель оценивает только собственную поездку («looking only at his or her own journey»), поэтому не учитывает, что его выбор усиливает пробки для всех.","«In other words» подводит итог: после того, как все выбрали короткий путь, поездки стали дольше. Такой вывод возможен только в конце абзаца, после описания последствий.","Каждый водитель, глядя только на свой маршрут, считает новую дорогу выгодной — это четвёртое предложение абзаца. Предыдущее предложение лишь описывает строительство.","«Transportation planners are cautious… Nevertheless, the idea reminds them» — напоминание адресовано планировщикам из предыдущего предложения.","Суть: опасения коллапса движения после сноса эстакады не оправдались. Вариант про улучшение движения утверждает больше, чем сказано в тексте."]', '["Inference","Insert Text","Select the Sentence","Reference","Sentence Simplification"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-203', 'R', 'rap', 'A', '{"topic":"Technology and history","title":"Making Elevators Safe","paras":[["Before the 1850s, few people wanted to ride in an elevator.","Hoists were used in factories and warehouses, but they were dangerous.","If the rope broke, the platform fell to the ground.","Because of this risk, most buildings had only four or five floors, and the upper floors were cheap to rent."],["An American inventor named Elisha Otis solved the problem.","He designed a safety brake that worked automatically.","When the rope was tight, the brake stayed open.","If the rope broke, strong springs pushed metal bars into the sides of the shaft and stopped the platform.","In 1854, Otis showed his invention at a fair in New York.","He stood on a high platform and ordered a worker to cut the rope.","The platform dropped only a few centimeters and then stopped."],["The demonstration made people trust elevators.","Within a few years, shops and hotels began to install them.","Taller buildings became possible, and the best rooms were now on the upper floors, where the air was fresh and the view was good.","Elevators changed the shape of cities, and they are one reason why modern skylines look the way they do."]],"insert":{"p":1,"slots":[2,4,5,6],"sentence":"Everyone who was watching expected the platform to crash."},"qs":[{"type":"Factual","stem":"According to paragraph 1, why did most buildings have only four or five floors?","opts":["Upper floors were more expensive than lower floors.","Elevators were dangerous to use.","Builders did not have strong rope.","Most people preferred to live near the ground."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Reference","stem":"The word \"them\" in paragraph 3 refers to","opts":["hotels","floors","elevators","people"],"hl":{"p":2,"s":1,"w":"them"}},{"type":"Negative Factual","stem":"According to paragraph 2, all of the following are true of the safety brake EXCEPT:","opts":["It worked automatically.","It used strong springs.","It stopped the platform when the rope broke.","It needed a worker to pull a handle."]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Elevators made tall buildings possible, and the upper floors became the most attractive rooms.","Tall buildings had fresh air, so people wanted to build elevators.","The best rooms were on the upper floors because tall buildings had better views than short ones.","Elevators made the upper floors cleaner, but they did not allow taller buildings."],"simp":{"p":2,"s":2}}]}', '[1,3,2,3,0]', '["В конце первого абзаца: «Because of this risk» — из-за риска падения лифта здания были невысокими, а верхние этажи стоили дёшево. Вариант про дорогие верхние этажи противоречит тексту.","Вставка описывает ожидание зрителей перед падением платформы. Она должна стоять после «ordered a worker to cut the rope» и перед «The platform dropped only a few centimeters». Раньше слово «the platform» не имеет антецедента.","«shops and hotels began to install them» — устанавливали лифты. Shops и hotels — это те, кто устанавливал, а не то, что устанавливали.","Тормоз «worked automatically» — рабочий не нужен. Пружины и остановка платформы при обрыве каната прямо названы в тексте.","Суть: благодаря лифтам стали возможны высокие здания, а лучшие комнаты оказались наверху. Остальные варианты путают причину и следствие."]', '["Factual","Insert Text","Reference","Negative Factual","Sentence Simplification"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-204', 'R', 'rap', 'A', '{"topic":"Life sciences","title":"Why Leaves Change Color","paras":[["In many countries, trees show beautiful red, orange, and yellow colors in autumn.","These colors are not new.","They are in the leaves all year, but in spring and summer we cannot see them.","During those months, leaves are full of chlorophyll, a green substance that helps the tree make food from sunlight.","The green is so strong that it hides the other colors."],["In autumn, the days become shorter and the weather becomes cooler.","The tree begins to prepare for winter.","It stops making chlorophyll, and the green substance slowly breaks down.","As the green disappears, yellow and orange colors that were hidden become visible.","Red colors are different.","Many trees make red substances in autumn, especially when the days are sunny and the nights are cool."],["Scientists are still studying why trees make red colors.","One idea is that the red substance protects the leaf from strong sunlight while the tree takes back useful materials from it.","Eventually the leaf falls, and the tree rests through the winter until spring returns."]],"insert":{"p":1,"slots":[1,3,4,5],"sentence":"Without it, the leaf cannot make food from sunlight."},"qs":[{"type":"Factual","stem":"According to paragraph 1, why can we not see yellow and orange colors in summer?","opts":["The colors do not exist until autumn.","The green color of chlorophyll hides them.","Rain washes them off the leaves.","The leaves are too small to show them."]},{"type":"Vocabulary","stem":"The word \"visible\" in the passage is closest in meaning to","opts":["easy to break","very bright","easy to see","quick to change"],"hl":{"p":1,"s":3,"w":"visible"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that describes when trees make red substances.","sel":{"p":1}},{"type":"Reference","stem":"The word \"it\" in paragraph 3 refers to","opts":["the tree","the sunlight","the red substance","the leaf"],"hl":{"p":2,"s":1,"w":"it"}}]}', '[1,2,1,5,3]', '["В первом абзаце: цвета есть в листьях весь год, но «the green is so strong that it hides the other colors». Вариант «не существуют до осени» противоречит тексту.","Когда зелёный цвет исчезает, жёлтый и оранжевый становятся видимыми. Visible = easy to see.","В вставке «it» — это хлорофилл, поэтому она идёт после предложения «It stops making chlorophyll…». Без хлорофилла лист не может производить пищу. В других местах слову «it» нечего заменять.","Условия, при которых деревья вырабатывают красные вещества, описаны в последнем предложении: солнечные дни и прохладные ночи. Предыдущее предложение («Red colors are different») лишь вводит тему.","«the tree takes back useful materials from it» — дерево забирает полезные вещества из листа. Tree — подлежащее и не может быть тем, откуда забирают."]', '["Factual","Vocabulary","Insert Text","Select the Sentence","Reference"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-205', 'R', 'rap', 'A', '{"topic":"Social sciences","title":"Sharing Bicycles in Cities","paras":[["In the last twenty years, many cities have started bicycle-sharing programs.","A person can take a bicycle from a station, ride to another part of the city, and leave it at a different station.","Users usually pay with a card or a phone, and short trips are often cheap or free.","Some large cities have hundreds of stations."],["City governments have several reasons for starting these programs.","First, bicycles do not make air pollution, so they can help keep the air clean.","Second, they reduce the number of cars on busy streets.","Third, they offer a cheap way to travel for people who cannot afford a car.","Some programs also report that users become healthier because they exercise more."],["However, the programs also face problems.","Bicycles must be moved from stations that are full to stations that are empty, and this work is expensive.","Some bicycles are damaged or stolen.","For these reasons, a program needs careful planning.","Cities that place stations close together and build safe bicycle lanes usually have the most success."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"Fewer cars also mean less noise."},"qs":[{"type":"Negative Factual","stem":"According to paragraph 2, all of the following are reasons for starting bicycle-sharing programs EXCEPT:","opts":["Bicycles are faster than any other kind of transport.","Bicycles do not cause air pollution.","Bicycles reduce the number of cars on streets.","Bicycles are a cheap way to travel."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Reference","stem":"The word \"this\" in paragraph 3 refers to","opts":["building new stations","moving bicycles between stations","paying with a phone","repairing damaged bicycles"],"hl":{"p":2,"s":1,"w":"this"}},{"type":"Inference","stem":"What can be inferred about bicycle-sharing programs from paragraph 3?","opts":["They always earn money for the city.","Most users steal the bicycles.","Their success depends partly on how stations and lanes are planned.","They work only in small cities."]},{"type":"Vocabulary","stem":"The word \"reduce\" in the passage is closest in meaning to","opts":["make faster","make cleaner","make safer","make smaller"],"hl":{"p":1,"s":2,"w":"reduce"}}]}', '[0,2,1,2,3]', '["Скорость в сравнении с другим транспортом во втором абзаце не упоминается. Чистый воздух, меньше машин и дешёвый проезд названы прямо.","«Fewer cars» продолжает мысль предыдущего предложения о сокращении числа машин. Раньше машины ещё не упомянуты, а после слова «Third» речь идёт о дешёвом проезде.","«Bicycles must be moved from stations that are full to stations that are empty, and this work is expensive» — дорогая работа — перемещение велосипедов.","Последнее предложение: успех чаще у городов, где станции стоят близко и есть безопасные дорожки. Значит, результат зависит от планирования.","Велосипеды сокращают число машин на улицах. Reduce = make smaller."]', '["Negative Factual","Insert Text","Reference","Inference","Vocabulary"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-A-206', 'R', 'rap', 'A', '{"topic":"Physical sciences","title":"How a Rainbow Forms","paras":[["A rainbow appears when sunlight passes through drops of water in the air.","Sunlight looks white, but it is really a mixture of many colors.","Each color is a different kind of light.","We usually see rainbows after rain, when the sun comes out while the air is still full of small drops."],["When a ray of sunlight enters a raindrop, it bends.","Different colors bend by different amounts, so the colors separate.","The light then hits the back of the drop and reflects, which means that it bounces back.","When it leaves the drop, it bends again.","Red light leaves at a slightly wider angle than blue light, and this is why red is on the outside of the rainbow and blue is on the inside."],["To see a rainbow, you must stand with the sun behind you and the raindrops in front of you.","Sometimes a second, fainter rainbow appears above the first one.","In the second rainbow, the colors are in the opposite order, because the light reflects twice inside each drop."]],"qs":[{"type":"Factual","stem":"According to paragraph 1, when do we usually see rainbows?","opts":["After rain, when the sun comes out","At night, when the sky is clear","In winter, when the air is very cold","At noon, when the sun is high"]},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 3 that explains why the colors of the second rainbow are in the opposite order.","sel":{"p":2}},{"type":"Reference","stem":"The word \"it\" in paragraph 2 refers to","opts":["the drop","the light","the back","the raindrop"],"hl":{"p":1,"s":2,"w":"it"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Blue light leaves at a wider angle than red light, so blue appears on the outside.","Red and blue light leave at the same angle, which makes the rainbow round.","Because red light leaves the drop at a wider angle than blue light, red appears on the outer edge and blue on the inner edge.","Red appears on the outside of the rainbow because red light bends more than blue light."],"simp":{"p":1,"s":4}},{"type":"Vocabulary","stem":"The word \"fainter\" in the passage is closest in meaning to","opts":["larger","colder","closer","less bright"],"hl":{"p":2,"s":1,"w":"fainter"}}]}', '[0,2,1,2,3]', '["В конце первого абзаца: радуги видны после дождя, когда выходит солнце и в воздухе ещё много капель.","Причина обратного порядка цветов дана в последнем предложении: свет отражается внутри капли дважды. Предыдущее предложение только сообщает, что второй радуги иногда видно.","«The light then hits the back of the drop and reflects, which means that it bounces back» — отскакивает свет. Drop и back — ближайшие существительные, но они не отражаются.","Суть: красный свет выходит под большим углом, поэтому красный цвет снаружи, синий внутри. Остальные варианты меняют цвета местами или добавляют то, чего нет в тексте.","Вторая радуга появляется выше первой и выглядит слабее. Fainter = less bright."]', '["Factual","Select the Sentence","Reference","Sentence Simplification","Vocabulary"]', -1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-206', 'R', 'rap', 'B', '{"topic":"Life sciences","title":"How Bats Find Their Way in the Dark","paras":[["Most bats are active at night, when there is too little light for them to rely on their eyes.","Instead, they use a system called echolocation.","A bat produces a series of short, high-pitched calls, usually too high for humans to hear, and listens carefully for the echoes that return after the sound hits objects.","By measuring how long an echo takes to come back, the bat can judge how far away an object is."],["The pattern of the echo carries more information than distance alone.","A large, smooth surface returns a strong echo, whereas a soft surface such as fur absorbs much of the sound.","The bat can therefore tell the difference between a wall and a branch, and even between different kinds of insects.","When a bat is searching, it calls slowly.","When it detects prey, it calls faster and faster, and in the final moments of the chase the calls form a rapid buzz that gives it a very detailed picture of the target."],["Echolocation is not without difficulties.","In a crowded cave, thousands of bats call at once, yet each bat appears able to pick out its own echoes.","Some moths have evolved ears that detect bat calls, and a few can even produce clicks that confuse the bat.","This continuing competition shows how closely the two groups have shaped each other."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"For example, a bat can recognize a moth by the way its wings change the echo."},"qs":[{"type":"Negative Factual","stem":"According to paragraph 1, all of the following are true of echolocation EXCEPT:","opts":["The calls are low enough for humans to hear easily.","A bat listens for echoes that return.","The time an echo takes shows the distance of an object.","The calls are short and high-pitched."]},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that explains how a bat''s calls change when it finds prey.","sel":{"p":1}},{"type":"Reference","stem":"The word \"its\" in paragraph 3 refers to","opts":["the cave","each bat","thousands of bats","the echo"],"hl":{"p":2,"s":1,"w":"its"}},{"type":"Inference","stem":"What can be inferred about bats in a crowded cave?","opts":["They stop using echolocation.","They call more quietly than moths.","They can separate their own echoes from those of other bats.","They fly only when the cave is empty."]}]}', '[0,2,4,1,2]', '["Звуки «usually too high for humans to hear» — люди их обычно не слышат. Остальные пункты прямо названы в первом абзаце.","«For example» должно следовать за общим утверждением. Оно подходит после «The bat can therefore tell the difference… between different kinds of insects». В других местах пример появился бы раньше, чем сама мысль.","Изменение звуков при обнаружении добычи описано в последнем предложении абзаца: летучая мышь кричит всё чаще, в конце получается быстрый «жужжащий» звук.","«each bat appears able to pick out its own echoes» — свои эхо у каждой мыши. Thousands of bats — множественное число, которое не согласуется с its.","Хотя кричат тысячи мышей, «each bat appears able to pick out its own echoes». Значит, они различают собственные эхо."]', '["Negative Factual","Insert Text","Select the Sentence","Reference","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-207', 'R', 'rap', 'B', '{"topic":"Technology and history","title":"The Telegraph and the Speed of News","paras":[["Before the 1840s, news could travel no faster than a person, a horse, or a ship.","A message from one city to another might take days, and a message across an ocean took weeks.","Merchants, governments, and newspapers all depended on these slow channels, and decisions were often made using information that was already out of date."],["The electric telegraph changed this situation.","A telegraph operator tapped a key to send a pattern of short and long electrical pulses along a wire, and a receiver at the other end turned the pulses into letters.","The best-known system used a code developed by Samuel Morse.","By the 1850s, wires connected most major cities in Europe and North America, and in 1866 a cable across the Atlantic Ocean finally made messages between the continents almost instant."],["The consequences were large.","Newspapers began to publish stories from distant places on the same day.","Traders could compare prices in different markets within minutes, which reduced differences between them.","Because messages were charged by the word, people also learned to write short and efficient sentences, a habit that some writers believe influenced the style of modern news reporting."]],"qs":[{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 1? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Merchants, governments, and newspapers made decisions slowly because they wanted old information.","Slow communication made old information more valuable to governments.","Newspapers decided which communication channels were out of date.","Because they relied on slow communication, people often made decisions using old information."],"simp":{"p":0,"s":2}},{"type":"Negative Factual","stem":"According to paragraph 2, all of the following are true of the telegraph EXCEPT:","opts":["It carried the human voice along a wire.","Operators used a key to send signals.","One well-known system used Morse''s code.","By the 1850s, wires connected many major cities."]},{"type":"Rhetorical Purpose","stem":"Why does the author mention \"a cable across the Atlantic Ocean\"?","opts":["To explain how Morse developed his code","To show how the telegraph eventually connected continents","To argue that ships were no longer needed","To describe an early experiment that failed"],"hl":{"p":1,"s":3,"w":"a cable across the Atlantic Ocean"}},{"type":"Reference","stem":"The word \"them\" in paragraph 3 refers to","opts":["prices","traders","markets","minutes"],"hl":{"p":2,"s":2,"w":"them"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 3 that explains why telegraph users wrote short sentences.","sel":{"p":2}}]}', '[3,0,1,2,3]', '["Суть: из-за медленной связи решения часто принимали на устаревших данных. Остальные варианты меняют причину и следствие.","Телеграф передавал серии коротких и длинных импульсов, превращаемых в буквы, а не человеческий голос. Остальные пункты есть во втором абзаце.","Упоминание кабеля показывает, что в 1866 году телеграф связал континенты и сообщения стали почти мгновенными.","«Traders could compare prices in different markets… which reduced differences between them» — различия между рынками. Prices — ближайшее существительное, но различия сокращались между рынками.","Причина дана в последнем предложении: сообщения оплачивали за слово, поэтому люди учились писать коротко. Остальные предложения описывают другие последствия телеграфа."]', '["Sentence Simplification","Negative Factual","Rhetorical Purpose","Reference","Select the Sentence"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-208', 'R', 'rap', 'B', '{"topic":"Business and economics","title":"Why Free Samples Work","paras":[["Walk through a supermarket on a weekend, and you may find a small table where a worker offers tiny pieces of cheese or sausage.","Companies spend considerable money on such free samples, and they do so for a reason that goes beyond letting customers taste the product.","Marketing researchers have long suspected that a free gift creates a feeling of obligation."],["Psychologists call this feeling reciprocity, the tendency to return a favor.","In one frequently cited experiment, participants who had been given a small gift by a stranger were later more willing to buy raffle tickets from that stranger than participants who had received nothing.","The size of the gift hardly mattered, and the effect appeared even when people disliked the person who gave it."],["Reciprocity does not fully explain the success of samples, however.","Tasting a product also reduces uncertainty, because customers learn immediately whether they like it.","In addition, the pleasant experience may put shoppers in a better mood, which makes them more generous with their money.","Researchers still debate which of these effects is most important, and the answer probably varies from product to product."]],"insert":{"p":2,"slots":[1,2,3,4],"sentence":"For instance, a shopper who dislikes the taste can simply walk away."},"qs":[{"type":"Vocabulary","stem":"The word \"obligation\" in the passage is closest in meaning to","opts":["a sense of surprise","a sense of hunger","a sense of pride","a sense of duty"],"hl":{"p":0,"s":2,"w":"obligation"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that suggests reciprocity does not depend on liking the person who gives the gift.","sel":{"p":1}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 3 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Reference","stem":"The word \"it\" in paragraph 3 refers to","opts":["the product","uncertainty","the supermarket","a favor"],"hl":{"p":2,"s":1,"w":"it"}},{"type":"Inference","stem":"What does the author suggest about the success of free samples?","opts":["It depends only on reciprocity.","It probably has several causes that work together.","It has been fully explained by experiments.","It occurs only with food products."]}]}', '[3,2,1,0,1]', '["Бесплатный подарок создаёт ощущение, что нужно что-то вернуть. Obligation = a sense of duty.","Эффект проявлялся, «even when people disliked the person who gave it». Предыдущее предложение описывает эксперимент, но ничего не говорит о симпатии.","«For instance» приводит пример к предыдущему утверждению: пробник снимает неопределённость, потому что можно сразу узнать, нравится ли продукт. В других местах пример не связан с предыдущей мыслью.","«Tasting a product … customers learn immediately whether they like it» — нравится продукт. Uncertainty — ближайшее существительное, но нравиться может только продукт.","В третьем абзаце названы несколько причин: взаимность, снятие неопределённости и хорошее настроение. Исследователи спорят о значимости каждой, то есть причин несколько."]', '["Vocabulary","Select the Sentence","Insert Text","Reference","Inference"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-B-209', 'R', 'rap', 'B', '{"topic":"Earth science","title":"How Caves Form","paras":[["Many of the world''s largest caves are found in limestone, a rock made mainly from the remains of sea creatures.","Limestone is hard, yet it dissolves slowly in water that is slightly acidic.","Rainwater absorbs carbon dioxide from the air and from the soil, and this makes it weakly acidic."],["As the water seeps down through small cracks in the rock, it dissolves a little of the stone along the way.","Over thousands of years, the cracks widen and join together, forming passages.","When the water table, the level below which the ground is full of water, drops, the passages fill with air and become caves.","Large caves usually take hundreds of thousands of years to develop."],["Once a cave is filled with air, a different process begins.","Water continues to drip from the ceiling, carrying dissolved limestone.","When a drop hangs in the air, a small amount of carbon dioxide escapes from it, and a thin ring of limestone is left behind.","Repeated over centuries, this process builds icicle-shaped stalactites that grow downward from the ceiling.","Drops that fall to the floor can build stalagmites, which rise upward."]],"insert":{"p":2,"slots":[1,2,4,5],"sentence":"The water that formed the cave therefore also decorates it."},"qs":[{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 1? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Limestone dissolves quickly because it is a hard rock.","Water becomes acidic when limestone dissolves in it.","Although limestone is a hard rock, slightly acidic water can gradually dissolve it.","Hard rocks like limestone cannot be dissolved by any kind of water."],"simp":{"p":0,"s":1}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that explains how a cave becomes filled with air.","sel":{"p":1}},{"type":"Reference","stem":"The word \"it\" in paragraph 2 refers to","opts":["the rock","a crack","the stone","the water"],"hl":{"p":1,"s":0,"w":"it"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 3 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following are true of stalactites EXCEPT:","opts":["They grow upward from the floor of the cave.","They hang from the ceiling.","They are built from dissolved limestone.","They take centuries to form."]}]}', '[2,2,3,3,0]', '["Суть: известняк твёрдый, но медленно растворяется в слабокислой воде. Остальные варианты искажают скорость, причину или возможность растворения.","Пещера заполняется воздухом, когда уровень грунтовых вод опускается — это третье предложение абзаца.","«As the water seeps down… it dissolves a little of the stone» — растворяет камень вода. Rock и stone — то, что растворяется.","«Therefore» подводит итог описанного процесса: та же вода, что создала пещеру, теперь её украшает. Такой вывод возможен только после рассказа о сталактитах и сталагмитах, то есть в конце абзаца.","Сталактиты растут вниз от потолка, а вверх растут сталагмиты. Остальные пункты прямо названы в абзаце."]', '["Sentence Simplification","Select the Sentence","Reference","Insert Text","Negative Factual"]', 0, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-213', 'R', 'rap', 'C', '{"topic":"Social sciences","title":"Why Crowds Can Be Wise","paras":[["In 1906, the statistician Francis Galton attended a country fair where visitors were invited to guess the weight of an ox after it had been slaughtered and dressed.","Nearly eight hundred people entered, most of them with no special expertise.","When Galton calculated the middle value of all the guesses, he was surprised to find that it came remarkably close to the true weight, closer than almost any individual estimate, including those from experienced farmers and butchers."],["Later researchers have explained such results through a simple statistical idea.","Each person''s guess contains some useful knowledge and some random error.","When many people make guesses independently, the errors tend to point in different directions and cancel each other out, leaving a more accurate average.","The effect depends on two conditions: the guesses must be made independently, and the group must include a variety of viewpoints."],["When these conditions fail, crowds can perform poorly.","If people see one another''s answers before making their own, early mistakes spread, and everyone drifts toward the same error.","Likewise, a group made up of people with identical backgrounds is likely to share the same blind spots.","The lesson is not that groups are always wiser than experts, but that their judgments are valuable only when each member thinks for himself or herself."]],"insert":{"p":1,"slots":[1,2,3,4],"sentence":"In other words, no single guess needs to be accurate for the average to be accurate."},"qs":[{"type":"Reference","stem":"The word \"it\" in paragraph 1 refers to","opts":["the weight of the ox","the middle value of the guesses","the country fair","the number of entries"],"hl":{"p":0,"s":2,"w":"it"}},{"type":"Insert Text","stem":"Look at the four squares [■] in paragraph 2 that indicate where the following sentence could be added to the passage. Where would the sentence best fit?","insert":true},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that explains why the errors in many guesses tend to disappear.","sel":{"p":1}},{"type":"Negative Factual","stem":"According to paragraph 3, crowds may perform poorly in all of the following situations EXCEPT when","opts":["people can see one another''s answers first","all members have identical backgrounds","each person makes a guess without seeing the others'' answers","early mistakes spread through the group"]},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 3? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Groups are wiser than experts only when each member follows the opinion of the group.","Experts are always wiser than groups because group members do not think for themselves.","The lesson is that every member of a group should be an expert.","Groups are not automatically wiser than experts; their judgments are useful only when members think independently."],"simp":{"p":2,"s":3}}]}', '[1,2,2,2,3]', '["«he was surprised to find that it came remarkably close to the true weight» — близко к истинному весу оказалось усреднённое значение всех догадок.","«In other words» пересказывает предыдущую мысль: ошибки взаимно компенсируются, поэтому не обязательно, чтобы отдельная догадка была точной. Следующее предложение уже вводит новую тему — условия эффекта.","Объяснение даёт третье предложение абзаца: при независимых оценках ошибки направлены в разные стороны и гасят друг друга.","Независимые оценки как раз условие хорошей работы толпы. Остальные три ситуации названы в третьем абзаце как причины плохих результатов.","Суть: группы не всегда мудрее экспертов, их суждения ценны только при независимом мышлении. Остальные варианты искажают смысл."]', '["Reference","Insert Text","Select the Sentence","Negative Factual","Sentence Simplification"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-214', 'R', 'rap', 'C', '{"topic":"Arts","title":"Perspective in Renaissance Painting","paras":[["Medieval European painters rarely tried to show space as the eye sees it.","Figures were often arranged according to their importance rather than their distance, and buildings tilted at angles that could not exist in reality.","In the early fifteenth century, however, Italian artists began to search for a method of representing three-dimensional space convincingly on a flat surface."],["The architect Filippo Brunelleschi is generally credited with demonstrating the principle around 1415.","He observed that parallel lines, such as the edges of a road or the sides of a building, appear to converge as they recede into the distance, meeting at a single vanishing point on the horizon.","A painter who places this point on the canvas and draws all receding lines toward it can create the impression of depth.","In the 1430s, Leon Battista Alberti described the method in writing, and his treatise on painting taught it to a wider group of artists."],["Linear perspective did not simply make paintings more realistic; it changed what a painting was.","Instead of a collection of symbols, the picture became a window through which a viewer looked at a scene from one fixed position.","Some historians argue that this habit of seeing the world from a single point of view shaped other areas of thought, including science and mapmaking, although that claim remains debated."]],"qs":[{"type":"Rhetorical Purpose","stem":"Why does the author mention \"buildings tilted at angles that could not exist in reality\"?","opts":["To illustrate how medieval painting differed from realistic representation","To criticize the architects of medieval Europe","To show that medieval painters lacked all skill","To explain how Brunelleschi designed his own buildings"],"hl":{"p":0,"s":1,"w":"buildings tilted at angles that could not exist in reality"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Parallel lines in real life actually meet at a point on the horizon.","Parallel lines seem to come together at one point on the horizon as they move away from the viewer.","Roads and buildings look smaller than the horizon.","Distant objects are painted on the horizon instead of along the road."],"simp":{"p":1,"s":1}},{"type":"Vocabulary","stem":"The word \"converge\" in the passage is closest in meaning to","opts":["move apart","become shorter","come together","turn darker"],"hl":{"p":1,"s":1,"w":"converge"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 2 that describes how a painter can create the impression of depth.","sel":{"p":1}},{"type":"Reference","stem":"The word \"his\" in paragraph 2 refers to","opts":["Filippo Brunelleschi","a painter","a wider group of artists","Leon Battista Alberti"],"hl":{"p":1,"s":3,"w":"his"}}]}', '[0,1,2,2,3]', '["Пример показывает, что средневековая живопись не стремилась к реалистичному пространству. Автор противопоставляет её поискам итальянских художников XV века.","Суть: параллельные линии кажутся сходящимися в одной точке на горизонте. Вариант про реальную встречу линий неверен — они только кажутся сходящимися.","Параллельные линии кажутся сходящимися в точке схода. Converge = come together.","Способ создать иллюзию глубины описан в третьем предложении: поставить точку схода на холсте и направить к ней все уходящие линии.","«Leon Battista Alberti described the method in writing, and his treatise…» — трактат принадлежит Альберти. Brunelleschi упомянут в начале абзаца и не подходит."]', '["Rhetorical Purpose","Sentence Simplification","Vocabulary","Select the Sentence","Reference"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-215', 'R', 'rap', 'C', '{"topic":"Life sciences","title":"How Bacteria Become Resistant","paras":[["Antibiotics rarely kill every bacterium in a population.","Within a large group of bacteria, individual cells differ slightly in their genes, and a few may happen to have a trait that lets them survive the drug.","When the antibiotic removes the susceptible cells, the survivors face less competition and multiply quickly, so the next generation contains a much higher share of resistant cells."],["Resistance can also spread sideways.","Bacteria can pass small pieces of genetic material to one another, even between different species, so a trait that evolved in one place may appear in organisms that never encountered the drug.","Using antibiotics when they are not needed, for example against viral infections, increases the pressure on bacteria to adapt."],["Because developing new antibiotics is expensive and slow, many experts argue that protecting existing drugs is just as important.","Hospitals monitor how often each drug is prescribed, farmers are being encouraged to reduce routine use in animals, and researchers are exploring treatments that work differently, such as viruses that attack only bacteria.","None of these measures alone is sufficient, but together they may slow the spread of resistance."]],"qs":[{"type":"Select the Sentence","stem":"Select the sentence in paragraph 1 that explains why resistant bacteria become more common.","sel":{"p":0}},{"type":"Inference","stem":"What can be inferred from paragraph 1 about the bacteria in a large population?","opts":["They do not all react to a drug in the same way.","They all become resistant at the same time.","They change their genes because they need to survive.","They cannot multiply when a drug is present."]},{"type":"Reference","stem":"The word \"they\" in paragraph 2 refers to","opts":["bacteria","antibiotics","viral infections","species"],"hl":{"p":1,"s":2,"w":"they"}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["Bacteria of different species cannot share genes, so resistance stays where it evolved.","Resistance appears in organisms that never met the drug because they evolved the same trait independently.","Because bacteria can share genes, even across species, resistance can appear in organisms that were never exposed to the drug.","Bacteria pass genetic material only to members of their own species, which spreads resistance slowly."],"simp":{"p":1,"s":1}},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following are being done to slow resistance EXCEPT:","opts":["Hospitals tracking how often each drug is prescribed","Farmers being encouraged to reduce routine use","Researchers exploring viruses that attack bacteria","Banning every antibiotic in hospitals"]}]}', '[2,0,1,2,3]', '["Рост доли устойчивых бактерий объясняет третье предложение абзаца: после гибели чувствительных клеток выжившие размножаются быстрее.","Клетки «differ slightly in their genes», и лишь у некоторых есть признак, позволяющий выжить. Значит, реакция на препарат у них разная.","«Using antibiotics when they are not needed» — не нужны именно антибиотики. Infections — ближайшее существительное, но оно не подходит по смыслу.","Суть: благодаря обмену генами, в том числе между видами, устойчивость возникает у организмов, не встречавшихся с препаратом. Остальные варианты отрицают обмен или добавляют лишнее.","Полный запрет антибиотиков в больницах в тексте не упоминается. Остальные меры названы во втором предложении абзаца."]', '["Select the Sentence","Inference","Reference","Sentence Simplification","Negative Factual"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('R-RAP-C-216', 'R', 'rap', 'C', '{"topic":"Business and economics","title":"The Sunk Cost Trap","paras":[["Imagine that you have paid for a ticket to a concert, but on the day of the event you feel unwell and the weather is dreadful.","Many people go anyway, reasoning that otherwise the money would be wasted.","Economists point out that this reasoning contains an error.","The ticket price is a sunk cost, money that has already been spent and cannot be recovered whatever you decide, so it should play no part in the choice."],["Yet the pull of sunk costs is strong, and it affects decisions far larger than concert attendance.","Governments continue funding projects that are clearly failing because so much has already been invested.","Companies keep developing products that customers do not want.","In each case, the decision-makers compare the future cost of continuing not with the future benefit but with the amount already lost, and the lost amount makes quitting feel like admitting defeat."],["Researchers suggest several remedies.","One is to ask what a newcomer, who had paid nothing so far, would decide if given the same choice.","Another is to set clear exit conditions before starting, so that stopping later becomes a matter of following a rule rather than admitting a mistake.","Neither approach eliminates the emotional pull, but both can make it easier to recognize when past spending is steering a decision."]],"qs":[{"type":"Rhetorical Purpose","stem":"Why does the author describe a concert ticket in paragraph 1?","opts":["To illustrate the idea of a sunk cost with a familiar situation","To argue that concerts are too expensive","To show that people dislike bad weather","To explain how economists set ticket prices"]},{"type":"Reference","stem":"The word \"it\" in paragraph 2 refers to","opts":["concert attendance","the pull of sunk costs","the amount already spent","the choice"],"hl":{"p":1,"s":0,"w":"it"}},{"type":"Select the Sentence","stem":"Select the sentence in paragraph 3 that describes a way to make stopping easier by deciding in advance.","sel":{"p":2}},{"type":"Sentence Simplification","stem":"Which of the sentences below best expresses the essential information in the highlighted sentence in paragraph 2? Incorrect choices change the meaning in important ways or leave out essential information.","opts":["In these cases, decision-makers compare future costs with future benefits, but the lost amount makes continuing feel like defeat.","Decision-makers continue because the amount already lost makes continuing cheaper than quitting.","In these cases, people judge whether to continue by looking at what they have already lost, and quitting feels like defeat.","Quitting feels like admitting defeat only when the future benefit is smaller than the past cost."],"simp":{"p":1,"s":3}},{"type":"Negative Factual","stem":"According to paragraph 3, all of the following are mentioned as remedies EXCEPT:","opts":["Imagining how a newcomer would decide","Setting exit conditions before starting","Following a rule when it is time to stop","Asking experts to pay for past mistakes"]}]}', '[0,1,2,2,3]', '["Билет на концерт — бытовой пример невозвратных затрат: деньги потрачены и не вернутся, что бы вы ни решили.","«Yet the pull of sunk costs is strong, and it affects decisions far larger» — влияет на решения сила притяжения невозвратных затрат.","Заранее заданные условия выхода описаны в третьем предложении абзаца: остановка превращается в следование правилу, а не в признание ошибки.","Суть: вместо будущей выгоды люди сравнивают с уже потерянной суммой, и уйти кажется поражением. Остальные варианты меняют логику сравнения.","Оплата прошлых ошибок экспертами в тексте не упоминается. Взгляд новичка и заранее заданные условия выхода названы прямо."]', '["Rhetorical Purpose","Reference","Select the Sentence","Sentence Simplification","Negative Factual"]', 1, 'active', 1793652489836, 1793652489836)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = COALESCE(items.cal_level, excluded.level), body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
